  /* ── Algeria (DZ) ── */
  'te.dz.dom.title': 'Domestic Business Trip',
  'te.dz.dom.desc': 'Algeria does not have a legally required per diem rate for private sector employees. Instead, the government sets rates for its own public sector employees under Decree No. 91-500. Private companies can use these as a guide — if you pay within these limits, the amount is generally treated as tax-free for the employee. If you pay more than the ceiling, the excess will be taxed as normal salary income (IRG — Income Tax). All amounts are in Algerian Dinar (DZD).',
