  'te.dz.intl.desc': 'For overseas travel, Algeria uses a zone-based system for public sector employees set by interministerial decree. Private employers are not legally bound by these rates, but the tax authority treats them as the benchmark for tax-free reimbursement. Amounts above the public sector rate may be subject to IRG (Income Tax). Rates are expressed in USD, as is standard practice for international travel in Algeria.',
