  /* ── Argentina (AR) ── */
  'te.ar.dom.title': '国内出差',
  'te.ar.dom.desc': '阿根廷法律并未要求私营部门雇主必须支付每日津贴。政府依据第 333/85 号法令为公共部门员工制定每日津贴标准，并会通过决议定期更新。私营企业通常将这些标准作为参考。\n\n税务处理（《所得税法》第 82 条）：私营雇主支付的每日津贴，仅在有正式票据（comprobantes）作为支持时，方可免征所得税。未提供票据的固定金额津贴将被视为应税雇佣收入。\n\n重要提示：由于阿根廷通货膨胀率较高，阿根廷比索（ARS）标准会频繁调整。以下金额区间反映的是公共部门参考标准，实际适用前应始终查阅最新官方决议。',
  'te.ar.dom.source': '第 333/85 号法令——差旅津贴制度；第 20.628 号《所得税法》第 82 条',
