  'te.ar.intl.title': '国际出差',
  'te.ar.intl.desc': '对于境外出差，公共部门每日津贴标准由第 280/95 号法令规定，并以美元（USD）计价。私营雇主通常参考这些标准，或以美国国务院公布的每日津贴标准作为参考。\n\n注意：阿根廷实行多种汇率制度，以美元计价的津贴实际价值会因采用不同汇率进行兑换而有较大差异。',
