  /* ── Australia (AU) ── */
  'te.au.dom.title': 'Domestic Business Trip — ATO Reasonable Amounts',
  'te.au.dom.desc': 'The ATO publishes \'reasonable amounts\' annually under TD 2025/4. These are SUBSTANTIATION EXCEPTION thresholds — if your employer pays within these limits and you spend it on genuine work travel, you do NOT need to keep every receipt.\n\nKey rules:\n• Must receive a travel ALLOWANCE (not just reimbursement) — must appear on your income statement\n• Must actually spend the money on work travel\n• Overseas trips of 6+ consecutive nights: must keep travel records (diary/itinerary)\n• Accommodation applies ONLY to commercial establishments (hotels, motels, serviced apartments)\n• Meals: only for meals falling within the travel period by time of day\n• Incidentals: apply in full for each day (no part-day apportionment)\n\nSalary bands (salary EXCLUDES allowances received):\n• Table 1: Annual salary up to $148,250\n• Table 2: Annual salary $148,251 to $263,850\n• Table 3: Annual salary $263,851 or more\n• Part-time employees: annualise salary to full-time equivalent\n\nOvertime meal allowance: AUD 38.65 (TD 2025/4, para 6)\nTruck driver meals (all destinations): Breakfast $31.15 | Lunch $35.55 | Dinner $61.30',
  'te.au.dom.source': 'ATO Taxation Determination TD 2025/4 — 2025-26 income year (issued 25 June 2025)',
