  'te.au.intl.title': 'International Business Trip — ATO Reasonable Amounts',
  'te.au.intl.desc': 'TD 2025/4 provides MEALS and INCIDENTALS reasonable amounts only for overseas travel. OVERSEAS ACCOMMODATION must ALWAYS be fully receipted — no reasonable amount applies (TD 2025/4, paragraph 37).\n\nCountries are assigned to one of six cost groups (Table 8 below). Three salary bands apply — same as domestic.\n\nKey rules:\n• If you travel to 2+ countries on the same day, use the higher cost group\n• Countries not listed in Table 8: use Cost Group 3\n• Overseas trips of 6+ consecutive nights: must keep travel records (diary)\n• ECA rates or APSC rates (for subscribers) are also accepted as reasonable',
  'te.au.intl.source': 'ATO Taxation Determination TD 2025/4 — 2025-26 income year (issued 25 June 2025)',
  'te.au.intl.t0.title': 'TABLE 5 — Overseas Travel, Salary ≤ $148,250 (AUD)',
