  /* ── Austria (AT) ── */
  'te.at.dom.title': 'Domestic Business Trip',
  'te.at.dom.desc': 'Austria does not have a single national per diem rate. Instead, rates are governed by collective agreements (Kollektivvertrag) which vary by industry.\n\nUnder the most commonly referenced agreement (Information & Consulting), the minimum daily allowance is €18.40, and the maximum tax-free amount under the Austrian Income Tax Act is €26.40 per day.\n\nThe \'one-twelfth rule\': the daily rate (max €26.40) is divided into 12 equal parts. You earn one part for each hour (or part thereof) of travel beyond 3 hours. Trips of 3 hours or less receive nothing.\n\nTax note: The tax-free cap is €30/day as of 2025 under income tax law. Many collective agreements set a lower practical ceiling (e.g. €26.40). Amounts above the tax-free cap are subject to income tax.\n\nAccommodation: Reimbursed at actual cost with receipts. Without receipts, a flat overnight allowance of €15 is tax-free.',
  'te.at.dom.source': 'WKO Collective Agreement for Information and Consulting (2025); Austrian Income Tax Act (EStG)',
  'te.at.dom.t0.title': 'One-Twelfth Rule — Daily Allowance Calculation (Max €26.40/day)',
  'te.at.dom.t0.h.0': 'Trip Duration',
  'te.at.dom.t0.h.1': 'Tax-Free Max Amount (EUR)',
