  'te.at.intl.title': 'International Business Trips',
  'te.at.intl.desc': 'For international business trips, Austria uses destination-specific flat rates published by the WKO (Austrian Chamber of Commerce).\n\nThree columns apply:\n• Daily Allowance (Tagessatz): covers meals and daily incidentals\n• Overnight Stay (Nächtigungssatz): covers accommodation\n• Differential (Differenzgebühren): additional supplement for certain high-cost cities\n\nAll rates are in EUR. A dash (—) in the Differential column means no supplement applies.',
  'te.at.intl.source': 'Austrian Federal Ministry – WKO Foreign Travel Allowance Rates',
