  /* ── Bangladesh (BD) ── */
  'te.bd.dom.title': 'Domestic Business Trip',
  'te.bd.dom.desc': 'Bangladesh does not set a legally required per diem for private sector employees. The government sets daily allowances (TA/DA — Travel Allowance / Daily Allowance) for its own civil servants based on their pay grade (BPS grade system).\n\nUnder the Income Tax Act 2023, travel allowances paid by private employers for legitimate business trips are generally exempt from income tax, provided the amounts are reasonable and properly documented. The tax authority may assess \'reasonableness\' by reference to public sector rates.\n\nMarket practice for MNCs: BDT 1,500–3,000 per day for professional staff (accommodation typically reimbursed separately). All domestic rates are in Bangladeshi Taka (BDT).',
  'te.bd.dom.source': 'Income Tax Act 2023; Finance Division — TA/DA Circulars',
  'te.bd.dom.h.0': 'Grade / Category',
  'te.bd.dom.h.1': 'Daily Allowance (BDT/day)',
  'te.bd.dom.h.2': 'Source Type',
  'te.bd.dom.r.0.0': 'Government — Grade 1–5 (senior officers / secretaries)',
  'te.bd.dom.r.0.1': '1,500',
  'te.bd.dom.r.0.2': 'Government Benchmark',
  'te.bd.dom.r.1.0': 'Government — Grade 6–10 (mid-level officers)',
  'te.bd.dom.r.1.1': '1,000',
  'te.bd.dom.r.1.2': 'Government Benchmark',
  'te.bd.dom.r.2.0': 'Government — Grade 11–20 (junior officers & staff)',
  'te.bd.dom.r.2.1': '600',
  'te.bd.dom.r.2.2': 'Government Benchmark',
  'te.bd.dom.r.3.0': 'Private sector — MNC market practice',
  'te.bd.dom.r.3.1': '1,500 – 3,000',
  'te.bd.dom.r.3.2': 'Market Practice',
  'te.bd.intl.title': 'International Business Trips',
  'te.bd.intl.desc': 'For overseas travel, the Finance Division sets per diem rates for government officials. These vary by destination and the official\'s grade level. Private employers are not legally bound by these rates but commonly reference them.\n\nRates are expressed in USD per day (inclusive of meals and incidentals). Accommodation is typically reimbursed separately against receipts.',
  'te.bd.intl.source': 'Finance Division — Foreign Travel TA/DA Rules',
  'te.bd.intl.h.0': 'Destination / Grade',
  'te.bd.intl.h.1': 'Rate (USD/day)',
  'te.bd.intl.h.2': 'Source Type',
  'te.bd.intl.r.0.0': 'High-cost destinations — senior officers (US, UK, Japan)',
  'te.bd.intl.r.0.1': '250 – 350',
  'te.bd.intl.r.0.2': 'Government Benchmark',
