  'te.bd.intl.r.1.1': '200 – 250',
  'te.bd.intl.r.1.2': 'Government Benchmark',
  'te.bd.intl.r.2.0': 'Mid-cost destinations — senior officers (EU, Gulf)',
  'te.bd.intl.r.2.1': '180 – 250',
  'te.bd.intl.r.2.2': 'Government Benchmark',
  'te.bd.intl.r.3.0': 'Mid-cost destinations — junior officers',
  'te.bd.intl.r.3.1': '150 – 180',
