  /* ── Belgium (BE) ── */
  'te.be.dom.title': 'Domestic Business Trip',
  'te.be.dom.desc': 'Belgium has a government-set per diem for domestic business trips, which applies to ALL employers (public and private).\n\nCurrent rates (effective 1 March 2025, indexed annually):\n  • Daily allowance: €21.22 per day (covers meals only)\n  • Overnight allowance: €159.17 per night (only if employer does NOT pay accommodation)\n  • Monthly flat rate (for frequent travellers): max 16 × €21.22 = €339.52/month\n\nTo qualify, the trip must be:\n  • Genuinely business-related\n  • At least 6 hours long\n  • More than 25 km from the employee\'s usual workplace\n  • Employee must not receive other meal compensation for the same day\n\nDeductions apply if meals are provided free: 35% deducted for lunch, 45% for dinner. Meal voucher amounts must also be deducted. You cannot claim both receipts and per diem for the same expenses.',
  'te.be.dom.source': 'FPS Finance — Domestic per diem (indexed); effective 1 March 2025',
  'te.be.dom.h.0': 'Category',
  'te.be.dom.h.1': 'Rate (EUR)',
  'te.be.dom.h.2': 'Source Type',
  'te.be.dom.r.0.0': 'Daily allowance (meals only)',
  'te.be.dom.r.0.1': '€21.22/day',
  'te.be.dom.r.0.2': 'Statutory',
  'te.be.dom.r.1.0': 'Overnight allowance (if employer doesn\'t pay accommodation)',
  'te.be.dom.r.1.1': '€159.17/night',
  'te.be.dom.r.1.2': 'Statutory',
  'te.be.dom.r.2.0': 'Monthly flat rate (frequent domestic travellers)',
  'te.be.dom.r.2.1': '€339.52/month (16 × €21.22)',
  'te.be.dom.r.2.2': 'Statutory',
  'te.be.dom.r.3.0': 'If meals provided free — lunch deduction',
  'te.be.dom.r.3.1': '35% of daily rate',
  'te.be.dom.r.3.2': 'Statutory',
  'te.be.dom.r.4.0': 'If meals provided free — dinner deduction',
  'te.be.dom.r.4.1': '45% of daily rate',
  'te.be.dom.r.4.2': 'Statutory',
  'te.be.intl.title': 'International Business Trips',
  'te.be.intl.desc': 'Belgium has two categories for international trips:\n\n  • Category 1 (Short): trips up to 30 consecutive calendar days. Covers meals and small expenses (local transport, snacks, tips, phone). Employers can use a flat €37.18/day (same for all countries) or the country-specific rates in the table below.\n\n  • Category 2 (Long): trips over 30 days, up to 24 months. Rates are slightly higher. Allowances stop if the employee permanently relocates to that country.\n\nAccommodation: not included in per diem — reimbursed separately up to the maximum shown.\n\nMeal deductions: 35% for lunch, 45% for dinner if provided free by employer or third party.\nAll rates are in Euros (EUR). Source: Ministerieel besluit 14 July 2025.',
  'te.be.intl.source': 'Ministerieel besluit published BS 14.07.2025 — new rates effective 14 July 2025',
  'te.be.intl.h.0': 'Country',
  'te.be.intl.h.1': 'Max Accommodation (EUR/night)',
  'te.be.intl.h.2': 'Cat 1 Daily Rate (EUR)',
  'te.be.intl.h.3': 'Cat 2 Daily Rate (EUR)',
