  /* ── Brazil (BR) ── */
  'te.br.dom.title': 'Domestic Business Trip',
  'te.br.dom.desc': 'Brazil has NO mandatory per diem rate for private sector employers. Each company sets its own rates.\n\nTax treatment (CLT Art. 457 §2, amended 2017): Per diem (diárias) paid to employees for business travel are NOT considered part of salary and are FULLY exempt from income tax — with NO cap on the amount. This was changed in 2017; the previous rule that capped tax-free per diem at 50% of monthly salary was abolished.\n\nImportant: This tax exemption only applies if the payment is genuinely for travel expenses and not structured as disguised salary. If the payment exceeds actual travel costs or is not linked to genuine travel, it can be reclassified as salary by the tax authority (Receita Federal).\n\nFederal public sector rates (Decreto 12.417/2024) are shown for reference. Private employers commonly use these as a benchmark.',
  'te.br.dom.source': 'CLT Art. 457 §2 (amended 2017) + Art. 470 — Consolidação das Leis do Trabalho',
  'te.br.dom.h.0': 'Category',
  'te.br.dom.h.1': 'Rate (BRL/day)',
  'te.br.dom.h.2': 'Source Type',
  'te.br.dom.r.0.0': 'Federal public sector — Ministers / State Secretaries',
  'te.br.dom.r.0.1': 'BRL 700.33',
  'te.br.dom.r.0.2': 'Government Benchmark',
  'te.br.dom.r.1.0': 'Federal public sector — DAS 4–6 / senior civil servants',
  'te.br.dom.r.1.1': 'BRL 508.17',
  'te.br.dom.r.1.2': 'Government Benchmark',
  'te.br.dom.r.2.0': 'Federal public sector — other federal employees',
  'te.br.dom.r.2.1': 'BRL 335.60',
  'te.br.dom.r.2.2': 'Government Benchmark',
  'te.br.dom.r.3.0': 'Private sector',
  'te.br.dom.r.3.1': 'Per company policy (no statutory rate)',
  'te.br.dom.r.3.2': 'Market Practice',
  'te.br.dom.r.4.0': 'Tax treatment (CLT Art. 457 §2)',
  'te.br.dom.r.4.1': 'Fully tax-free, no cap — genuine travel expenses only',
  'te.br.dom.r.4.2': 'Statutory',
  'te.br.intl.title': 'International Business Trips',
  'te.br.intl.desc': 'International travel per diem for Brazilian federal public sector employees is set by Decreto 12.417/2024. These are benchmark rates — private employers are not legally required to follow them but often use them as a reference.\n\nRates are in USD per day and cover meals and incidentals. Accommodation is reimbursed separately against receipts.\n\nPrivate sector: same CLT Art. 457 §2 tax exemption applies to international per diems — fully tax-free with no cap, as long as genuinely for business travel.',
  'te.br.intl.source': 'Decreto 12.417/2024 — Federal public sector international rates',
  'te.br.intl.h.0': 'Destination / Grade',
  'te.br.intl.h.1': 'Rate (USD/day)',
  'te.br.intl.h.2': 'Source Type',
  'te.br.intl.r.0.0': 'Group A — high-cost destinations (US, Western Europe, Japan, Australia)',
  'te.br.intl.r.0.1': 'USD 403',
  'te.br.intl.r.0.2': 'Government Benchmark',
  'te.br.intl.r.1.0': 'Group B — medium-high cost (Middle East, Singapore, Canada, New Zealand)',
  'te.br.intl.r.1.1': 'USD 352',
  'te.br.intl.r.1.2': 'Government Benchmark',
  'te.br.intl.r.2.0': 'Group C — medium cost (Eastern Europe, most of Latin America, South Africa)',
  'te.br.intl.r.2.1': 'USD 298',
  'te.br.intl.r.2.2': 'Government Benchmark',
  'te.br.intl.r.3.0': 'Group D — lower-cost destinations (South Asia, Sub-Saharan Africa, Central Asia)',
