  /* ── Bulgaria (BG) ── */
  'te.bg.dom.title': 'Domestic Business Trip',
  'te.bg.dom.desc': 'Bulgaria has statutory minimum per diem rates for domestic business trips. These apply to ALL employers and are set by government ordinance.\n\nRates (effective since 27 March 2023):\n  • With overnight stay: BGN 40 per day (minimum)\n  • Day trip only (no overnight): BGN 20 per day (50% of full rate)\n\nTax treatment (PITA Art. 24(2)(5b)):\nPer diem is tax-free up to 200% of the statutory minimum:\n  • With overnight: up to BGN 80/day tax-free (200% × BGN 40)\n  • Day trip: up to BGN 40/day tax-free (200% × BGN 20)\nAmounts above 200% are treated as taxable employment income.\n\nAccommodation: Reimbursed at actual cost with receipts. Without receipts, maximum BGN 35/night tax-free.\n\nImportant: As of 1 January 2026, Bulgaria joined the Eurozone. Rates may be converted to EUR. Always verify current denomination with the NRA (NAP).',
  'te.bg.dom.source': 'Ordinance on Domestic Business Trips (amended March 2023) — Art. 19; PITA Art. 24(2)(5b) — tax-free ceiling',
  'te.bg.dom.h.0': 'Category',
  'te.bg.dom.h.1': 'Daily Allowance',
  'te.bg.dom.h.2': 'Source Type',
