  'te.bg.dom.r.6.2': 'Statutory',
  'te.bg.intl.title': 'International Business Trips',
  'te.bg.intl.desc': 'For international trips, Bulgaria uses a full country-by-country rate table set in Appendix 2 of the Ordinance on Official Business Trips Abroad. Updated rates are in force from 1 February 2025 (DV bр.8/2025).\n\nThree components apply:\n  • Daily allowance (дневни пари): covers meals and incidentals — country-specific, in EUR\n  • Accommodation (квартирни пари): maximum per night — country-specific, in EUR; actual receipted costs may be reimbursed instead\n  • Transport: reimbursed separately against receipts\n\nTax treatment: Same 200% rule applies. Amounts within 200% of the Appendix 2 rate are tax-free. Excess is taxable income.\n\nNote: The full Appendix 2 country list covers 170+ countries. Key selected rates are shown below — refer to the official ordinance for the complete list.',
  'te.bg.intl.source': 'Ordinance on Official Business Trips Abroad (NKSCS) — Appendix 2; last updated DV bр.8/2025 (eff. 1 Feb 2025)',
  'te.bg.intl.h.0': 'Country',
