  /* ── Canada (CA) ── */
  'te.ca.dom.title': 'Domestic Business Trip',
  'te.ca.dom.desc': 'Canada has NO mandatory statutory per diem for private sector employers. The CRA (Canada Revenue Agency) sets allowance rates for its own employees, and these are widely used as a benchmark by private companies.\n\nTax treatment: A travel allowance is non-taxable to the employee if:\n  1. The employee travels away from their usual municipality/metropolitan area\n  2. The amount is \'reasonable\'\n  3. The CRA considers up to $23 CAD per meal reasonable (simplified method)\n\nCRA published meal rates (Appendix B — effective April 1, 2025):\n  • Breakfast:  $28.40 (all provinces); Yukon $27.95; NWT $30.50; Nunavut $30.55\n  • Lunch:       $27.40 (all provinces); Yukon $25.65; NWT $37.00; Nunavut $37.05\n  • Dinner:      $57.70 (all provinces); Yukon $73.95; NWT $79.20; Nunavut $98.75\n  • Daily total: $113.50 (all provinces) — reviewed every 6 months\n  • Incidentals: $17.50 per day\n  • Private non-commercial accommodation: $50.00 per night\n\nAll amounts are in Canadian Dollars (CAD), taxes included.',
  'te.ca.dom.source': 'CRA Directive on Travel — Appendix B (effective April 2025, reviewed semi-annually)',
  'te.ca.dom.h.0': 'Meal / Category',
