  'te.ca.intl.title': 'International Business Trips',
  'te.ca.intl.desc': 'For international travel, the CRA publishes country-specific meal rates under Appendix C of the Directive on Travel. These are used by federal government employees and widely referenced by private companies.\n\nKey rules:\n  • Incidentals: 32% of total meal allowance (commercial accommodation)\n  • Private non-commercial accommodation (abroad): CAD $50/night\n  • Rates updated quarterly (April 1 and October 1)\n  • Where no rate is listed (*), actual reasonable costs apply with receipts\n\nSelected rates from Appendix C (October 2025) are shown below in CAD/day. All rates cover meals only — accommodation reimbursed separately at actual cost.',
  'te.ca.intl.source': 'CRA Directive on Travel — Appendix C (effective October 2025)',
