  /* ── Chile (CL) ── */
  'te.cl.dom.title': 'Domestic Business Trip',
  'te.cl.dom.desc': 'Chile has NO government-mandated per diem rate for private sector employers. Companies set their own rates.\n\nTax treatment (Ley de Renta Art. 17 N°15): Per diem (viáticos) paid to employees are exempt from income tax provided they are:\n  1. For genuine business travel\n  2. \'Reasonable\' in the SII\'s judgment\n  3. Properly documented (travel records, purpose, duration)\n\nThe SII (Servicio de Impuestos Internos) assesses reasonableness case-by-case. There is no published fixed ceiling. In practice, the SII uses the public sector scale (DFL 262/77) as a reference benchmark.\n\nPublic sector rates under DFL 262/77 (reference benchmarks — CLP amounts are approximate due to periodic adjustments):\n  • Senior officials: CLP 60,000–80,000/day\n  • Standard employees: CLP 35,000–50,000/day\n\nNote: CLP rates fluctuate with inflation — always verify current scale via the Contraloría General de la República or SII.',
  'te.cl.dom.source': 'Ley sobre Impuesto a la Renta Art. 17 N°15 — viáticos tax exemption rule',
  'te.cl.dom.h.0': 'Category',
  'te.cl.dom.h.1': 'Rate (CLP/day, approx.)',
  'te.cl.dom.h.2': 'Source Type',
  'te.cl.dom.r.0.0': 'Public sector — senior officials (DFL 262/77)',
  'te.cl.dom.r.0.1': 'CLP 60,000 – 80,000',
  'te.cl.dom.r.0.2': 'Government Benchmark',
  'te.cl.dom.r.1.0': 'Public sector — standard employees',
  'te.cl.dom.r.1.1': 'CLP 35,000 – 50,000',
  'te.cl.dom.r.1.2': 'Government Benchmark',
  'te.cl.dom.r.2.0': 'Private sector',
  'te.cl.dom.r.2.1': 'Per company policy (no statutory rate)',
  'te.cl.dom.r.2.2': 'Market Practice',
  'te.cl.dom.r.3.0': 'Tax exemption (Art. 17 N°15)',
  'te.cl.dom.r.3.1': 'Exempt if reasonable & documented — no fixed cap',
  'te.cl.dom.r.3.2': 'Statutory',
  'te.cl.dom.r.4.0': 'Excess above SII \'reasonable\' threshold',
  'te.cl.dom.r.4.1': 'Taxable as employment income (Second Category Tax)',
  'te.cl.dom.r.4.2': 'Statutory',
  'te.cl.intl.title': 'International Business Trips',
  'te.cl.intl.desc': 'For international travel, Chile also has no mandatory private sector rate. The public sector scale under Decreto 1.121 (updating DFL 262/77) provides USD benchmarks used as the reference for tax-exempt treatment.\n\nTax treatment: Same Art. 17 N°15 exemption applies — international viáticos are tax-free if reasonable and documented. The SII references public sector USD rates as the benchmark for private sector.\n\nPublic sector benchmark rates (Decreto 1.121, amounts in USD/day):\n  • North America / Western Europe: USD 315/day\n  • Japan / Australia / New Zealand: USD 290/day\n  • Asia-Pacific (excluding Japan): USD 270/day\n  • Latin America: USD 230/day\n  • Africa / Eastern Europe / Middle East: USD 210/day\n\nThese are NOT legally binding for private sector — treat as a reasonableness guide.',
  'te.cl.intl.source': 'DFL N° 262/77 — public sector per diem scales; SII rulings on reasonableness',
  'te.cl.intl.h.0': 'Destination Region',
  'te.cl.intl.h.1': 'Benchmark Rate (USD/day)',
  'te.cl.intl.h.2': 'Source Type',
  'te.cl.intl.r.0.0': 'North America / Western Europe (US, Canada, UK, Germany, France, etc.)',
  'te.cl.intl.r.0.1': 'USD 315',
  'te.cl.intl.r.0.2': 'Government Benchmark',
  'te.cl.intl.r.1.0': 'Japan / Australia / New Zealand',
  'te.cl.intl.r.1.1': 'USD 290',
  'te.cl.intl.r.1.2': 'Government Benchmark',
  'te.cl.intl.r.2.0': 'Asia-Pacific — excluding Japan (China, Singapore, South Korea, etc.)',
  'te.cl.intl.r.2.1': 'USD 270',
