  /* ── China (CN) ── */
  'te.cn.dom.title': 'Domestic Business Trip',
  'te.cn.dom.desc': 'China has NO government-mandated per diem rate for private sector employers. Companies set their own policies.\n\nTax treatment under IIT Law: Business travel expense reimbursements are NOT taxable income, provided they are:\n  1. For genuine, documented business travel\n  2. Supported by valid invoices (fapiao — ) or receipts\n  3. Reasonable in amount relative to actual costs\n\nIf paid as a flat cash allowance without fapiao documentation, the STA may treat it as taxable employment income subject to IIT (3%–45%).\n\nMOF Central Government Reference (Circular, 2014 as amended):\n  • Ministerial level — accommodation: up to CNY 1,100/night (Beijing/Shanghai)\n  • Senior civil servants (Bureau level+) — accommodation: up to CNY 500–850/night\n  • Standard civil servants — accommodation: up to CNY 300–500/night\n  • Meals & incidentals: typically CNY 100–200/day (varies by location tier)\n  • Cities are tiered (Tier 1: Beijing, Shanghai, Guangzhou, Shenzhen; Tier 2–4: lower rates)\n\nNote: Private companies commonly use the government scale as a benchmark. There is no single national rate — verify company policy for your specific employer.',
  'te.cn.dom.source': 'State Taxation Administration (STA) — IIT guidance on business travel reimbursements',
  'te.cn.dom.h.0': 'Category',
  'te.cn.dom.h.1': 'Rate (CNY/day — central govt reference)',
  'te.cn.dom.h.2': 'Source Type',
  'te.cn.dom.r.0.0': 'Ministerial / Vice-Ministerial level — Beijing & Shanghai',
