  'te.cn.dom.r.6.0': 'Private sector (no statutory rate)',
  'te.cn.dom.r.6.1': 'Per company policy — reimbursement with fapiao recommended',
  'te.cn.dom.r.6.2': 'Market Practice',
  'te.cn.dom.r.7.0': 'Tax treatment — reimbursement with fapiao',
  'te.cn.dom.r.7.1': 'Tax-free — not subject to IIT',
  'te.cn.dom.r.7.2': 'Tax Authority Guideline',
  'te.cn.dom.r.8.0': 'Tax treatment — flat cash allowance (no fapiao)',
  'te.cn.dom.r.8.1': 'May be subject to IIT (3%–45%)',
  'te.cn.dom.r.8.2': 'Statutory',
  'te.cn.intl.title': 'International Business Trips',
  'te.cn.intl.desc': 'For international travel, China also has no mandatory per diem for private sector.\n\nCentral government overseas travel (MOF regulations):\n  • Per diem rates vary by country and are set in USD\n  • Accommodation: reimbursed at actual cost with receipts\n  • Business class flights: only permitted for Deputy Minister level and above\n\nPrivate sector: Same IIT treatment — reimbursements of actual overseas travel expenses with fapiao/receipts are tax-free. Flat cash allowances without documentation are taxable. Many companies reference U.S. State Department or UN ICSC rates as a benchmark for international travel.\n\nNote for foreign employees: Business travel expense reimbursements, housing allowances, meal allowances, and similar benefits-in-kind remain tax-free for expats until end of 2027 (extended), provided they are actual-cost reimbursements with valid fapiao.',
  'te.cn.intl.source': 'MOF Circular on Central Government Travel Expense Management (2014, as amended)',
  'te.cn.intl.h.0': 'Destination',
