  /* ── Colombia (CO) ── */
  'te.co.dom.title': 'Domestic Business Trip',
  'te.co.dom.desc': 'Colombia has NO government-mandated per diem rate for private sector employers. Companies set their own rates. The public sector scale under Decreto 1083/2015 is widely used as a benchmark.\n\nTax treatment (Estatuto Tributario Art. 107):\n  • Viáticos (travel allowances) paid to employees for genuine business travel are deductible for the employer as a business expense\n  • For the EMPLOYEE: viáticos are NOT taxable income, provided they are for actual business travel and are reasonable (Estatuto Tributario Art. 127)\n  • If the allowance is excessive or not linked to genuine travel, DIAN may reclassify it as salary income, subject to income tax (0%–39%)\n\nPublic sector reference rates (Decreto 1083/2015 — approximate 2025 ranges):\n  • Director / Senior official: COP 200,000–350,000/day\n  • Professional / Technical level: COP 120,000–200,000/day\n  • Support staff: COP 70,000–120,000/day\n\nNote: COP rates adjust with inflation. The 2025 UVT = COP 49,799. Always verify current rates with DIAN or company HR policy.',
  'te.co.dom.source': 'DIAN — Dirección de Impuestos y Aduanas Nacionales; Estatuto Tributario',
  'te.co.dom.h.0': 'Category',
  'te.co.dom.h.1': 'Rate (COP/day — reference)',
  'te.co.dom.h.2': 'Source Type',
  'te.co.dom.r.0.0': 'Public sector — Director / Senior official',
  'te.co.dom.r.0.1': 'COP 200,000 – 350,000',
