  'te.co.dom.r.1.0': 'Public sector — Professional / Technical level',
  'te.co.dom.r.1.1': 'COP 120,000 – 200,000',
  'te.co.dom.r.1.2': 'Government Benchmark',
  'te.co.dom.r.2.0': 'Public sector — Support staff',
  'te.co.dom.r.2.1': 'COP 70,000 – 120,000',
