  'te.co.dom.r.3.2': 'Market Practice',
  'te.co.dom.r.4.0': 'Tax treatment (ET Art. 127)',
  'te.co.dom.r.4.1': 'Non-taxable if for genuine business travel and reasonable',
  'te.co.dom.r.4.2': 'Statutory',
  'te.co.dom.r.5.0': 'Amounts deemed unreasonable or not travel-related',
  'te.co.dom.r.5.1': 'Taxable salary income (0%–39% IIT)',
  'te.co.dom.r.5.2': 'Statutory',
  'te.co.intl.title': 'International Business Trips',
  'te.co.intl.desc': 'For international travel, Colombia references US State Department per diem rates or similar benchmarks. There is no separate Colombian government rate table for private sector international travel.\n\nPublic sector: Decree 1083/2015 sets USD rates for government officials traveling abroad, tiered by destination cost of living and employee rank.\n\nTax treatment: Same Estatuto Tributario Art. 127 applies — international viáticos are non-taxable if for legitimate business travel and reasonable in amount. Accommodation must typically be receipted separately.\n\nPrivate sector benchmark rates (commonly used, based on public sector guidance):\n  • North America / Western Europe: USD 300–400/day\n  • Latin America: USD 200–300/day\n  • Asia-Pacific / Middle East: USD 250–350/day\n  • Africa / Eastern Europe: USD 180–280/day',
  'te.co.intl.source': 'Public sector rates per Decreto 1083 of 2015 (Reglamento Único Sector Administrativo)',
  'te.co.intl.h.0': 'Destination Region',
