  /* ── Croatia (HR) ── */
  'te.hr.dom.title': 'Domestic Business Trip',
  'te.hr.dom.desc': 'Croatia has statutory per diem (dnevnica) limits set by the Income Tax Act (Zakon o porezu na dohodak) and Income Tax Regulations. These apply to ALL employers.\n\nDomestic per diem rates (2025 — in EUR since Croatia adopted the euro on 1 Jan 2023):\n  • Full per diem (trip over 12 hours): up to EUR 30/day — tax-free\n  • Half per diem (trip 8–12 hours): up to EUR 15/day — tax-free\n  • Trips under 8 hours: no per diem entitlement\n\nKey rules:\n  • Per diem covers meals and personal incidentals only\n  • A valid travel order (putni nalog) must be issued before departure\n  • If employer provides free meals, the per diem must be reduced:\n    – Breakfast deducted: 15% of daily rate\n    – Lunch deducted: 35% of daily rate\n    – Dinner deducted: 35% of daily rate\n    – Full board (all meals): 70% deducted (employee receives 30%)\n  • Cannot combine per diem (dnevnica) with field allowance (terenski dodatak) for the same day\n  • Accommodation: reimbursed at actual cost with receipts (no flat rate)\n\nEmployers can pay more than EUR 30 — the excess above the statutory limit is taxable income for the employee.',
  'te.hr.dom.source': 'Croatian Tax Administration — Pravilnik o porezu na dohodak (Income Tax Regulations)',
  'te.hr.dom.h.0': 'Category',
  'te.hr.dom.h.1': 'Rate (EUR/day)',
  'te.hr.dom.h.2': 'Source Type',
