  'te.hr.intl.title': 'International Business Trips',
  'te.hr.intl.desc': 'For international trips, Croatia publishes country-specific rates under the Government Decree on Foreign Business Travel Allowances. Updated rates are published in Narodne novine (official gazette).\n\nKey rules:\n  • Full rate: trip over 12 hours abroad\n  • Half rate (50%): trip 8–12 hours abroad\n  • No allowance: under 8 hours\n  • Covers meals and incidentals; accommodation receipted separately\n  • Travel order (putni nalog) required for tax-free treatment\n  • Same meal deduction rules apply (breakfast 15%, lunch/dinner 35% each)\n\nSelected country rates (EUR/day) from the Government Decree are shown below. All rates are in EUR.',
  'te.hr.intl.source': 'Government Decree on Foreign Business Travel Allowances — Narodne novine',
  'te.hr.intl.h.0': 'Country',
