  /* ── Czech Republic (CZ) ── */
  'te.cz.dom.title': 'Domestic Business Trip — Stravné (Meal Allowance)',
  'te.cz.dom.desc': 'Czech Republic has statutory per diem (stravné) rates set annually by decree under the Labour Code (Zákoník práce §163 and §176). These apply to ALL employers.\n\n2025 domestic rates (Vyhláška č. 475/2024 Sb., effective 1 Jan 2025):\n  • Trip 5–12 hours: CZK 148/day (private sector minimum)\n  • Trip 12–18 hours: CZK 225/day\n  • Trip over 18 hours: CZK 353/day\n\nPublic sector ranges (§176 — set annually within the statutory band):\n  • 5–12 hours: CZK 148–177/day\n  • 12–18 hours: CZK 225–271/day\n  • Over 18 hours: CZK 353–422/day\n\nTax treatment: Amounts within the statutory ceiling are fully tax-free (no IIT, no social/health contributions). Amounts above the public sector ceiling are taxable salary income for the employee.\n\nMeal deductions: If free meals are provided during the trip, per diem is reduced:\n  • 70% deduction for trip 5–12h\n  • 35% deduction for trip 12–18h\n  • 25% deduction for trip over 18h\n\nAccommodation: Reimbursed at actual receipted cost — no flat rate applies.',
  'te.cz.dom.source': 'Vyhláška č. 475/2024 Sb. — domestic per diem 2025; Zákoník práce č. 262/2006 Sb.',
  'te.cz.dom.h.0': 'Trip Duration',
  'te.cz.dom.h.1': 'Private Sector (CZK/day)',
  'te.cz.dom.h.2': 'Source Type',
  'te.cz.dom.r.0.0': 'Trip duration 5–12 hours',
  'te.cz.dom.r.0.1': 'CZK 148 (statutory minimum)',
