  'te.cz.dom.r.8.1': 'Actual receipted cost — no flat rate',
  'te.cz.dom.r.8.2': 'Statutory',
  'te.cz.intl.title': 'International Business Trip — Zahraniční Stravné',
  'te.cz.intl.desc': 'Czech Republic publishes country-specific international per diem (zahraniční stravné) rates annually under the Labour Code §170 and Ministry of Finance decree.\n\n2025 rates: Vyhláška č. 373/2024 Sb. (in force 1 Jan 2025).\nRates are set in EUR or USD per country. All amounts are full-day rates.\n\nProration rules:\n  • Over 18 hours abroad: 100% (full rate)\n  • 12–18 hours abroad: 2/3 of full rate\n  • 1–12 hours abroad: 1/3 of full rate\n  • Under 1 hour: no allowance\n\nMeal deductions (free meals provided):\n  • 25% deduction per free meal (at full rate)\n  • 35% deduction (at 2/3 rate)\n  • 70% deduction (at 1/3 rate)\n\nPrivate sector: may pay higher — excess above MF rate is taxable for the employee.\nAdditionally, a pocket money supplement (kapesné) of up to 40% of the daily rate may be provided tax-free.',
  'te.cz.intl.source': 'Vyhláška č. 373/2024 Sb. — international per diem rates 2025 (MF ČR)',
