  /* ── Denmark (DK) ── */
  'te.dk.dom.title': 'Domestic Business Trip',
  'te.dk.dom.desc': 'Denmark has government-set standard per diem rates (rejsegodtgørelse / diæter) published annually by SKAT. These apply to ALL employers who pay tax-free allowances.\n\n2025 standard rates (set by SKAT, effective 1 Jan 2025):\n  • Food & incidentals (kostgodtgørelse): DKK 597/day\n  • Accommodation (logigodtgørelse): up to DKK 256/night\n  • 25% petty expenses allowance: DKK 149.25/day (applies even when meals are provided — covers coffee, newspapers, local transport)\n\nKey conditions:\n  • Trip must last at least 24 hours and employee must sleep away from home\n  • Must be a temporary workplace — employee cannot commute daily\n  • Accommodation allowance only applies if employer does NOT pay accommodation\n\nProration: allowance is paid per commenced hour beyond the first 24 hours. If you travel 40 hours, you get the daily rate plus 16/24 of the daily rate.\n\nMeal deductions (if employer provides free meals):\n  • Breakfast: 15% of daily food rate (DKK 89.55)\n  • Lunch: 30% of daily food rate (DKK 179.10)\n  • Dinner: 30% of daily food rate (DKK 179.10)\n\n12-month rule: Standard rate applies for the first 12 months at the same temporary workplace. After 12 months, actual documented costs only.\n\nAnnual cap (employee deduction): DKK 32,800 in 2025 — applies to employee self-deductions only; does NOT limit employer\'s ability to pay tax-free allowances.',
  'te.dk.dom.source': 'SKAT (Danish Tax Authority) — Tax-free travel allowance (rejsegodtgørelse / diæter) 2025',
  'te.dk.dom.h.0': 'Allowance Type',
  'te.dk.dom.h.1': 'Rate (DKK — 2025)',
  'te.dk.dom.h.2': 'Source Type',
  'te.dk.dom.r.0.0': 'Food & incidentals (kostgodtgørelse) — full day',
  'te.dk.dom.r.0.1': 'DKK 597/day',
  'te.dk.dom.r.0.2': 'Statutory',
  'te.dk.dom.r.1.0': 'Accommodation (logigodtgørelse) — per night',
  'te.dk.dom.r.1.1': 'Up to DKK 256/night',
  'te.dk.dom.r.1.2': 'Statutory',
  'te.dk.dom.r.2.0': '25% petty expenses (even with free meals)',
  'te.dk.dom.r.2.1': 'DKK 149.25/day',
  'te.dk.dom.r.2.2': 'Statutory',
  'te.dk.dom.r.3.0': 'Meal deduction — breakfast provided',
  'te.dk.dom.r.3.1': 'DKK 89.55 (15% of food rate)',
  'te.dk.dom.r.3.2': 'Statutory',
  'te.dk.dom.r.4.0': 'Meal deduction — lunch provided',
  'te.dk.dom.r.4.1': 'DKK 179.10 (30% of food rate)',
  'te.dk.dom.r.4.2': 'Statutory',
  'te.dk.dom.r.5.0': 'Meal deduction — dinner provided',
  'te.dk.dom.r.5.1': 'DKK 179.10 (30% of food rate)',
  'te.dk.dom.r.5.2': 'Statutory',
  'te.dk.dom.r.6.0': 'Minimum trip duration for tax-free allowance',
  'te.dk.dom.r.6.1': '24 hours with overnight stay away from home',
  'te.dk.dom.r.6.2': 'Statutory',
  'te.dk.dom.r.7.0': 'Annual cap (employee self-deduction only)',
  'te.dk.dom.r.7.1': 'DKK 32,800/year (2025) — does NOT limit employer payments',
  'te.dk.dom.r.7.2': 'Statutory',
  'te.dk.dom.r.8.0': 'After 12 months at same temporary workplace',
  'te.dk.dom.r.8.1': 'Actual documented costs only (standard rate no longer applies)',
  'te.dk.dom.r.8.2': 'Statutory',
  'te.dk.intl.title': 'International Business Trips',
  'te.dk.intl.desc': 'For international travel, Denmark uses the SAME standard rate framework. However, the food rate for abroad is the domestic food rate (DKK 597/day) — there is no separate country-specific international rate table.\n\nAccommodation internationally: reimbursed at actual documented cost (receipts), OR the employer can use the DKK 256/night standard rate.\n\nAlternative approach: Many Danish companies use U.S. State Department rates or company-specific international scales for more accurate cost coverage — all are accepted by SKAT as long as properly documented and reasonable.\n\nTax treatment: Same rules apply. Allowances up to the SKAT standard rates are fully tax-free. Amounts above are taxable income.\n\nNote: For employees who travel internationally more than 180 days/year, specific longer-term assignment rules may apply — consult SKAT or a tax advisor.',
  'te.dk.intl.source': 'Same SKAT rules apply to international travel — rates as per account rendered or standard rates',
  'te.dk.intl.h.0': 'Allowance Type / Notes',
  'te.dk.intl.h.1': 'Rate (DKK — 2025)',
  'te.dk.intl.h.2': 'Source Type',
  'te.dk.intl.r.0.0': 'Food & incidentals — international',
  'te.dk.intl.r.0.1': 'Same rate: DKK 597/day (no country-specific rates)',
  'te.dk.intl.r.0.2': 'Statutory',
  'te.dk.intl.r.1.0': 'Accommodation — international',
  'te.dk.intl.r.1.1': 'Actual receipted cost OR up to DKK 256/night standard rate',
  'te.dk.intl.r.1.2': 'Statutory',
  'te.dk.intl.r.2.0': '25% petty expenses — international',
  'te.dk.intl.r.2.1': 'DKK 149.25/day (same as domestic)',
  'te.dk.intl.r.2.2': 'Statutory',
  'te.dk.intl.r.3.0': 'Alternative: company-specific international scales',
  'te.dk.intl.r.3.1': 'Accepted by SKAT if reasonable and documented',
  'te.dk.intl.r.3.2': 'Market Practice',
  'te.dk.intl.r.4.0': 'Alternative: U.S. State Department rates',
  'te.dk.intl.r.4.1': 'Commonly used as benchmark by Danish multinationals',
  'te.dk.intl.r.4.2': 'Market Practice',
  'te.dk.intl.r.5.0': 'Tax treatment — within standard rates',
  'te.dk.intl.r.5.1': 'Fully tax-free, no IIT, no AM-bidrag',
  'te.dk.intl.r.5.2': 'Statutory',
  'te.dk.intl.r.6.0': 'Tax treatment — above standard rates',
