  'te.dk.intl.r.6.2': 'Statutory',

  /* ── Egypt (EG) ── */
  'te.eg.dom.title': 'Domestic Business Trip',
  'te.eg.dom.desc': 'Egypt has NO government-mandated per diem rate for private sector employers. Companies set their own travel allowance policies.\n\nTax treatment under Income Tax Law No. 91/2005 (amended by Law No. 7 of 2024):\n  • Travel allowances (بدل الانتقال / بدل سفر) paid to employees for legitimate business travel are generally treated as non-salary income and are NOT subject to income tax (IIT), provided they are:\n    1. For genuine, documented business travel\n    2. Supported by valid receipts or travel orders\n    3. Reasonable and not excessive\n\nSocial insurance note: Allowances for transport, travel, meals, and accommodation can be excluded from the social insurance salary base if they do not exceed 30% of the total social insurance wage.\n\nPublic sector reference (Ministerial Decree):\n  • Per diems for Egyptian government employees are set by Ministerial Decree and vary by employee grade, destination within Egypt, and duration\n  • Standard rates range from EGP 150–500/day depending on grade and location\n  • Cairo / major cities: generally higher rates than provincial areas\n\nNote: Due to Egypt\'s high inflation, EGP rates must be verified with current official circulars. All rates are in Egyptian Pounds (EGP).',
  'te.eg.dom.source': 'Egyptian Tax Authority (ETA) — Articles 16 and 22 on travel allowances and business expenses',
  'te.eg.dom.h.0': 'Category',
  'te.eg.dom.h.1': 'Rate (EGP/day — reference)',
  'te.eg.dom.h.2': 'Source Type',
  'te.eg.dom.r.0.0': 'Public sector — senior officials (Grade 1–4)',
  'te.eg.dom.r.0.1': 'EGP 400–500/day (varies by grade & destination)',
