  'te.eg.intl.title': 'International Business Trips',
  'te.eg.intl.desc': 'For international business travel, Egypt follows the same Income Tax Law framework — reimbursements of actual travel expenses (accommodation, meals, transport) are tax-free for the employee if genuine and documented.\n\nThere is no government-published rate table for private sector international per diem. Many Egyptian multinationals and private companies reference U.S. State Department per diem rates or UN ICSC rates as benchmarks.\n\nU.S. State Department benchmark rates for Egypt (for reference):\n  • Cairo: Lodging USD 175/night + M&IE USD 98/day\n  • Alexandria / other cities: lower rates (check State Dept for current figures)\n\nElectronic invoicing note: Since January 2025, Egypt requires electronic receipts for tax-deductible business expenses. Ensure international travel costs are supported by proper electronic invoices where available.',
  'te.eg.intl.source': 'Travel allowances for international business trips follow the same IIT exemption framework',
  'te.eg.intl.h.0': 'Destination',
  'te.eg.intl.h.1': 'Reference Rate (USD/day)',
  'te.eg.intl.h.2': 'Source Type',
  'te.eg.intl.r.0.0': 'Cairo (US State Dept benchmark — 2025)',
  'te.eg.intl.r.0.1': 'Lodging: USD 175/night | M&IE: USD 98/day',
  'te.eg.intl.r.0.2': 'Market Practice',
  'te.eg.intl.r.1.0': 'Alexandria / other Egyptian cities',
  'te.eg.intl.r.1.1': 'Lower than Cairo — verify with US State Dept rates',
