  /* ── Finland (FI) ── */
  'te.fi.dom.title': 'Domestic Business Trip',
  'te.fi.dom.desc': 'Finland has government-set maximum per diem rates published annually by the Finnish Tax Administration (Vero). These apply to ALL employers — amounts within the limits are fully tax-free.\n\n2025 domestic rates (effective 1 Jan 2025):\n  • Partial per diem (trip 6–10 hours): €24/day\n  • Full per diem (trip over 10 hours): €53/day\n  • Meal allowance (no per diem paid, eating away from normal workplace): €13.25/day\n  • Night travel allowance (min. 4 hours between 21:00–07:00): €16/day\n\nKey conditions:\n  • Destination must be more than 15 km from employer or employee\'s home\n  • AND more than 5 km from both workplace AND home\n  • Accommodation: actual receipted cost (no flat rate for accommodation)\n\nMeal deductions (if employer provides meals):\n  • 1 free meal = 50% reduction on partial per diem / for full per diem: no reduction for 1 meal; 50% reduction for 2 free meals\n\nEmployers can pay more than the Vero maximum — the excess is taxable income. Employees with no signed employment contract do NOT qualify for tax-free per diem.',
  'te.fi.dom.source': 'Finnish Tax Administration (Vero) — Tax-exempt allowances 2025 decision',
  'te.fi.dom.h.0': 'Allowance Type / Trip Duration',
  'te.fi.dom.h.1': 'Rate (EUR — 2025)',
  'te.fi.dom.h.2': 'Source Type',
  'te.fi.dom.r.0.0': 'Partial per diem — trip 6 to 10 hours',
  'te.fi.dom.r.0.1': '€24/day',
  'te.fi.dom.r.0.2': 'Statutory',
  'te.fi.dom.r.1.0': 'Full per diem — trip over 10 hours',
  'te.fi.dom.r.1.1': '€53/day',
  'te.fi.dom.r.1.2': 'Statutory',
