  'te.fi.dom.r.3.0': 'Night travel allowance (min. 4h between 21:00–07:00)',
  'te.fi.dom.r.3.1': '€16/day',
  'te.fi.dom.r.3.2': 'Statutory',
  'te.fi.dom.r.4.0': 'Accommodation',
  'te.fi.dom.r.4.1': 'Actual receipted cost — no flat rate',
  'te.fi.dom.r.4.2': 'Statutory',
  'te.fi.dom.r.5.0': '50% deduction — 2+ free meals provided',
  'te.fi.dom.r.5.1': 'Per diem reduced by half',
  'te.fi.dom.r.5.2': 'Statutory',
  'te.fi.dom.r.6.0': 'Excess above Vero limit',
  'te.fi.dom.r.6.1': 'Taxable income subject to IIT',
  'te.fi.dom.r.6.2': 'Statutory',
  'te.fi.intl.title': 'International Business Trips',
  'te.fi.intl.desc': 'For international trips, Finland publishes country-specific maximum per diem rates annually. The rate depends on the country where the travel day ENDS (last overnight location).\n\nKey rules:\n  • Full rate applies for trips lasting at least 24 hours (per day)\n  • If return extends by 2–10 hours beyond last full day: half rate for that extra day\n  • If return extends by 10+ hours: full rate for that extra day\n  • 50% deduction if 2+ free meals provided\n  • Accommodation: actual receipted cost only — no flat international rate\n  • Night travel (abroad, no accommodation): €18 flat allowance if applicable\n\nRates below are 2025 rates from the Vero annual decision. Selected key countries shown — refer to vero.fi for the complete 200+ country table.',
  'te.fi.intl.source': 'Vero decision includes full country-by-country international per diem table for 2025',
  'te.fi.intl.h.0': 'Country / Region',
  'te.fi.intl.h.1': 'Max Per Diem (EUR — 2025)',
