  /* ── France (FR) ── */
  'te.fr.dom.title': 'Domestic Business Trip — Grand Déplacement',
  'te.fr.dom.desc': 'France has URSSAF-published maximum per diem (indemnité de grand déplacement) rates that apply to all employers. These define the social-insurance-free ceiling. Amounts within these limits are also income-tax-free.\n\nGrand déplacement (long-distance trip) applies when BOTH conditions are met:\n  • Distance between home and work site ≥ 50 km (one way)\n  • AND no public transport can cover it in under 1h30 (one way)\n  → Employee is unable to return home each day\n\n2025 domestic rates (URSSAF — Arrêté du 4 septembre 2025):\n  Meals:\n    • Grand déplacement (unable to return home): €21.10/meal (any duration)\n    • Meal at restaurant — short displacement: €21.10/meal\n    • Snack/meal outside workplace: €10.30\n    • Meal on work premises (shift/night work): €7.40\n\n  Accommodation (first 3 months):\n    • Paris & inner suburbs (92, 93, 94): €75.60/night\n    • Other French metropolitan areas: €56.10/night\n  After month 3: 15% reduction. After month 25: 30% reduction. After 6 years: no more tax-free exemption.\n\nNote: Employers may also reimburse actual receipted costs (frais réels) — in that case no ceiling applies as long as amounts are genuine and documented.',
  'te.fr.dom.source': 'URSSAF — Frais professionnels: plafonds 2025 (Arrêté du 4 septembre 2025 + Bulletin officiel SS)',
  'te.fr.dom.h.0': 'Allowance Category',
  'te.fr.dom.h.1': 'Rate (EUR — 2025)',
  'te.fr.dom.h.2': 'Source Type',
  'te.fr.dom.r.0.0': 'Grand déplacement — meal (unable to return home)',
  'te.fr.dom.r.0.1': '€21.10/meal',
  'te.fr.dom.r.0.2': 'Statutory',
  'te.fr.dom.r.1.0': 'Short displacement — meal at restaurant',
