  'te.fr.dom.r.8.1': 'No social-insurance exemption — fully taxable',
  'te.fr.dom.r.8.2': 'Statutory',
  'te.fr.intl.title': 'International Business Trips',
  'te.fr.intl.desc': 'For international business travel, France uses destination-specific rates published monthly by the Ministry of Europe and Foreign Affairs for civil servants. These rates are the legal benchmark for social-insurance-free reimbursement in the private sector.\n\nTwo components:\n  • Meal/incidentals per diem: varies by country (see table)\n  • Accommodation: reimbursed at actual receipted cost. If no accommodation is paid by employer, a flat indemnité de logement applies based on the destination country rate\n\nPrivate sector: no statutory obligation to follow these rates, but using them guarantees social-insurance and income-tax exemption. Amounts above the official rate are subject to social contributions.\n\nKey selected rates (EUR/day — representative 2025 figures based on Ministry scale). Full current table: https://www.legifrance.gouv.fr (search arrêté indemnités mission étranger)',
  'te.fr.intl.source': 'Foreign travel rates: barème Ministry of Europe & Foreign Affairs published monthly for civil servants',
