  /* ── Georgia (GE) ── */
  'te.ge.dom.title': 'Domestic Business Trip',
  'te.ge.dom.desc': 'Georgia has a statutory tax-free ceiling for employee business travel allowances under the Tax Code of Georgia.\n\nDomestic per diem — tax-free ceiling:\n  • GEL 30 per day (within the territory of Georgia)\n  • This is the maximum daily allowance that can be paid to an employee tax-free under the Georgian Tax Code\n  • Amounts above GEL 30/day are treated as taxable employment income (IIT at 20%)\n\nAdditional components (also tax-free if genuine and documented):\n  • Transportation costs: reimbursed at actual cost against receipts\n  • Hotel/accommodation: reimbursed at actual cost against receipts\n\nWho this applies to:\n  • Employees of Georgian companies, including local and foreign employees with their primary workplace in Georgia\n  • The GEL 30 ceiling applies to ALL employers — public and private sector\n\nNote: GEL (Georgian Lari) is the local currency. At the time of this publication, USD 1 ≈ GEL 2.70 (verify current exchange rate with National Bank of Georgia: nbg.gov.ge).',
  'te.ge.dom.source': 'Tax Code of Georgia — business travel allowance provisions for employees',
  'te.ge.dom.h.0': 'Category',
  'te.ge.dom.h.1': 'Rate',
  'te.ge.dom.h.2': 'Source Type',
  'te.ge.dom.r.0.0': 'Daily allowance — within Georgia',
  'te.ge.dom.r.0.1': 'GEL 30/day (maximum tax-free ceiling)',
  'te.ge.dom.r.0.2': 'Statutory',
  'te.ge.dom.r.1.0': 'Amounts above GEL 30/day',
  'te.ge.dom.r.1.1': 'Taxable employment income — subject to IIT at 20%',
  'te.ge.dom.r.1.2': 'Statutory',
  'te.ge.dom.r.2.0': 'Transportation costs',
  'te.ge.dom.r.2.1': 'Actual cost — fully tax-free with receipts',
  'te.ge.dom.r.2.2': 'Statutory',
  'te.ge.dom.r.3.0': 'Accommodation within Georgia',
  'te.ge.dom.r.3.1': 'Actual cost — fully tax-free with receipts',
  'te.ge.dom.r.3.2': 'Statutory',
  'te.ge.intl.title': 'International Business Trips',
  'te.ge.intl.desc': 'For international travel, the Georgian Tax Code provides that employee allowances are tax-free up to amounts that vary by destination country.\n\nThe specific international rates are determined by reference to destination country cost of living and are not a single published table in Georgia — employers typically use one of these references:\n  1. U.S. State Department or UN ICSC rates for the destination country\n  2. Company-specific international travel policy\n  3. KPMG / Deloitte benchmarks for the destination\n\nTax treatment: Reasonable international travel reimbursements (accommodation, meals, incidentals) with supporting documentation are NOT subject to Georgian IIT. Amounts deemed unreasonable or without documentation may be reclassified as taxable employment income.\n\nIIT rate in Georgia: flat 20% on employment income.\nNo social insurance system in Georgia (pension contributions apply separately under the Accumulative Pension Law, 2019).',
  'te.ge.intl.source': 'International rates vary by country — employer determines reasonable amount per destination',
  'te.ge.intl.h.0': 'Category / Destination',
