  /* ── Germany (DE) ── */
  'te.de.dom.title': 'Domestic Business Trip — Verpflegungsmehraufwand',
  'te.de.dom.desc': 'Germany has statutory per diem (Verpflegungsmehraufwand) rates set under the Income Tax Act (EStG §9(4a)). These apply to ALL employers and are fully tax-free up to the statutory ceiling.\n\n2025 domestic rates (UNCHANGED since 2020):\n  • Trip under 8 hours: €0 (no allowance)\n  • Trip 8 to 24 hours OR day of arrival/departure on multi-day trips: €14/day\n  • Full day (24 hours): €28/day\n  • Overnight lump sum (if no accommodation receipts): €20/night\n\nKey rules:\n  • Multiple trips in one day can be combined — if total ≥ 8h, €14 applies\n  • 3-month rule (Dreimonatsfrist): Tax-free per diem can only be paid for the first 3 consecutive months at the same temporary workplace. After a 4-week break, the 3-month clock resets\n  • Deductions if meals are provided free: breakfast −20%, lunch −40%, dinner −40% (based on the full per diem amount for that day)\n  • All invoices >€150 must show employer name, address, and VAT amount\n  • Original receipts must be physically or digitally backed up in the EU',
  'te.de.dom.source': 'BMF (Bundesministerium der Finanzen) letter; Income Tax Act §4 and §9 — 2025 domestic rates unchanged since 2020',
  'te.de.dom.h.0': 'Trip Duration / Category',
  'te.de.dom.h.1': 'Rate (EUR — 2025)',
  'te.de.dom.h.2': 'Source Type',
  'te.de.dom.r.0.0': 'Trip under 8 hours',
