  'te.de.dom.r.7.2': 'Statutory',
  'te.de.dom.r.8.0': 'Above statutory rate',
  'te.de.dom.r.8.1': 'Employer may pay more — excess is taxable income + social contributions',
  'te.de.dom.r.8.2': 'Statutory',
  'te.de.intl.title': 'International Business Trips',
  'te.de.intl.desc': 'For international trips, Germany uses destination-specific rates published annually by the Federal Ministry of Finance (BMF) in December for the following year.\n\nEach destination has three rates:\n  1. Full daily rate (24h absence)\n  2. Arrival/departure day rate (also applies if absent 8+ hours on that calendar day)\n  3. Overnight accommodation lump sum\n\nKey rules (same as domestic):\n  • Same deduction rules for free meals (20%/40%/40%)\n  • Same 3-month rule applies\n  • If country not listed: Luxembourg rate applies as default\n  • For overseas territories of a listed country: use the mainland rate\n\nAll rates in EUR. Source: BMF letter 5 December 2024 (rates for 2025).',
  'te.de.intl.source': 'Steuerliche Behandlung von Reisekosten und Reisekostenvergütungen bei Auslandsreisen ab 1. Januar 2025',
