  /* ── Greece (GR) ── */
  'te.gr.dom.title': 'Domestic Business Trip',
  'te.gr.dom.desc': 'Greece has a statutory per diem minimum under the Individual Labour Law Code (Art. 144). Unlike most EU countries, the Greek per diem is treated as TAXABLE INCOME — it is added to the employee\'s salary and taxed at their applicable income tax bracket.\n\nPer diem minimum (effective 1 April 2025, following minimum wage increase):\n  • Per diem = statutory daily minimum wage OR 1/25 of the statutory monthly minimum wage\n  • Statutory minimum daily wage (from 1 Apr 2025): €39.30/day (blue-collar workers)\n  • 1/25 of monthly minimum wage (from 1 Apr 2025): €880 ÷ 25 = €35.20/day\n\nIMPORTANT UPDATE: From 1 April 2026, minimum wage increased to €920/month.\n  • New 1/25 rate: €920 ÷ 25 = €36.80/day\n  • New daily minimum wage (blue-collar): €41.09/day\n\nKey rules:\n  • Per diem is mandatory when the employee spends the night away from home\n  • Rate applies regardless of the destination — same for all domestic locations\n  • Per diem applies per night away (not per calendar day)\n  • ALL per diem is TAXABLE as employment income (progressive IIT 9%–44%)\n\nMeal deductions (if employer provides):\n  • Food and accommodation both provided: per diem reduced by 3/4 (only 1/4 paid)\n  • Food only provided: per diem reduced by 1/2\n  • Accommodation only provided: per diem reduced by 1/5\n\nTravel expenses (flights, trains, accommodation receipts) are reimbursed separately and are NOT subject to income tax if for genuine business purposes and documented.',
  'te.gr.dom.source': 'Individual Labour Law Code Art. 144 — per diem obligation; Greek Income Tax Code Law 4172/2013',
  'te.gr.dom.h.0': 'Category',
  'te.gr.dom.h.1': 'Rate / Amount',
  'te.gr.dom.h.2': 'Source Type',
  'te.gr.dom.r.0.0': 'Statutory daily minimum wage (from 1 Apr 2025) — blue-collar',
  'te.gr.dom.r.0.1': '€39.30/day',
  'te.gr.dom.r.0.2': 'Statutory',
  'te.gr.dom.r.1.0': '1/25 of monthly minimum wage (from 1 Apr 2025) — white-collar',
  'te.gr.dom.r.1.1': '€35.20/day (€880 ÷ 25)',
  'te.gr.dom.r.1.2': 'Statutory',
  'te.gr.dom.r.2.0': 'Statutory daily minimum wage (from 1 Apr 2026)',
  'te.gr.dom.r.2.1': '€41.09/day',
  'te.gr.dom.r.2.2': 'Statutory',
  'te.gr.dom.r.3.0': '1/25 of monthly minimum wage (from 1 Apr 2026)',
  'te.gr.dom.r.3.1': '€36.80/day (€920 ÷ 25)',
  'te.gr.dom.r.3.2': 'Statutory',
  'te.gr.dom.r.4.0': 'Tax treatment',
  'te.gr.dom.r.4.1': 'FULLY TAXABLE — added to salary, taxed at employee\'s IIT bracket (9%–44%)',
  'te.gr.dom.r.4.2': 'Statutory',
  'te.gr.dom.r.5.0': 'Employer provides food AND accommodation',
  'te.gr.dom.r.5.1': 'Per diem reduced to 1/4 of the standard rate',
  'te.gr.dom.r.5.2': 'Statutory',
  'te.gr.dom.r.6.0': 'Employer provides food only',
  'te.gr.dom.r.6.1': 'Per diem reduced to 1/2 of the standard rate',
  'te.gr.dom.r.6.2': 'Statutory',
  'te.gr.dom.r.7.0': 'Employer provides accommodation only',
  'te.gr.dom.r.7.1': 'Per diem reduced to 4/5 of the standard rate',
  'te.gr.dom.r.7.2': 'Statutory',
  'te.gr.dom.r.8.0': 'Travel expenses (flights, hotels, trains) — receipted',
  'te.gr.dom.r.8.1': 'Separate reimbursement — NOT taxable if for genuine business',
  'te.gr.dom.r.8.2': 'Tax Authority Guideline',
  'te.gr.intl.title': 'International Business Trips',
  'te.gr.intl.desc': 'The same framework applies for international trips. The per diem is set at the statutory daily minimum wage or 1/25 of the monthly minimum wage — the SAME rate as for domestic travel. There is no separate international rate table under Greek employment law.\n\nPer diem remains TAXABLE as employment income for international trips.\n\nEuropean Commission reference rates (for benchmarking — not legally binding for private sector in Greece):\n  • Greece (inbound): €82/day + €140/night accommodation (EC 2022 rates)\n  • For outbound trips, EC publishes country-specific rates (see ec.europa.eu)\n\nMany multinational companies operating in Greece use higher international per diem rates aligned with EC or U.S. State Dept benchmarks. These are fully valid but the entire per diem remains taxable. Only actual receipted expenses (flights, hotels) reimbursed separately are non-taxable.',
  'te.gr.intl.source': 'PwC Tax Summaries — Greece individual income determination; EC per diem rates for foreign reference',
  'te.gr.intl.h.0': 'Category / Region',
  'te.gr.intl.h.1': 'Rate / Amount',
  'te.gr.intl.h.2': 'Source Type',
  'te.gr.intl.r.0.0': 'Per diem for international trips',
  'te.gr.intl.r.0.1': 'Same statutory minimum as domestic — fully taxable as employment income',
  'te.gr.intl.r.0.2': 'Statutory',
  'te.gr.intl.r.1.0': 'EC reference rate — Greece (inbound travel to Greece)',
  'te.gr.intl.r.1.1': '€82/day meals + €140/night accommodation',
  'te.gr.intl.r.1.2': 'Government Benchmark',
  'te.gr.intl.r.2.0': 'EC reference — Western Europe (France, Germany, UK, etc.)',
  'te.gr.intl.r.2.1': '€95–€120/day (EC table varies by country)',
