  /* ── Hungary (HU) ── */
  'te.hu.dom.title': 'Domestic Business Trip',
  'te.hu.dom.desc': 'Hungary has a statutory minimum domestic per diem (napidíj) under Government Decree 437/2015 (XII.28.) for employees on business trips.\n\nDomestic per diem:\n  • Minimum rate: HUF 500/day (statutory minimum under Decree 437/2015)\n  • Exception: Employees working as drivers or cargo attendants in domestic road freight/passenger transport: HUF 9,000/day (Government Order 96/2023, effective 30 March 2023)\n\nTax treatment for domestic per diem:\n  • The HUF 500 statutory flat-rate daily allowance is treated as TAXABLE income (taxed as wages at the flat 15% PIT rate plus 18.5% social security contribution)\n  • Employer can alternatively reimburse actual meal expenses via invoices — this is taxed as a \'specific defined benefit\': tax base = amount × 1.18, subject to 15% PIT + 13% social contribution payable by the EMPLOYER\n\nNot eligible for per diem:\n  • Trips lasting less than 6 hours on that day\n  • If employer provides food for the employee during the trip\n\nAccommodation: Reimbursed at actual cost with receipts — separate from per diem.',
  'te.hu.dom.source': 'NAV (National Tax and Customs Administration) — personal income tax and per diem treatment',
  'te.hu.dom.h.0': 'Category',
  'te.hu.dom.h.1': 'Rate / Amount',
  'te.hu.dom.h.2': 'Source Type',
  'te.hu.dom.r.0.0': 'Statutory minimum per diem — standard employees',
  'te.hu.dom.r.0.1': 'HUF 500/day (taxable as wages)',
  'te.hu.dom.r.0.2': 'Statutory',
  'te.hu.dom.r.1.0': 'Per diem — drivers/cargo attendants (road transport)',
  'te.hu.dom.r.1.1': 'HUF 9,000/day (Government Order 96/2023, from 30 Mar 2023)',
  'te.hu.dom.r.1.2': 'Statutory',
  'te.hu.dom.r.2.0': 'Tax treatment — flat daily allowance',
  'te.hu.dom.r.2.1': 'Taxable: 15% PIT + 18.5% social security (employee)',
  'te.hu.dom.r.2.2': 'Statutory',
  'te.hu.dom.r.3.0': 'Alternative: meal invoice reimbursement',
  'te.hu.dom.r.3.1': 'Tax base = amount × 1.18 → 15% PIT + 13% social tax (employer)',
  'te.hu.dom.r.3.2': 'Statutory',
  'te.hu.dom.r.4.0': 'No per diem if trip < 6 hours that day',
  'te.hu.dom.r.4.1': 'Trip must be ≥ 6 hours AND employer must not provide free food',
  'te.hu.dom.r.4.2': 'Statutory',
  'te.hu.dom.r.5.0': 'Accommodation',
  'te.hu.dom.r.5.1': 'Actual receipted cost — reimbursed separately',
  'te.hu.dom.r.5.2': 'Statutory',
  'te.hu.intl.title': 'International Business Trips',
  'te.hu.intl.desc': 'For international business trips, Hungary does NOT publish a country-specific per diem rate table. The employer determines the allowance amount.\n\nCritical tax rule (Hungarian Personal Income Tax Act — SZJA):\n  • Only 30% of the daily meal allowance for foreign trips is NON-TAXABLE\n  • This 30% non-taxable portion is capped at a MAXIMUM of EUR 15/day\n  • Therefore: maximum tax-free meal allowance per day = EUR 15\n  • Any amount above this 30%/EUR 15 ceiling is taxable income for the employee\n\nExample:\n  • Employer pays EUR 50/day for a trip to Germany\n  • Tax-free portion: 30% × EUR 50 = EUR 15 (within the EUR 15 cap)\n  • Taxable portion: EUR 50 − EUR 15 = EUR 35 (taxed as wages)\n\nOther components reimbursed separately:\n  • Accommodation: actual receipted cost — NOT subject to this EUR 15 cap\n  • Transportation (flights, trains): actual receipted cost — fully reimbursable\n  • Business-related costs (taxis, parking, phone): actual receipted costs\n\nTiming: For foreign trips, per diem is not paid for periods under 8 hours abroad. If the trip exceeds 8 hours, the full daily allowance is granted.',
  'te.hu.intl.source': 'Only 30% of foreign daily meal allowance is tax-free, capped at EUR 15/day (SZJA provisions)',
  'te.hu.intl.h.0': 'Category',
  'te.hu.intl.h.1': 'Rate / Tax Treatment',
  'te.hu.intl.h.2': 'Source Type',
  'te.hu.intl.r.0.0': 'No country-specific statutory rate',
  'te.hu.intl.r.0.1': 'Employer determines the daily allowance amount freely',
  'te.hu.intl.r.0.2': 'Market Practice',
  'te.hu.intl.r.1.0': 'Tax-free portion of meal allowance',
  'te.hu.intl.r.1.1': '30% of the daily meal allowance, capped at maximum EUR 15/day',
  'te.hu.intl.r.1.2': 'Statutory',
  'te.hu.intl.r.2.0': 'Above EUR 15/day (or above 30% if lower)',
  'te.hu.intl.r.2.1': 'TAXABLE as employment income — PIT 15% + social contributions',
  'te.hu.intl.r.2.2': 'Statutory',
  'te.hu.intl.r.3.0': 'Minimum trip duration to qualify',
  'te.hu.intl.r.3.1': 'Must be at least 8 hours abroad to receive international per diem',
  'te.hu.intl.r.3.2': 'Statutory',
  'te.hu.intl.r.4.0': 'Accommodation',
