  /* ── India (IN) ── */
  'te.in.dom.title': 'Domestic Business Trip — Daily Allowance',
  'te.in.dom.desc': 'India has NO government-mandated per diem rate for private sector employers. Companies set their own rates.\n\nTax treatment — Business travel daily allowance:\nUnder Section 10(14)(i) of the Income Tax Act 1961 and CBDT Rule 2BB:\n  • Any daily allowance granted to meet ORDINARY DAILY CHARGES incurred by an employee due to absence from normal place of duty is FULLY EXEMPT from income tax\n  • There is NO prescribed ceiling on this exemption — the entire amount is tax-free as long as it is genuinely for business travel\n  • This applies under BOTH the old and the new tax regimes\n\nImportant distinction:\n  • Business travel daily allowance (Section 10(14)(i)): Fully tax-free, no cap\n  • Leave Travel Allowance / LTA (Section 10(5)): For personal vacation travel within India only, 2 claims per 4-year block (2022–2025 block), OLD REGIME ONLY\n  • LTA covers ONLY actual travel costs — NOT meals, hotels, or sightseeing\n\nGovernment / public sector: Central government employees follow the TA/DA rules under FR/SR (Fundamental Rules / Supplementary Rules). Rates are grade-based:\n  • Grade Pay ≥ INR 10,000: INR 500/day (meals) + hotels per tier\n  • Grade Pay INR 5,400–9,999: INR 300/day\n  • Grade Pay INR 1,800–4,799: INR 240/day\nPrivate sector commonly references these or uses market-standard amounts.',
  'te.in.dom.source': 'CBDT Rule 2BB — daily allowance to meet ordinary daily charges on business tour: fully tax-exempt with no cap',
  'te.in.dom.h.0': 'Category',
  'te.in.dom.h.1': 'Rate / Amount',
  'te.in.dom.h.2': 'Source Type',
  'te.in.dom.r.0.0': 'Business travel daily allowance — private sector',
  'te.in.dom.r.0.1': 'Per company policy — no statutory rate',
  'te.in.dom.r.0.2': 'Market Practice',
  'te.in.dom.r.1.0': 'Tax exemption (IT Act S.10(14)(i) + Rule 2BB)',
  'te.in.dom.r.1.1': 'FULLY exempt from IIT — no cap — both old & new tax regimes',
  'te.in.dom.r.1.2': 'Statutory',
  'te.in.dom.r.2.0': 'Leave Travel Allowance (LTA) — Section 10(5)',
  'te.in.dom.r.2.1': 'Tax-free for 2 trips per 4-year block (2022–2025); domestic India only; OLD REGIME ONLY',
  'te.in.dom.r.2.2': 'Statutory',
  'te.in.dom.r.3.0': 'LTA coverage',
  'te.in.dom.r.3.1': 'Only actual travel costs (transport tickets) — NOT meals, hotels, sightseeing',
  'te.in.dom.r.3.2': 'Statutory',
  'te.in.dom.r.4.0': 'Govt — Grade Pay ≥ INR 10,000 (senior officers)',
  'te.in.dom.r.4.1': 'INR 500/day meals; accommodation per city tier',
  'te.in.dom.r.4.2': 'Government Benchmark',
  'te.in.dom.r.5.0': 'Govt — Grade Pay INR 5,400–9,999',
  'te.in.dom.r.5.1': 'INR 300/day meals; accommodation per city tier',
  'te.in.dom.r.5.2': 'Government Benchmark',
  'te.in.dom.r.6.0': 'Govt — Grade Pay INR 1,800–4,799',
  'te.in.dom.r.6.1': 'INR 240/day meals; accommodation per city tier',
  'te.in.dom.r.6.2': 'Government Benchmark',
  'te.in.intl.title': 'International Business Trips',
  'te.in.intl.desc': 'For international travel, there is also no statutory rate for private sector. Business travel reimbursements remain non-taxable under Section 10(14)(i) if for genuine business purposes.\n\nFEMA and RBI context: Overseas travel expenditure by Indian residents is subject to Foreign Exchange Management Act (FEMA) limits. Banks can release foreign exchange for business travel up to USD 25,000 per trip without RBI approval (subject to company policy and purpose documentation).\n\nTax treatment — international per diem:\n  • Per diems paid as daily allowance for official business trips abroad are tax-free under Section 10(14)(i) — no cap, provided genuinely for business\n  • Excess over actual costs or amounts not linked to business purposes are taxable as salary income\n\nGovernment (Ministry of External Affairs) benchmark for officers traveling abroad:\n  • Class A cities (US, UK, Japan, Australia, Singapore, Switzerland, France, Germany): USD 270–350/day (includes accommodation component)\n  • Class B cities (Southeast Asia, Middle East): USD 180–250/day\n  • Class C cities (South Asia, Africa, Eastern Europe): USD 120–180/day\n\nPrivate sector commonly uses US State Dept or similar benchmarks as reference.',
  'te.in.intl.source': 'LTA covers personal vacation travel within India only; international travel not covered by LTA',
  'te.in.intl.h.0': 'Category / Destination',
  'te.in.intl.h.1': 'Rate / Notes',
  'te.in.intl.h.2': 'Source Type',
