  /* ── Indonesia (ID) ── */
  'te.id.dom.title': 'Domestic Business Trip',
  'te.id.dom.desc': 'Indonesia has NO government-mandated per diem rate for private sector employers. Employers have full flexibility in setting travel allowance policies.\n\nTax treatment under Indonesian Income Tax Law (PPh Pasal 21 / Article 21):\n  • Business travel reimbursements paid to employees are generally NOT subject to income tax (PPh 21) provided:\n    1. The reimbursement is for genuine business travel costs\n    2. Supported by valid receipts or tax invoices (faktur pajak)\n    3. Amounts are reasonable and not disguised as salary\n\n  • Flat-rate cash allowances (uang harian / uang saku) paid without receipt substantiation ARE treated as taxable employment income (PPh 21), subject to progressive IIT rates of 5%–35%\n\nGovernment / public sector reference (Peraturan Menteri Keuangan — PMK):\nThe Ministry of Finance sets per diem rates for government employees annually.\n  • Uang harian (daily allowance): IDR 500,000–1,100,000/day (grade-based)\n  • Accommodation: IDR 500,000–2,200,000/night (city tier and grade)\n  • These are benchmarks used by many private companies for reference\n\nAll amounts in Indonesian Rupiah (IDR). USD 1 ≈ IDR 15,800–16,000 (2025).',
  'te.id.dom.source': 'PMK-81/2024 (Coretax) + Income Tax Law — business travel reimbursement treatment',
  'te.id.dom.h.0': 'Category',
  'te.id.dom.h.1': 'Rate / Amount',
  'te.id.dom.h.2': 'Source Type',
  'te.id.dom.r.0.0': 'Private sector',
  'te.id.dom.r.0.1': 'Per company policy — no statutory rate',
  'te.id.dom.r.0.2': 'Market Practice',
