  'te.id.dom.r.5.1': 'IDR 500,000–800,000/day (approx. USD 31–50)',
  'te.id.dom.r.5.2': 'Government Benchmark',
  'te.id.dom.r.6.0': 'Govt accommodation — Tier 1 cities (Jakarta, Surabaya, Bali)',
  'te.id.dom.r.6.1': 'IDR 1,500,000–2,200,000/night',
  'te.id.dom.r.6.2': 'Government Benchmark',
  'te.id.dom.r.7.0': 'Govt accommodation — other cities',
  'te.id.dom.r.7.1': 'IDR 500,000–1,200,000/night',
  'te.id.dom.r.7.2': 'Government Benchmark',
  'te.id.intl.title': 'International Business Trips',
  'te.id.intl.desc': 'For international travel, Indonesia also has no mandatory per diem for private sector.\n\nTax treatment:\n  • Same rule applies — actual receipted international travel costs are non-taxable\n  • Flat cash allowances without receipts are taxable PPh 21\n  • Coretax (PMK-81/2024, effective Jan 2025) strengthens documentation requirements\n\nGovernment reference rates for international travel (Ministry of Finance — selected):\n  • Tier I (US, UK, Japan, Singapore, Australia): USD 300–400/day\n  • Tier II (Europe, Canada, South Korea, UAE): USD 220–320/day\n  • Tier III (Southeast Asia, Middle East, China): USD 160–250/day\n  • Tier IV (South Asia, Africa, Eastern Europe): USD 120–200/day\n\nNote: Indonesian government uses USD for international travel rates.\nPrivate sector commonly uses the Ministry of Finance scale or US State Dept rates.',
  'te.id.intl.source': 'Same income tax framework applies; actual receipted expenses are non-taxable',
  'te.id.intl.h.0': 'Destination / Tier',
