  /* ── Iraq (IQ) ── */
  'te.iq.dom.title': 'Domestic Business Trip',
  'te.iq.dom.desc': 'Iraq has NO published government-mandated per diem rate for private sector employers. Companies set their own travel allowance policies.\n\nTax treatment under Iraqi Income Tax Law No. 113 of 1982 (as amended):\n  • Legally documented business expenses incurred in producing income in Iraq are generally deductible for the employer\n  • For the EMPLOYEE: risk allowances are exempt from income tax up to 30% of basic salary. Standard travel reimbursements for genuine business travel are generally NOT treated as taxable income for the employee if:\n    1. The travel is for genuine business purposes\n    2. Supported by documentation (travel orders, receipts)\n    3. Amounts are reasonable\n\nPersonal allowances (private sector employees, 2025):\n  • Single person: IQD 2,500,000/year deduction\n  • Married person: IQD 4,500,000/year deduction\n\nKurdistan Region of Iraq (KRI): Employees have a tax-free legal allowance of IQD 1,000,000/month. The KRI has a more stable and business-friendly environment than the rest of Iraq. Separate KRI investment law applies.\n\nNote: Since January 2024, all domestic commercial transactions must be executed in Iraqi Dinar (IQD) — including internal business travel payments.\nIQD exchange rate: USD 1 ≈ IQD 1,310 (official rate).',
  'te.iq.dom.source': 'Ministry of Finance Iraq — Income Tax Law; business travel expenses deductibility rules',
  'te.iq.dom.h.0': 'Category',
  'te.iq.dom.h.1': 'Rate / Amount',
  'te.iq.dom.h.2': 'Source Type',
  'te.iq.dom.r.0.0': 'Private sector — domestic per diem',
