  'te.iq.dom.r.4.0': 'Personal allowance — married employee',
  'te.iq.dom.r.4.1': 'IQD 4,500,000/year',
  'te.iq.dom.r.4.2': 'Statutory',
  'te.iq.dom.r.5.0': 'Kurdistan Region (KRI) — tax-free monthly allowance',
  'te.iq.dom.r.5.1': 'IQD 1,000,000/month per employee',
  'te.iq.dom.r.5.2': 'Statutory',
  'te.iq.dom.r.6.0': 'Domestic transaction currency requirement (from Jan 2024)',
  'te.iq.dom.r.6.1': 'All domestic payments must be in IQD (Iraqi Dinar)',
  'te.iq.dom.r.6.2': 'Statutory',
  'te.iq.intl.title': 'International Business Trips',
  'te.iq.intl.desc': 'For international business travel from Iraq, the same general principle applies — actual receipted travel expenses are deductible for the employer and not taxable for the employee if genuinely for business.\n\nThere is no Iraqi government-published per diem rate table for international travel.\n\nU.S. State Department reference rates for travel TO Iraq (2025):\n  • Baghdad — on USG compounds/military: Lodging $100 + M&IE $54/day\n  • Baghdad — local hotels: Lodging $100 + M&IE $54/day\n  • Other Iraq — on USG compounds/military: Lodging $247 + M&IE $82/day\n  • Other Iraq — local hotels: Lodging $247 + M&IE $82/day\n\nThese are inbound rates for travelers going TO Iraq. For Iraqis or Iraq-based employees traveling INTERNATIONALLY, private companies reference the US State Dept or UN ICSC rates for the destination country.\n\nSecurity context: Iraq\'s high-risk environment means many multinationals operating in Iraq apply elevated per diem rates. Oil sector companies (common in Iraq) often set premium rates reflecting security costs and restricted movement.',
  'te.iq.intl.source': 'US State Dept: Baghdad lodging $100 + M&IE $54; Other Iraq: lodging $247 + M&IE $82',
