  /* ── Ireland (IE) ── */
  'te.ie.dom.title': 'Domestic Business Trip — Civil Service Subsistence',
  'te.ie.dom.desc': 'Ireland\'s Revenue sets Civil Service subsistence rates, which apply to both public and private sector employers as the maximum tax-free amounts for business travel. Updated rates are in effect from 29 January 2025 (Circular 04/2025).\n\nDay allowances (trip must be >8km from employee\'s home AND usual workplace):\n  • 10+ hours absence: €46.17/day\n  • 5–10 hours absence: €19.25/day\n\nOvernight allowance (must be ≥100km from home AND usual workplace):\n  • Normal rate (up to 14 nights): €205.53/night\n  • Reduced rate (nights 15–28): €184.98/night\n  • Detention rate (nights 29–56): €102.76/night\n  • After 56 nights: apply to Revenue for continued tax-free treatment\n\nVouched Accommodation (VA) — Dublin only:\n  • Actual accommodation cost (up to €205.53) PLUS €46.17 meals\n\nKey rules:\n  • Day allowance AND overnight allowance can be claimed together only if the employee works 5+ hours the next day\n  • Subsistence at any one location is capped at 6 months total\n  • Actual costs can be reimbursed instead — but must not exceed the Civil Service ceiling\n  • Amounts above Civil Service rates are taxable as employment income (PAYE/PRSI/USC)',
  'te.ie.dom.source': 'Revenue.ie — Civil Service subsistence rates; effective 29 January 2025 (Circular 04/2025)',
  'te.ie.dom.h.0': 'Allowance Type / Duration',
  'te.ie.dom.h.1': 'Rate (EUR — eff. 29 Jan 2025)',
  'te.ie.dom.h.2': 'Source Type',
