  'te.ie.dom.r.7.2': 'Statutory',
  'te.ie.dom.r.8.0': 'Short-term assignment abroad — month 1',
  'te.ie.dom.r.8.1': '100% of international rate',
  'te.ie.dom.r.8.2': 'Tax Authority Guideline',
  'te.ie.dom.r.9.0': 'Short-term assignment abroad — months 2–3',
  'te.ie.dom.r.9.1': '75% of international rate',
  'te.ie.dom.r.9.2': 'Tax Authority Guideline',
  'te.ie.dom.r.10.0': 'Short-term assignment abroad — months 4–6',
  'te.ie.dom.r.10.1': '50% of international rate',
  'te.ie.dom.r.10.2': 'Tax Authority Guideline',
  'te.ie.intl.title': 'International Business Trips',
  'te.ie.intl.desc': 'For international travel, Ireland uses country-specific rates set under Circular 07/2017. Each country has overnight rates, VA (vouched accommodation) rates, and hourly rates.\n\nShort-term assignments abroad (up to 6 months):\n  • Month 1: 100% of the applicable international rate\n  • Months 2–3: 75% of the rate\n  • Months 4–6: 50% of the rate\n\nLong-term assignments (over 6 months):\n  • Month 1: overnight rate only (to find accommodation)\n  • After month 1: subsistence costs + portion of 10-hour rate (agreed with Revenue)\n\nSelected international overnight rates (from Circular 07/2017 — in local currency):\nNote: These are overnight rates covering accommodation + meals. A \'10-hour day\' rate and \'5-hour day\' rate also exist per country. Refer to Circular 07/2017 for full table.',
  'te.ie.intl.source': 'International rates under Circular 07/2017 — country-specific overnight, VA, and hourly rates',
