  /* ── Italy (IT) ── */
  'te.it.dom.title': 'Domestic Business Trip — Indennità di Trasferta',
  'te.it.dom.desc': 'Italy sets statutory tax-free ceilings for travel allowances (indennità di trasferta) under TUIR Art. 51(5). These apply to ALL employers — public and private.\n\nThree reimbursement systems exist (employer chooses one):\n\n1. Flat-rate allowance (sistema forfettario) — no receipts needed for the allowance itself:\n   • Domestic trips (outside the employee\'s home municipality): up to €46.48/day tax-free\n   • Above €46.48/day: the EXCESS is taxable as employment income (IRPEF + INPS)\n\n2. Mixed reimbursement (sistema misto) — flat allowance + some receipted costs:\n   • If employer also pays meals: flat allowance ceiling drops to €30.99/day (1/3 reduction)\n   • If employer also pays accommodation: drops to €30.99/day\n   • If both meals and accommodation covered: drops to €15.49/day (2/3 reduction)\n   • Actual meal/accommodation costs reimbursed: fully tax-free (no ceiling)\n\n3. Analytical reimbursement (sistema analitico — a piè di lista) — all costs receipted:\n   • Meals, accommodation, travel, transport: fully tax-free with valid receipts\n   • Ancillary costs (laundry, calls, tips): tax-free up to €15.49/day\n\nIMPORTANT — Tracciability rule from 1 January 2025 (Legge di Bilancio 2025, confirmed by Circolare 15/E/2025):\n   • For domestic trips: meal, accommodation, and taxi/NCC costs must be paid by traceable means (card, bank transfer, digital payment) to remain tax-free for the employee\n   • Cash payments for these domestic expenses may cause the reimbursement to become taxable. Note: Public transport (trains, planes, buses) is EXCLUDED from this rule\n   • For foreign trips: tracability rule does NOT apply — can still use cash abroad',
  'te.it.dom.source': 'Agenzia delle Entrate Circolare 15/E del 22 dicembre 2025 — tracciabilità e trasferte; Legge di Bilancio 2025',
  'te.it.dom.h.0': 'Category / System',
  'te.it.dom.h.1': 'Tax-Free Ceiling (EUR/day)',
  'te.it.dom.h.2': 'Source Type',
  'te.it.dom.r.0.0': 'Flat-rate allowance — no meals/accommodation covered',
