  'te.it.dom.r.6.1': 'Meals, accommodation, taxi/NCC must be paid by card/transfer to remain tax-free',
  'te.it.dom.r.6.2': 'Statutory',
  'te.it.dom.r.7.0': 'Metalmeccanica CCNL (industrial sector benchmark)',
  'te.it.dom.r.7.1': '€40/day full trip',
  'te.it.dom.r.7.2': 'Collective Agreement',
  'te.it.dom.r.8.0': 'Studi professionali CCNL',
  'te.it.dom.r.8.1': '€15/day (8–24h) or €30/day (over 24h)',
  'te.it.dom.r.8.2': 'Collective Agreement',
  'te.it.intl.title': 'International Business Trips',
  'te.it.intl.desc': 'For international business trips, the same TUIR Art. 51(5) ceilings apply but at higher levels reflecting the higher cost of international travel.\n\nFlat-rate allowance ceilings (sistema forfettario) — international:\n  • Full daily allowance (no meals/accommodation covered): up to €77.47/day tax-free\n  • If employer also pays meals OR accommodation: drops to €51.65/day\n  • If employer pays both meals AND accommodation: drops to €25.82/day\n\nMixed and analytical systems work the same as domestic — actual receipted costs for meals, accommodation, transport are fully tax-free. Ancillary expenses: up to €25.82/day.\n\nTracability rule: Does NOT apply to international trips. Expenses can be paid in cash abroad and still qualify as tax-free reimbursements, subject to documentation.\n\nCCNL (national collective agreements): Many sectors set their own per diem levels. Common examples:\n  • Metalmeccanica (industry): €40/day for full day trip\n  • Commercio (trade/retail): minimum = double the daily salary fraction\n  • Studi professionali: €15/day (8–24h), €30/day (over 24h)',
  'te.it.intl.source': 'International per diem: €77.47/day ceiling (flat forfettario, no receipts required for the allowance itself)',
  'te.it.intl.h.0': 'Category / System',
  'te.it.intl.h.1': 'Tax-Free Ceiling (EUR/day)',
  'te.it.intl.h.2': 'Source Type',
