  /* ── Japan (JP) ── */
  'te.jp.dom.title': 'Domestic Business Trip',
  'te.jp.dom.desc': 'Japan has NO government-mandated per diem rate for private sector employers. Each company sets its own rates, but the mechanism and tax treatment are clearly defined by law.\n\nTax treatment under Income Tax Act Art. 9(1)(iv) and NTA guidance:\n  • Per diem (nittou / nicchijou: nittou) paid to employees under a formally adopted \'Business Travel Expense Regulation\' (Ryohi Kisoku: Ryohi Kisoku) is fully NON-TAXABLE\n  • No PIT (shotoku-zei (income tax)) and no inhabitant tax applies on amounts within the Ryohi Kisoku\n  • If no formal Ryohi Kisoku exists, per diem may be treated as taxable salary\n\nRyohi Kisoku requirement:\n  • Company must formally adopt and document travel expense rules\n  • Rates must be \'reasonable\' — not inflated for tax avoidance purposes\n  • NTA conducts tax audits on excessive per diem (especially accommodation rates)\n  • Sole proprietors CANNOT use this system — only corporations\n\nTypical market benchmarks (JPY — vary by company and employee grade):\n  • Director/executive level: JPY 3,000–8,000/day (incidentals)\n  • Manager level: JPY 2,000–5,000/day\n  • Standard employee: JPY 1,000–3,000/day\n  • Accommodation: JPY 8,000–20,000/night (Tokyo/Osaka); JPY 5,000–12,000 (other cities)\n\nNote: Transportation (shinkansen, flights) and accommodation are reimbursed separately at actual cost and are also tax-free within the Ryohi Kisoku framework.',
  'te.jp.dom.source': 'NTA (National Tax Agency) — Income Tax Act Art. 9(1)(iv); business travel expenses (ryohi kisoku) are tax-free',
  'te.jp.dom.h.0': 'Category / Level',
  'te.jp.dom.h.1': 'Typical Rate (JPY/day)',
  'te.jp.dom.h.2': 'Source Type',
