  'te.jp.intl.title': 'International Business Trips',
  'te.jp.intl.desc': 'The same Ryohi Kisoku framework applies for international travel. Per diem paid under a valid company travel regulation is fully tax-free.\n\nNTA guidance: amounts should reflect actual cost of living at the destination. Excessive rates (e.g., JPY 50,000/day incidentals for a standard trip) may be challenged in a tax audit.\n\nTypical private sector international benchmarks (JPY/day — incidentals only; accommodation and transport separate):\n  • North America / Western Europe: JPY 4,000–10,000/day\n  • Asia-Pacific: JPY 3,000–8,000/day\n  • Southeast Asia / South Asia: JPY 2,000–5,000/day\n\nGovernment reference (Ministry of Finance — for government employees):\n  • Published annually in the \'Kokka Koumuin Ryohi Kisoku\' (Ryohi Kisoku)\n  • Rates vary by destination country and employee grade\n  • Many private companies reference these as a benchmarking guide\n\nExample government international accommodation rates:\n  • United States (Grade A+): JPY 35,000–50,000/night\n  • Europe (France, Germany, UK): JPY 30,000–45,000/night\n  • Southeast Asia: JPY 15,000–30,000/night',
  'te.jp.intl.source': 'International travel: same framework — amounts within the company\'s ryohi kisoku are fully tax-free',
  'te.jp.intl.h.0': 'Destination / Category',
  'te.jp.intl.h.1': 'Typical Rate (JPY/night or day)',
  'te.jp.intl.h.2': 'Source Type',
  'te.jp.intl.r.0.0': 'North America / Western Europe — daily incidentals',
