  /* ── Jordan (JO) ── */
  'te.jo.dom.title': 'Domestic Business Trip',
  'te.jo.dom.desc': 'Jordan has NO government-mandated per diem rate specifically for private sector employees. Companies set their own rates.\n\nTax treatment under Income Tax Law No. 34 of 2014 (amended 2018):\n  • Business travel allowances paid to employees are generally DEDUCTIBLE for the employer as legitimate business expenses\n  • For the EMPLOYEE: travel allowances and reimbursements for genuine business travel purposes are generally NOT included in taxable employment income — provided they are reasonable and properly documented\n  • The ISTD assesses reasonableness — amounts that are clearly excessive relative to the actual cost of travel may be reclassified as taxable salary income\n\nKey Jordanian personal income tax context:\n  • PIT is progressive from 5% to 30% (plus 1% national contribution on income above JOD 200,000/year)\n  • Personal exemption: JOD 9,000/year (individual) + JOD 9,000 for dependants\n  • JOD is pegged to USD: 1 JOD = USD 1.41 (fixed rate)\n\nGovernment / public sector reference:\n  • Jordanian civil servants receive per diem based on grade and destination\n  • General grades: JOD 25–50/day domestic (meals + incidentals)\n  • Senior officials: JOD 50–80/day domestic\n  • Private sector commonly references these government benchmarks',
  'te.jo.dom.source': 'ISTD (Income and Sales Tax Department) — Article 24 tax exemptions and business travel rules',
  'te.jo.dom.h.0': 'Category',
  'te.jo.dom.h.1': 'Rate / Amount',
  'te.jo.dom.h.2': 'Source Type',
  'te.jo.dom.r.0.0': 'Private sector',
