  'te.jo.dom.r.1.0': 'Tax treatment — genuine business travel with documentation',
  'te.jo.dom.r.1.1': 'Non-taxable for employee — deductible for employer',
  'te.jo.dom.r.1.2': 'Tax Authority Guideline',
  'te.jo.dom.r.2.0': 'Amounts deemed excessive or not for business travel',
  'te.jo.dom.r.2.1': 'Reclassified as salary — subject to PIT 5%–30%',
  'te.jo.dom.r.2.2': 'Statutory',
  'te.jo.dom.r.3.0': 'Public sector — standard grades',
  'te.jo.dom.r.3.1': 'JOD 25–50/day (meals + incidentals)',
  'te.jo.dom.r.3.2': 'Government Benchmark',
  'te.jo.dom.r.4.0': 'Public sector — senior officials',
  'te.jo.dom.r.4.1': 'JOD 50–80/day',
  'te.jo.dom.r.4.2': 'Government Benchmark',
  'te.jo.dom.r.5.0': 'Personal income tax exemption (individual)',
  'te.jo.dom.r.5.1': 'JOD 9,000/year personal + JOD 9,000 dependants',
  'te.jo.dom.r.5.2': 'Statutory',
  'te.jo.dom.r.6.0': 'National contribution tax',
  'te.jo.dom.r.6.1': '1% on annual taxable income exceeding JOD 200,000',
  'te.jo.dom.r.6.2': 'Statutory',
  'te.jo.intl.title': 'International Business Trips',
  'te.jo.intl.desc': 'For international travel from Jordan, same Income Tax Law framework applies — reasonable business travel reimbursements are non-taxable for the employee.\n\nU.S. State Department per diem rates are widely used as the benchmark for international business travel from Jordan (2025 rates):\n  • Amman (inbound): Lodging USD 207/night + M&IE USD 112/day\n\nJordanian public sector: civil servants traveling abroad receive per diem based on destination country and grade, aligned with regional Arab government practices.\n\nPrivate sector common international benchmarks (USD/day — meals + incidentals):\n  • United States / Western Europe: USD 250–350/day\n  • Gulf States (UAE, Saudi Arabia, Kuwait): USD 150–220/day\n  • Asian destinations: USD 150–250/day\n  • Regional (Arab countries): USD 100–180/day\n\nJoFotara (Jordan e-invoicing system): From 2023, Jordan has been rolling out electronic invoicing. Documentation of travel expenses is increasingly important.',
  'te.jo.intl.source': 'US State Dept 2025: Amman lodging $207 + M&IE $112/day (widely used as private sector benchmark)',
  'te.jo.intl.h.0': 'Destination',
  'te.jo.intl.h.1': 'Rate / Notes',
