  /* ── Kazakhstan (KZ) ── */
  'te.kz.dom.title': 'Domestic Business Trip — Commandirovka',
  'te.kz.dom.desc': 'Kazakhstan has statutory tax-free per diem (sutkovi / суточные) limits for employee business trips (commandirovka), set in multiples of the Monthly Calculation Index (MCI).\n\nTax Code framework (Article 319 of the 2017 Tax Code, continuing under the new Tax Code effective 1 January 2026):\n  • Domestic per diem (within Kazakhstan): up to 6 MCI per day tax-free\n  • MCI for 2025 = KZT 3,932\n  • Tax-free daily ceiling 2025: 6 × 3,932 = KZT 23,592/day\n  • Verify the 2026 MCI (typically set in the annual budget law)\n\nWhat this covers:\n  • The per diem covers meals and daily incidentals only\n  • Accommodation is reimbursed separately at actual receipted cost\n  • Transportation is reimbursed at actual cost with supporting documents\n\nTax treatment:\n  • Amounts within the 6 MCI ceiling: NOT taxable (not individual income)\n  • Amounts above 6 MCI/day: taxable employment income, subject to PIT (flat 10% under 2017 Code; progressive 10%/15% introduced under new 2026 Tax Code) and social contributions\n\nIMPORTANT — New Tax Code (July 18, 2025, effective January 1, 2026):\n  • New Tax Code signed by President; introduces progressive PIT (10% up to 8,500 MCI annual income, 15% above). Verify per diem MCI multipliers under new Code with a local tax advisor as implementation details may be updated in subsidiary regulations.',
  'te.kz.dom.source': 'MCI (Monthly Calculation Index) 2025 = KZT 3,932 | Tax-free domestic per diem: 6 MCI = KZT 23,592/day',
  'te.kz.dom.h.0': 'Category',
  'te.kz.dom.h.1': 'Rate / Amount',
  'te.kz.dom.h.2': 'Source Type',
  'te.kz.dom.r.0.0': 'Daily per diem — within Kazakhstan (sutkovi)',
  'te.kz.dom.r.0.1': 'Up to 6 MCI/day = KZT 23,592/day (2025)',
  'te.kz.dom.r.0.2': 'Statutory',
  'te.kz.dom.r.1.0': 'MCI value 2025',
  'te.kz.dom.r.1.1': 'KZT 3,932 per MCI (set annually in budget law)',
  'te.kz.dom.r.1.2': 'Statutory',
  'te.kz.dom.r.2.0': 'Amounts within 6 MCI ceiling',
  'te.kz.dom.r.2.1': 'NOT taxable — excluded from individual income',
  'te.kz.dom.r.2.2': 'Statutory',
  'te.kz.dom.r.3.0': 'Amounts above 6 MCI/day',
  'te.kz.dom.r.3.1': 'Taxable employment income — subject to PIT + social contributions',
  'te.kz.dom.r.3.2': 'Statutory',
  'te.kz.dom.r.4.0': 'Accommodation within Kazakhstan',
  'te.kz.dom.r.4.1': 'Actual receipted cost — fully deductible, non-taxable',
  'te.kz.dom.r.4.2': 'Statutory',
  'te.kz.dom.r.5.0': 'Transportation within Kazakhstan',
  'te.kz.dom.r.5.1': 'Actual receipted cost — fully deductible, non-taxable',
  'te.kz.dom.r.5.2': 'Statutory',
  'te.kz.dom.r.6.0': 'New Tax Code (eff. 1 Jan 2026) — PIT rates',
  'te.kz.dom.r.6.1': 'Progressive: 10% (up to 8,500 MCI/year); 15% above — verify per diem multipliers under new Code',
  'te.kz.dom.r.6.2': 'Statutory',
  'te.kz.intl.title': 'International Business Trips',
  'te.kz.intl.desc': 'For international business trips, the tax-free per diem ceiling is set at a higher MCI multiple to reflect higher international costs.\n\nInternational per diem — tax-free ceiling:\n  • Up to 8 MCI per day (for trips outside Kazakhstan)\n  • 2025: 8 × KZT 3,932 = KZT 31,456/day (approx. USD 62/day at KZT 500/USD)\n  • Accommodation: actual receipted costs — fully deductible for employer\n  • Transportation (flights, trains): actual costs — fully deductible\n\nTax treatment:\n  • Within 8 MCI: not individual income, not subject to PIT or social contributions\n  • Above 8 MCI/day: taxable employment income\n\nPrivate sector practice: Many multinational companies operating in Kazakhstan set international per diems aligned with US State Dept rates or UN ICSC rates for the destination, which are typically higher than the MCI-based floor. The excess above 8 MCI is taxable but is still paid and deducted as a business expense.\n\nCurrency note: KZT is the functional currency; USD widely used for international travel budgeting. USD 1 ≈ KZT 500–510 (2025 range — verify current rate).',
  'te.kz.intl.source': 'International per diem: 8 MCI per day tax-free = KZT 31,456/day (2025 MCI). Verify 2026 MCI once published.',
  'te.kz.intl.h.0': 'Category / Destination',
  'te.kz.intl.h.1': 'Rate / Amount',
