  /* ── Kyrgyzstan (KG) ── */
  'te.kg.dom.title': 'Domestic Business Trip',
  'te.kg.dom.desc': 'Kyrgyzstan has statutory tax-free per diem (sutkovi) limits based on multiples of the Monthly Reference Indicator (MRP / MRZ — Mesyachny Raschyotny Pokazatel).\n\nTax Code of the Kyrgyz Republic (Chapter on income from employment):\n  • Domestic per diem: up to 6 MRP per day — tax-free\n  • MRP for 2025 = KGS 100\n  • Tax-free daily ceiling 2025: 6 × KGS 100 = KGS 600/day\n\nNote: The MRP in Kyrgyzstan is set at KGS 100 and has historically been stable. Verify the current MRP value in the annual state budget law.\n\nWhat this covers:\n  • Meals and daily incidentals only\n  • Accommodation: reimbursed at actual cost with receipts\n  • Transportation: reimbursed at actual cost with supporting documents\n\nTax treatment:\n  • Within 6 MRP/day: not considered taxable income — exempt from PIT and social contributions\n  • Above 6 MRP/day: taxable employment income — subject to PIT at flat 10%\n\nBusiness trip documentation required:\n  • Commandirovka order (trip order from employer)\n  • Expense report submitted after return\n  • Receipts for accommodation and transport\n\nKGS exchange rate: USD 1 ≈ KGS 87–90 (2025 — verify with National Bank of Kyrgyzstan).',
  'te.kg.dom.source': 'MRP (Monthly Reference Indicator) 2025 = KGS 100 | Tax-free domestic per diem: 6 MRP = KGS 600/day',
  'te.kg.dom.h.0': 'Category',
  'te.kg.dom.h.1': 'Rate / Amount',
  'te.kg.dom.h.2': 'Source Type',
  'te.kg.dom.r.0.0': 'Daily per diem within Kyrgyzstan (sutkovi)',
  'te.kg.dom.r.0.1': 'Up to 6 MRP/day = KGS 600/day (2025)',
