  'te.kg.dom.r.4.0': 'Accommodation within Kyrgyzstan',
  'te.kg.dom.r.4.1': 'Actual receipted cost — deductible, non-taxable',
  'te.kg.dom.r.4.2': 'Statutory',
  'te.kg.dom.r.5.0': 'Transportation within Kyrgyzstan',
  'te.kg.dom.r.5.1': 'Actual receipted cost — deductible, non-taxable',
  'te.kg.dom.r.5.2': 'Statutory',
  'te.kg.dom.r.6.0': 'Documentation required',
  'te.kg.dom.r.6.1': 'Trip order + expense report + receipts for accommodation/transport',
  'te.kg.dom.r.6.2': 'Statutory',
  'te.kg.intl.title': 'International Business Trips',
  'te.kg.intl.desc': 'For international business trips, the Kyrgyz tax-free ceiling is higher to reflect the greater cost of international travel.\n\nInternational per diem — tax-free ceiling:\n  • Up to 8 MRP per day (for trips outside Kyrgyzstan)\n  • 2025: 8 × KGS 100 = KGS 800/day (approximately USD 9/day)\n\nImportant: The KGS-denominated ceiling is very low in USD terms. In practice, most employers with international operations pay significantly more than this — the excess above 8 MRP is treated as taxable employment income and subject to flat 10% PIT, but is still paid and deducted as a business expense.\n\nPrivate sector practice: Companies commonly reference U.S. State Dept or UN ICSC rates for the destination country and treat amounts above 8 MRP as taxable income.\n\nAdditional reimbursements (tax-free with receipts):\n  • International flights and transportation — actual cost\n  • Hotel accommodation abroad — actual receipted cost\n  • Visa fees, business registration costs — actual cost',
  'te.kg.intl.source': 'International: 8 MRP/day = KGS 800/day (2025 MRP). Verify current MRP in annual budget law.',
  'te.kg.intl.h.0': 'Category / Destination',
