  /* ── Laos (LA) ── */
  'te.la.dom.title': 'Domestic Business Trip',
  'te.la.dom.desc': 'Laos (Lao PDR) has NO government-mandated per diem rate specifically for private sector business travel. Companies set their own rates.\n\nTax treatment under the Lao Income Tax Law:\n  • Income from salaries and wages — including allowances and other benefits received in cash or in kind — is subject to Personal Income Tax (PIT) at progressive rates from 0% to 25%\n  • Business travel reimbursements for genuine, documented travel expenses are generally NOT included in taxable employment income\n  • Flat cash allowances paid without documentation may be treated as taxable income\n\nLabour law context:\n  • From 1 October 2023: minimum wage = LAK 1,600,000/month\n  • From 1 October 2024: subsistence allowance of up to LAK 900,000 required for non-professional workers earning less than LAK 2,500,000/month (combined)\n\nGovernment / public sector reference:\n  • Lao civil servants receive per diem based on grade and trip duration\n  • Domestic trip per diem: typically LAK 100,000–200,000/day (varies by grade)\n  • Private sector commonly references these government scales\n\nCurrency note: LAK is highly devalued. USD 1 ≈ LAK 21,000–22,000 (2025).',
  'te.la.dom.source': 'PWC Laos Tax Profile; Ministry of Labor and Social Welfare Notice No. 3534/MLSW (Oct 2024)',
  'te.la.dom.h.0': 'Category',
  'te.la.dom.h.1': 'Rate / Amount',
  'te.la.dom.h.2': 'Source Type',
  'te.la.dom.r.0.0': 'Private sector',
  'te.la.dom.r.0.1': 'Per company policy — no statutory per diem rate',
  'te.la.dom.r.0.2': 'Market Practice',
  'te.la.dom.r.1.0': 'Tax treatment — documented travel reimbursements',
  'te.la.dom.r.1.1': 'Generally non-taxable if genuine and documented',
