  'te.la.dom.r.2.0': 'Tax treatment — flat undocumented allowances',
  'te.la.dom.r.2.1': 'May be subject to PIT (progressive 0%–25%)',
  'te.la.dom.r.2.2': 'Statutory',
  'te.la.dom.r.3.0': 'Government reference — standard grades',
  'te.la.dom.r.3.1': 'LAK 100,000–150,000/day (approx. USD 5–7)',
  'te.la.dom.r.3.2': 'Government Benchmark',
  'te.la.dom.r.4.0': 'Government reference — senior officials',
  'te.la.dom.r.4.1': 'LAK 150,000–200,000/day',
  'te.la.dom.r.4.2': 'Government Benchmark',
  'te.la.dom.r.5.0': 'Minimum wage (from Oct 2023)',
  'te.la.dom.r.5.1': 'LAK 1,600,000/month — does not include travel allowances',
  'te.la.dom.r.5.2': 'Statutory',
  'te.la.dom.r.6.0': 'Subsistence allowance (from Oct 2024)',
  'te.la.dom.r.6.1': 'Up to LAK 900,000/month for low-income non-professional workers',
  'te.la.dom.r.6.2': 'Statutory',
  'te.la.intl.title': 'International Business Trips',
  'te.la.intl.desc': 'For international business travel from Laos, the same income tax framework applies. Reasonable, documented travel reimbursements are generally non-taxable.\n\nU.S. State Department per diem rates are the primary benchmark used by international organizations and private companies operating in Laos:\n  • Vientiane (inbound): Lodging USD 151/night + M&IE USD 83/day (2025)\n\nGovernment reference for Lao officials traveling abroad:\n  • Rates vary by destination country and grade\n  • Typically denominated in USD\n  • Range: USD 80–300/day depending on destination and grade\n\nSocial security: Both employer (6%) and employee (5.5%) contribute to NSSF. Contributions apply to base salary — not to legitimate travel reimbursements.\n\nPractical note: Laos uses USD widely in business transactions. Travel budgets are often set in USD or Thai Baht (THB) for regional travel.',
  'te.la.intl.source': 'US State Dept 2025: Vientiane lodging $151 + M&IE $83/day (widely used as private sector benchmark)',
  'te.la.intl.h.0': 'Destination',
  'te.la.intl.h.1': 'Rate / Notes',
