  /* ── Lithuania (LT) ── */
  'te.lt.dom.title': 'Domestic Business Trip — Dienpinigiai',
  'te.lt.dom.desc': 'Lithuania has statutory per diem (dienpinigiai) rates established under the Labour Code and Government Decree No. 98 (2017). These apply to ALL employers.\n\nDomestic per diem rate:\n  • EUR 28/day — maximum tax-free daily allowance for business trips within Lithuania\n  • No per diem is payable for one-day trips within Lithuania (Labour Code)\n\nTax treatment:\n  • Amounts within EUR 28/day: fully exempt from PIT and Sodra contributions\n  • Amounts above EUR 28/day: excess is subject to PIT (20%/25%/32% progressive from 2026) and Sodra social contributions\n\nAccommodation and transport:\n  • Reimbursed at actual cost with receipts\n  • No standard flat rate for accommodation — actual receipted costs\n\nKey PIT rates 2025 (employment income):\n  • 20% on income up to EUR 126,532/year\n  • 32% on income above EUR 126,532/year\n  • From 2026: three tiers — 20% / 25% / 32% (Parliament approved June 2025)\n\nMinimum wage 2025: EUR 1,038/month. Sodra minimum contribution base: EUR 1,038.\nAverage monthly salary (VDU) 2025: EUR 2,108.88.',
  'te.lt.dom.source': 'Darbo kodeksas (Labour Code of Lithuania) + Government Decree No. 98 (2017) — international trip rates',
  'te.lt.dom.h.0': 'Category / Duration',
  'te.lt.dom.h.1': 'Rate (EUR/day)',
