  'te.lt.dom.r.5.2': 'Statutory',
  'te.lt.intl.title': 'International Business Trips',
  'te.lt.intl.desc': 'For international trips, Lithuania publishes country-specific per diem rates under Government Resolution No. 98 (2017, as updated). These are the maximum tax-free daily allowances.\n\nSelected rates from Government Resolution — EUR/day:\n(Full table published on lrs.lt and summarized by VMI)\n\nRules:\n  • Rate applies per full day (or part day started) abroad\n  • Same tax treatment: within rate = tax-free; above rate = taxable income\n  • Accommodation reimbursed at actual receipted cost\n  • If no country-specific rate exists: a default rate applies\n\nNote: Lithuania made significant PIT changes effective 2026 (Parliament June 2025 — defence funding package). Per diem rules themselves remain unchanged; only the marginal rates on the taxable excess have been updated.',
  'te.lt.intl.source': 'Government Resolution No. 98, 2017 — country-specific per diem table for international business trips',
