  /* ── Luxembourg (LU) ── */
  'te.lu.dom.title': 'Domestic Business Trip',
  'te.lu.dom.desc': 'Luxembourg sets statutory per diem ceilings (frais de séjour) that apply to ALL employers. Flat-rate allowances are tax-free up to the civil servant scale; amounts above are subject to income tax and social contributions.\n\nTwo reimbursement methods are permitted:\n  1. Actual costs (frais réels) with receipts — no ceiling applies\n  2. Flat-rate allowances (forfaitaire) — capped at the civil servant scale\n\nDomestic rates (effective 1 January 2025 — Règlement du 13 décembre 2024):\n  • Indemnité de jour (daily meals allowance): €14/day\n  • Indemnité de nuit (overnight accommodation allowance): €56/night\n\nNote on indemnité de nuit:\n  • Receipt from hotel required for the full rate to be tax-free\n  • Without receipt: only 20% of the overnight rate (€11.20) is tax-exempt\n\nTrips within 25 km of the Luxembourg border:\n  • Treated as domestic (Luxembourg rate applies)\n\nFrais de déplacement (commuting deduction for employees):\n  • Separate from per diem — applies to regular commuting costs\n  • Capped at €214.50/month (annual cap: €2,574)\n  • Calculated using a distance-based formula (kilometric units) set by ACD',
  'te.lu.dom.source': 'Règlement du Gouvernement en Conseil du 13 décembre 2024 — rates effective 1 January 2025',
  'te.lu.dom.h.0': 'Category',
  'te.lu.dom.h.1': 'Day Rate (EUR)',
  'te.lu.dom.h.2': 'Night Rate (EUR)',
  'te.lu.dom.r.0.0': 'Within Luxembourg (indemnité de jour / indemnité de nuit)',
  'te.lu.dom.r.0.1': '€14/day',
