  'te.lu.intl.title': 'International Business Trips',
  'te.lu.intl.desc': 'For international trips, Luxembourg publishes country-specific rates updated annually by government decree (Règlement du Gouvernement en Conseil).\n\nEach country has two components:\n  1. Indemnité de jour (day allowance — meals): paid per full or started day\n  2. Indemnité de nuit (night allowance — accommodation + breakfast): requires receipt; without receipt only 20% is tax-exempt\n\nEU Presidency bonus: For countries holding the EU Council Presidency, the overnight rate is increased by 10% during the presidency period.\n\nInbound travel to Luxembourg (employees based abroad):\n  • Day rate: €60/day; Night rate: €200/night (Centre-ville)\n  • Night rate: €240/night (Kirchberg area)\n\nAll rates sourced from BDO Luxembourg Memento 2025 and confirmed against Règlement du Gouvernement en Conseil du 13 décembre 2024.',
  'te.lu.intl.source': 'BDO Luxembourg Memento Frais de Route et de Séjour 2025 — full country table (7 February 2025)',
