  /* ── Malaysia (MY) ── */
  'te.my.dom.title': 'Domestic Business Trip',
  'te.my.dom.desc': 'Malaysia has NO government-mandated per diem rate for private sector employers. Companies set their own travel allowance policies.\n\nTax treatment under Income Tax Act 1967 and LHDN Public Ruling 5/2019:\n\n1. Travelling Allowance (Elaun Perjalanan):\n   • Up to RM 6,000 per year is TAX-EXEMPT for business-related travel\n   • Applies to petrol allowance, toll reimbursement, and travel for work duties\n   • If employer cannot distinguish business vs. commuting travel: cap is RM 6,000\n   • Employee can claim further deduction if actual costs exceed RM 6,000\n\n2. Meal Allowance:\n   • Regular, uniform meal allowances are tax-exempt (not excessive)\n   • Overtime, outstation, or overseas meal allowances are tax-exempt if:\n     – Paid at a fixed rate per employer\'s internal circular\n     – Reasonable and based on actual business need\n\n3. Per Diem Allowances:\n   • Per diem for outstation travel is exempt if within LHDN guidelines\n   • Must be based on fixed rates in a written company policy/circular\n   • Amounts deemed excessive may be treated as taxable employment income\n\nGovernment / public sector reference (JPA — Public Service Dept):\n  • Grade TG48 and above: RM 260–350/night accommodation\n  • Standard staff: RM 150–250/night; meals RM 30–60/day\n\nMinimum wage: RM 1,700/month (2025)',
  'te.my.dom.source': 'Income Tax Act 1967 — perquisites and allowances; RM 6,000/year travelling allowance exemption',
  'te.my.dom.h.0': 'Category',
  'te.my.dom.h.1': 'Exemption / Rate',
  'te.my.dom.h.2': 'Source Type',
