  'te.my.dom.r.6.2': 'Market Practice',
  'te.my.dom.r.7.0': 'Minimum wage 2025',
  'te.my.dom.r.7.1': 'RM 1,700/month — does not affect travel allowance treatment',
  'te.my.dom.r.7.2': 'Statutory',
  'te.my.intl.title': 'International Business Trips',
  'te.my.intl.desc': 'For international business travel, the same LHDN framework applies. Reimbursements of actual travel costs are generally non-taxable.\n\nTax treatment (LHDN Public Ruling 5/2019):\n  • Meal and per diem allowances for outstation/overseas travel are exempt provided they are based on fixed rates specified in internal circulars\n  • The RM 6,000/year travelling allowance limit applies to domestic business travel; overseas allowances may qualify separately as they relate to actual costs\n\nGovernment (JPA) international reference rates:\n  • Group A (US, UK, Japan, Australia, Singapore, Germany, France, Switzerland): USD 200–350/day\n  • Group B (Middle East, South Korea, Canada, New Zealand): USD 150–250/day\n  • Group C (ASEAN, South Asia): USD 100–180/day\n  • Group D (Africa, Eastern Europe): USD 80–150/day\n\nIRAS Singapore 2025 acceptable rate for Malaysia: SGD 73/day (reference for Singapore-based employees traveling to Malaysia).',
  'te.my.intl.source': 'International travel: per diem covered under same framework; actual receipted costs non-taxable',
