  /* ── Mauritius (MU) ── */
  'te.mu.dom.title': 'Domestic Business Trip',
  'te.mu.dom.desc': 'Mauritius has NO government-mandated per diem rate for private sector employers. Companies set their own business travel policies.\n\nTax treatment under the Income Tax Act 1995 and MRA guidelines:\n\n1. Transport / Travelling Allowance (commuting-related):\n   • Tax-exempt up to the LESSER of:\n     – Actual petrol/travelling allowance paid, OR\n     – 25% of monthly basic salary, up to a maximum of MUR 20,000/month\n   • Applies when the employee uses a private car for work duties\n   • Commuting between home and workplace: return bus fare is fully exempt\n\n2. Business Trip Reimbursements (outstation/travel for work duties):\n   • Actual travel expense reimbursements (accommodation, meals, transport) for genuine business trips are generally NOT treated as taxable income if:\n     – Supported by valid receipts\n     – For genuine business purposes\n     – Not excessive in nature\n\nIncome tax rates 2025/2026:\n  • First MUR 500,000/year: 0%\n  • Next MUR 500,000: 10%\n  • Remainder: 20%\n  • Exempt person threshold: MUR 38,462/month\n  • Fair Share Contribution (FSC): 15% on chargeable income exceeding MUR 12M/year (effective 1 July 2025–30 June 2028)\n\nMUR exchange rate: USD 1 ≈ MUR 45–47 (2025 — verify with Bank of Mauritius).',
  'te.mu.dom.source': 'MRA (Mauritius Revenue Authority) — Exempt Income provisions under Income Tax Act 1995',
  'te.mu.dom.h.0': 'Category',
  'te.mu.dom.h.1': 'Exemption / Rate',
  'te.mu.dom.h.2': 'Source Type',
  'te.mu.dom.r.0.0': 'Travelling allowance — private car for work',
  'te.mu.dom.r.0.1': 'Lesser of actual paid OR 25% of basic salary, max MUR 20,000/month — tax-exempt',
