  'te.mu.dom.r.5.2': 'Statutory',
  'te.mu.dom.r.6.0': 'Private sector — no statutory per diem rate',
  'te.mu.dom.r.6.1': 'Per company policy — MRA assesses reasonableness',
  'te.mu.dom.r.6.2': 'Market Practice',
  'te.mu.intl.title': 'International Business Trips',
  'te.mu.intl.desc': 'For international business travel, same MRA framework applies — genuine, receipted travel reimbursements are generally non-taxable.\n\nNo government-published rate table exists for private sector international per diem.\n\nU.S. State Department per diem rates (2025 — for travel to Mauritius):\n  • Port Louis: Lodging USD 193/night + M&IE USD 98/day\n\nPrivate sector common benchmarks (Mauritius-based employees traveling abroad):\n  • Europe / North America / Australia: USD 200–350/day\n  • Middle East / Gulf States: USD 150–250/day\n  • Africa / Asia-Pacific: USD 100–200/day\n  • Regional Africa (Kenya, South Africa, etc.): USD 100–180/day\n\nIRAS Singapore 2025 acceptable rate for Mauritius: SGD 90/day (reference for Singapore-based employees travelling to Mauritius).',
  'te.mu.intl.source': 'US State Dept 2025: Mauritius (Port Louis) lodging $193 + M&IE $98/day — widely used as private sector benchmark',
  'te.mu.intl.h.0': 'Destination / Category',
