  /* ── Mexico (MX) ── */
  'te.mx.dom.title': 'Domestic Business Trip — Viaticos',
  'te.mx.dom.desc': 'Mexico has SAT-defined maximum tax-deductible limits for business travel expenses (viaticos). These are NOT statutory per diem rates — they are the limits that make the expenses deductible for the employer and non-taxable for the employee.\n\nSAT framework (ISR Law Art. 28, Frac. V + Art. 93 Frac. XVII):\n\nDomestic viaticos — tax-free treatment for the employee IF:\n  1. Travel is away from the employee\'s usual municipality of work/residence\n  2. Supported by CFDIs (digital tax receipts) from third parties covering lodging OR transport\n  3. If only meal expenses are documented without lodging/transport: payment must be made via corporate credit card\n\nSAT maximum deductible / tax-free ceilings (domestic):\n  • Meals: MXN 750/day (domestic)\n  • Car rental / leasing: MXN 850/day\n\n80% card payment rule:\n  • At least 80% of total viaticos must be paid via company credit card, debit card, or service card to be deductible for the EMPLOYER\n  • Up to 20% can be in cash (for small expenses such as MXN 15,000/year max)\n\nAmounts above SAT ceilings:\n  • Treated as taxable income for the employee and subject to ISR (1.92%–35%)\n\nUMA 2026: MXN 117.31/day | Minimum wage: MXN 278.80/day (general).',
  'te.mx.dom.source': 'SAT: Domestic meal limit MXN 750/day; car rental MXN 850/day; supported by third-party receipts (CFDIs)',
  'te.mx.dom.h.0': 'Category',
  'te.mx.dom.h.1': 'SAT Ceiling (MXN/day)',
  'te.mx.dom.h.2': 'Source Type',
  'te.mx.dom.r.0.0': 'Meals — domestic trips',
  'te.mx.dom.r.0.1': 'MXN 750/day (maximum deductible / tax-free for employee)',
  'te.mx.dom.r.0.2': 'Tax Authority Guideline',
  'te.mx.dom.r.1.0': 'Car rental or leasing — domestic',
  'te.mx.dom.r.1.1': 'MXN 850/day',
  'te.mx.dom.r.1.2': 'Tax Authority Guideline',
  'te.mx.dom.r.2.0': 'Lodging — domestic',
  'te.mx.dom.r.2.1': 'Actual cost with CFDI receipt (no flat ceiling for lodging)',
  'te.mx.dom.r.2.2': 'Tax Authority Guideline',
  'te.mx.dom.r.3.0': '80% corporate card rule',
  'te.mx.dom.r.3.1': 'At least 80% of total viaticos must be via company card to be employer-deductible',
  'te.mx.dom.r.3.2': 'Statutory',
  'te.mx.dom.r.4.0': 'Cash viaticos (up to 20%)',
  'te.mx.dom.r.4.1': 'Maximum MXN 15,000/year in cash (without card) — deductible for employer',
  'te.mx.dom.r.4.2': 'Statutory',
  'te.mx.dom.r.5.0': 'Amounts above SAT ceilings',
  'te.mx.dom.r.5.1': 'Taxable ISR income for employee (progressive 1.92%–35%)',
  'te.mx.dom.r.5.2': 'Statutory',
  'te.mx.dom.r.6.0': 'Documentation requirement',
  'te.mx.dom.r.6.1': 'CFDI from third parties covering lodging OR transport required for tax-free treatment',
  'te.mx.dom.r.6.2': 'Statutory',
  'te.mx.intl.title': 'International Business Trips',
  'te.mx.intl.desc': 'For international viaticos, the SAT framework is the same but the ceilings are higher.\n\nInternational viaticos — SAT ceilings:\n  • Meals: MXN 1,500/day (international)\n  • Lodging: MXN 3,850/day (international)\n  • Car rental / leasing: MXN 850/day (same as domestic)\n\nSame conditions apply:\n  • Must be supported by CFDIs or equivalent foreign receipts covering lodging OR transport\n  • 80% must be paid via company corporate card to be deductible for employer\n  • Travel must be away from usual municipality of work/residence\n\nTax treatment:\n  • Within SAT ceilings and properly documented: non-taxable for employee\n  • Excess above ceilings: taxable ISR income for the employee\n\nNote: The MXN 750 domestic meal limit and MXN 1,500 international meal limit have remained largely unchanged for several years. Verify current SAT Miscellaneous Tax Resolution (RMF) for any updates to these amounts annually.',
  'te.mx.intl.source': '80% of viaticos must be paid via corporate card to qualify as employer deductible expense (SAT rule)',
  'te.mx.intl.h.0': 'Category',
  'te.mx.intl.h.1': 'SAT Ceiling (MXN/day)',
  'te.mx.intl.h.2': 'Source Type',
  'te.mx.intl.r.0.0': 'Meals — international trips',
  'te.mx.intl.r.0.1': 'MXN 1,500/day (maximum deductible / tax-free for employee)',
  'te.mx.intl.r.0.2': 'Tax Authority Guideline',
  'te.mx.intl.r.1.0': 'Lodging — international',
