  /* ── Middle East (ME) ── */
  'te.me.dom.title': 'GCC & Middle East — Domestic Per Diem by Country',
  'te.me.dom.desc': 'This sheet provides a regional reference for the GCC (Gulf Cooperation Council) and broader Middle East countries. Separate detailed sheets exist for UAE, Saudi Arabia, Iraq, and Jordan. This sheet covers remaining key markets: Kuwait, Bahrain, Oman, Qatar, Lebanon, and Egypt (summary).\n\nKey regional principle: ALL GCC countries (UAE, Saudi Arabia, Kuwait, Bahrain, Oman, Qatar) have NO personal income tax on employment income. There is no mandatory per diem requirement for private sector employees in GCC countries. Employers set their own rates.\n\nTax treatment in GCC:\n  • No income tax on salaries/wages for individuals in UAE, Saudi Arabia, Kuwait, Bahrain, Oman, and Qatar\n  • Per diem, allowances, and benefits are generally non-taxable for employees\n  • Corporate tax rules vary: UAE introduced 9% CIT from June 2023; Saudi Arabia has 20% CIT; other GCC countries vary\n\nNon-GCC: Jordan and Lebanon have income tax — see Jordan sheet; Lebanon has significant economic context (currency crisis, USD/LBP dual rates).',
  'te.me.dom.source': 'Individual country sheets: UAE, Saudi Arabia, Iraq, Jordan also in this matrix (see separate tabs)',
