  /* ── Morocco (MA) ── */
  'te.ma.dom.title': 'Domestic Business Trip — Indemnités de Déplacement',
  'te.ma.dom.desc': 'Morocco has DGI (Direction Générale des Impôts) guidelines on tax-exempt allowances under the Code Général des Impôts (CGI) Art. 57. There is NO fixed government-mandated per diem rate for private sector employers — companies set their own rates.\n\nCategories of tax-exempt allowances under CGI:\n\n1. Indemnité de déplacement (business trip allowance):\n   • Covers accommodation and meal costs during professional missions\n   • Must be justified by valid invoices/receipts (pièces probantes) OR comply with the DGI published scales (barèmes)\n   • Without proper justification: treated as taxable employment income\n\n2. Indemnité de panier (meal allowance):\n   • Exempt up to MAD 30/day per working day\n   • Very common in Moroccan companies\n\n3. Indemnité de représentation:\n   • For senior staff/executives incurring representation expenses\n   • Exempt up to 10% of basic salary\n\n4. Indemnité de transport (commuting):\n   • Urban perimeter: exempt up to MAD 500/month\n   • Outside urban perimeter: exempt up to MAD 750/month\n\n5. Prime de tournée (travel premium for field staff):\n   • Exempt up to MAD 1,500/month for employees making multiple visits/day\n\nIncome tax (IR) rates 2025: Progressive 0%–37% annual\n  • Up to MAD 40,000/year: 0%\n  • MAD 40,001–60,000: 10%\n  • MAD 60,001–80,000: 20%\n  • MAD 80,001–100,000: 30%\n  • MAD 100,001–180,000: 34%\n  • Above MAD 180,000: 37%',
  'te.ma.dom.source': 'Code Général des Impôts (CGI) — indemnité de déplacement, indemnité de panier, conditions d\'exonération',
  'te.ma.dom.h.0': 'Allowance Category',
  'te.ma.dom.h.1': 'DGI Exemption Ceiling',
  'te.ma.dom.h.2': 'Source Type',
