  'te.ma.dom.r.6.2': 'Statutory',
  'te.ma.intl.title': 'International Business Trips',
  'te.ma.intl.desc': 'For international business travel, the same CGI framework applies. Documented reimbursements for genuine business travel are non-taxable.\n\nMorocco has no published per diem table for international private sector travel. Companies reference US State Dept or European government scales.\n\nU.S. State Department per diem rates for travel TO Morocco (2025):\n  • Casablanca: Lodging USD 199/night + M&IE USD 95/day\n  • Rabat: Lodging USD 185/night + M&IE USD 94/day\n  • Marrakesh: Lodging USD 190/night + M&IE USD 91/day\n\nPrivate sector benchmarks for Moroccan employees traveling abroad:\n  • Western Europe (France, Spain, Germany, UK): USD 180–280/day\n  • North America: USD 250–350/day\n  • Middle East / Gulf: USD 150–250/day\n  • Sub-Saharan Africa: USD 100–200/day\n\nNote: Morocco has the Moroccan Franc (MAD). Exchange rate: USD 1 ≈ MAD 10 (2025).',
  'te.ma.intl.source': 'International travel: documented reimbursements non-taxable under same DGI framework',
  'te.ma.intl.h.0': 'Destination',
  'te.ma.intl.h.1': 'Rate / Notes',
