  /* ── Netherlands (NL) ── */
  'te.nl.dom.title': 'Domestic Business Trip — Verblijfkostenvergoeding',
  'te.nl.dom.desc': 'The Netherlands has government-set maximum tax-free per diem (verblijfkostenvergoeding) rates published in the Handboek Loonheffingen (Payroll Tax Handbook) by the Belastingdienst. These apply to ALL employers as the ceiling for tax-free reimbursement.\n\nDomestic subsistence rates (2025 — CAO Rijk, effective 1 January 2025):\n\nDay allowances (during the trip):\n  • Breakfast: €4.56\n  • Lunch: €11.03\n  • Dinner: €20.40\n  • Small daytime expenses: €4.56\n  • Small evening expenses: €4.56\n\nOvernight allowance (per overnight absence):\n  • €150.30/night (first 8 nights — normal rate)\n  • Small evening expenses after night 8: €2.28 (halved)\n\nConditions:\n  • Destination must be in a different municipality OR ≥1 km from normal workplace\n  • Costs for breakfast, lunch, dinner must be incurred at a designated facility\n  • If employer provides free meals: deduct corresponding component\n  • After 8+ consecutive evenings abroad: small evening expenses halved\n\nKilometre allowance (€0.23/km): separate, fully tax-free for business journeys. Work from home allowance: max €2.40/day tax-free.',
  'te.nl.dom.source': 'CAO Rijk para 10.2/10.3 — domestic subsistence rates; updated annually 1 January',
  'te.nl.dom.h.0': 'Subsistence Component',
  'te.nl.dom.h.1': 'Rate (EUR — 2025)',
  'te.nl.dom.h.2': 'Source Type',
