  'te.nl.dom.r.8.1': 'Taxable salary — subject to payroll tax',
  'te.nl.dom.r.8.2': 'Statutory',
  'te.nl.intl.title': 'International Business Trips — Buitenlandse Dienstreis',
  'te.nl.intl.desc': 'For international business trips, the Belastingdienst publishes country-specific allowance rates annually. Two columns per destination:\n  1. Maximum accommodation costs (logieskosten)\n  2. Other costs / daily allowance (overige kosten)\n\nThe accommodation rate covers hotel and breakfast costs.\nThe \'other costs\' rate covers meals (lunch and dinner), small incidentals.\n\nSame deduction rules apply as domestic:\n  • Free meals provided: deduct the corresponding component\n  • After 8 consecutive evenings at same destination: small evening expenses halved\n\nSelected key rates (2025 — Belastingdienst official table):\nNote: All rates in EUR. Full table available on belastingdienst.nl',
  'te.nl.intl.source': 'International rates: Belastingdienst publishes country-specific allowance tables annually',
  'te.nl.intl.h.0': 'Country / City',
