  /* ── New Zealand (NZ) ── */
  'te.nz.dom.title': 'Domestic Business Trip',
  'te.nz.dom.desc': 'New Zealand has NO statutory per diem rate for private sector employers. IRD (Inland Revenue) applies a \'reasonable amount\' standard.\n\nTwo reimbursement methods under IRD guidance:\n\n1. Reimbursement of actual expenses:\n   • Employer reimburses actual receipted costs for accommodation, meals, transport\n   • These are NOT taxable income — not subject to PAYE\n   • If reimbursement exceeds actual cost, the excess IS taxable\n\n2. Cash allowances (not reimbursements):\n   • Fixed cash payments for meals, accommodation, clothing etc. are taxed as WAGES via PAYE\n   • Exceptions: meal allowances for employees working away from employer\'s premises, overtime meal allowances, and accommodation for employees who cannot travel home daily (e.g., secondments, conferences) — these are generally tax-free\n\nIRD \'reasonable estimate\' approach:\n   • If receipts are not available, employer may use a reasonable estimate\n   • The estimate must be genuinely reflective of actual costs\n   • No fixed NZD rate is published by IRD — reasonableness assessed case by case\n\nMileage allowance: IRD publishes a mileage rate for business use of personal vehicles (2025: NZD 1.04/km for petrol, diesel, or hybrid vehicles under 70km/day threshold; NZD 0.35/km for electric vehicles). Tax-free up to IRD rates.\n\nIncome tax rates 2025 (progressive): 10.5% / 17.5% / 30% / 33% / 39%',
  'te.nz.dom.source': 'IRD (Inland Revenue) — employee allowances guidance; reimbursements at actual cost are non-taxable; cash allowances taxed via PAYE',
  'te.nz.dom.h.0': 'Category',
  'te.nz.dom.h.1': 'Rate / Treatment',
  'te.nz.dom.h.2': 'Source Type',
  'te.nz.dom.r.0.0': 'Reimbursement of actual expenses — accommodation, meals, transport',
