  'te.nz.dom.r.5.0': 'Mileage — petrol/diesel/hybrid (up to 70km/day threshold) — 2025',
  'te.nz.dom.r.5.1': 'NZD 1.04/km (IRD published rate) — tax-free up to this rate',
  'te.nz.dom.r.5.2': 'Tax Authority Guideline',
  'te.nz.dom.r.6.0': 'Mileage — electric vehicle — 2025',
  'te.nz.dom.r.6.1': 'NZD 0.35/km (IRD published rate) — tax-free',
  'te.nz.dom.r.6.2': 'Tax Authority Guideline',
  'te.nz.dom.r.7.0': 'Private sector — no statutory rate',
  'te.nz.dom.r.7.1': 'Per company policy — IRD reasonableness standard applies',
  'te.nz.dom.r.7.2': 'Market Practice',
  'te.nz.intl.title': 'International Business Trips',
  'te.nz.intl.desc': 'For international business travel, same IRD framework applies: actual receipted costs are non-taxable; flat cash allowances are taxed as wages.\n\nMFAT (Ministry of Foreign Affairs and Trade) per diem schedule:\n   • Published quarterly; based on UNDP DSA (Daily Subsistence Allowance) rates\n   • Used for government officials and MFAT-contracted development cooperation workers\n   • Denominated in NZD; effective 1 January 2026 schedule published\n   • Covers meals, accommodation, and incidentals in one combined daily rate\n\nPrivate sector reference: Many NZ companies use MFAT or US State Dept per diem rates as a benchmark for international travel policies.\n\nSelected MFAT rates effective January 2026 (NZD/day — combined rate including accommodation, meals and incidentals):\n   • Australia (Sydney/Canberra/Melbourne): NZD 400–500/day\n   • United Kingdom: NZD 450–600/day\n   • United States: NZD 500–700/day\n   • Singapore: NZD 350–450/day\n   • Japan: NZD 350–500/day\n   • Pacific Islands: NZD 200–350/day\n\nVerify current rates at mfat.govt.nz (updated quarterly).',
  'te.nz.intl.source': 'MFAT (Ministry of Foreign Affairs and Trade) — per diem schedule updated quarterly; based on UNDP DSA rates',
  'te.nz.intl.h.0': 'Destination / Category',
  'te.nz.intl.h.1': 'Rate / Notes',
