  /* ── Nigeria (NG) ── */
  'te.ng.dom.title': 'Domestic Business Trip',
  'te.ng.dom.desc': 'Nigeria has NO government-mandated per diem rate for private sector employers. Companies set their own travel allowance policies.\n\nMAJOR TAX REFORM: Nigeria Tax Act 2025 (NTA)\n  • Signed by President Tinubu on 26 June 2025\n  • Effective from 1 January 2026\n  • Replaces and consolidates the Personal Income Tax Act (PITA) and other laws\n\nTax treatment of business travel under NTA 2025:\n  • Genuine, documented business travel reimbursements remain generally non-taxable\n  • The NTA broadens the taxable income base but retains non-taxability of actual business expense reimbursements where supported by documentation\n  • Undocumented flat cash allowances may be treated as taxable employment income\n\nNew PIT rate structure (effective 1 January 2026):\n  • Annual income up to NGN 800,000: 0% (full exemption — replaces old NGN 300,000 threshold)\n  • NGN 800,001–3,000,000: lower progressive rates\n  • Above NGN 50,000,000: 25% (top rate)\n  • CRA (Consolidated Relief Allowance) abolished; replaced by rent relief (20% of annual rent, max NGN 500,000)\n\nMinimum wage (from 1 May 2024): NGN 70,000/month\nNGN exchange rate: USD 1 ≈ NGN 1,550–1,600 (2025 — volatile; verify with CBN)',
  'te.ng.dom.source': 'NTA replaces PITA (Personal Income Tax Act); genuine business travel reimbursements are generally non-taxable',
  'te.ng.dom.h.0': 'Category',
  'te.ng.dom.h.1': 'Rate / Treatment',
  'te.ng.dom.h.2': 'Source Type',
  'te.ng.dom.r.0.0': 'Private sector — domestic per diem',
  'te.ng.dom.r.0.1': 'Per company policy — no statutory rate',
  'te.ng.dom.r.0.2': 'Market Practice',
  'te.ng.dom.r.1.0': 'Tax treatment — documented business travel reimbursements',
