  'te.ng.dom.r.2.1': 'May be treated as taxable employment income',
  'te.ng.dom.r.2.2': 'Statutory',
  'te.ng.dom.r.3.0': 'PIT annual exemption threshold (from 1 Jan 2026)',
  'te.ng.dom.r.3.1': 'NGN 800,000/year — full exemption (NTA 2025)',
  'te.ng.dom.r.3.2': 'Statutory',
  'te.ng.dom.r.4.0': 'PIT top rate (from 1 Jan 2026)',
  'te.ng.dom.r.4.1': '25% on income above NGN 50,000,000/year',
  'te.ng.dom.r.4.2': 'Statutory',
  'te.ng.dom.r.5.0': 'CRA abolished (from 1 Jan 2026)',
  'te.ng.dom.r.5.1': 'Replaced by rent relief: 20% of annual rent, max NGN 500,000',
  'te.ng.dom.r.5.2': 'Statutory',
  'te.ng.dom.r.6.0': 'Minimum wage (from 1 May 2024)',
  'te.ng.dom.r.6.1': 'NGN 70,000/month — does not affect travel allowance treatment',
  'te.ng.dom.r.6.2': 'Statutory',
  'te.ng.intl.title': 'International Business Trips',
  'te.ng.intl.desc': 'For international business travel, same NTA 2025 framework applies. Documented genuine travel reimbursements are non-taxable.\n\nU.S. State Department per diem rates for travel TO Nigeria (2025):\n  • Lagos: Lodging USD 261/night + M&IE USD 126/day\n  • Abuja: Lodging USD 168/night + M&IE USD 88/day\n\nPrivate sector benchmarks for Nigerian employees traveling abroad:\n  • United Kingdom / Western Europe: USD 250–380/day\n  • United States: USD 280–400/day\n  • Gulf States (UAE, Saudi Arabia): USD 180–280/day\n  • South Africa / regional Africa: USD 120–200/day\n\nNote: Nigeria\'s oil and gas sector typically applies elevated per diem rates reflecting the industry\'s international mobility. Rates for assignees from/to the Niger Delta or offshore platforms often include hardship allowances separately.',
  'te.ng.intl.source': 'International travel: same NTA framework — documented travel reimbursements non-taxable',
  'te.ng.intl.h.0': 'Destination / Category',
