  /* ── Norway (NO) ── */
  'te.no.dom.title': 'Domestic Business Trip — Kostgodtgjorelse',
  'te.no.dom.desc': 'Norway has government-published maximum tax-free per diem (kostgodtgjorelse) rates set by the Norwegian Tax Administration (Skatteetaten). Two sources apply:\n\n1. State rates (Statens reiseregulativ / SGS-1001): Mandatory for government employees; used as the reference benchmark.\n2. Skatteetaten advance rates: Maximum amounts that ANY private sector employer can pay tax-free without withholding tax.\n\n2025 domestic tax-free rates (Skatteetaten):\n  • Trip over 12 hours (no overnight): NOK 906/day\n  • Trip 6 to 12 hours: NOK 504/day\n  • Under 6 hours: no tax-free per diem\n\nOvernight stays — accommodation type determines the rate:\n  • Hotel with no meals included: full subsistence rate\n  • Hotel with breakfast included: breakfast deducted (approx. 20% reduction)\n  • Private accommodation (undocumented night supplement): NOK 435/night (paid in addition to any day rate — employee keeps without receipts)\n\nEligibility conditions:\n  • Destination must be more than 15 km from employee\'s home\n  • AND trip must last more than 6 hours\n  • Overnight stay: employee must spend at least 5 hours of the night (22:00–06:00) away\n\n24-month rule: Tax-free per diem is limited to 24 months at the same location. After 24 months, the deduction/tax-free treatment changes.\n\nKm allowance: NOK 3.50/km (tax-free for business travel in own car).',
  'te.no.dom.source': 'Skatteetaten (Norwegian Tax Administration) — 2025 tax-free per diem rates: >12h NOK 906/day; 6-12h NOK 504/day',
  'te.no.dom.h.0': 'Trip Duration / Accommodation Type',
  'te.no.dom.h.1': 'Tax-Free Rate (NOK — 2025)',
