  'te.no.dom.r.9.0': '24-month rule at same location',
  'te.no.dom.r.9.1': 'Tax-free per diem limited to 24 months; treatment changes after',
  'te.no.dom.r.9.2': 'Statutory',
  'te.no.dom.r.10.0': 'Excess above tax-free rates',
  'te.no.dom.r.10.1': 'Subject to payroll withholding tax (arbeidsgiveravgift)',
  'te.no.dom.r.10.2': 'Statutory',
  'te.no.intl.title': 'International Business Trips',
  'te.no.intl.desc': 'For international trips, Skatteetaten publishes country-specific per diem rates annually. These are the maximum tax-free amounts for ANY employer.\n\nKey rules for international trips:\n  • If the same destination is visited consecutively for more than 28 days: the per diem is reduced to 75% of the country rate from day 29 onwards\n  • If two consecutive stays at the same assignment exceed 28 days: the reduction also applies\n  • Undocumented night supplement (NOK 435) does NOT apply for private accommodation abroad\n\nSelected international rates (2025 — Skatteetaten / SGS-1001):\nNote: International rates are in the local currency of destination or EUR/USD. All rates below are in NOK/day as published by Skatteetaten unless stated.',
  'te.no.intl.source': 'International: country-specific rates; 25% reduction from day 29 at same location',
