  /* ── Pakistan (PK) ── */
  'te.pk.dom.title': 'Domestic Business Trip — T.A./D.A.',
  'te.pk.dom.desc': 'Pakistan has NO government-mandated per diem rate for private sector employers. Companies set their own T.A./D.A. (Travelling Allowance / Daily Allowance) policies.\n\nTax treatment under Income Tax Ordinance 2001 (Section 12):\n  • Any allowance or benefit (not being entertainment or conveyance allowance) granted to an employee to meet expenses WHOLLY AND NECESSARILY incurred in the performance of the duties of their employment is TAX-EXEMPT\n  • T.A./D.A. (Travelling Allowance and Daily Allowance) is explicitly cited as an example of such exempt allowances under the Ordinance\n  • The allowance must be for genuine, employment-related travel\n  • Amounts in excess of actual need or not for business purposes may be taxable\n\nOther exempt allowances (Section 12 and Second Schedule):\n  • Medical allowance: up to 10% of basic salary (or PKR 10,000/month, whichever is lower)\n  • Conveyance allowance: provided vehicle used for BUSINESS USE ONLY — no taxable benefit\n  • House rent allowance: 45% of basic salary (standard market practice, may differ)\n\nIncome tax (IT Ordinance 2001, Tax Year 2025-26 — July 2025 to June 2026):\n  • Up to PKR 600,000: 0%\n  • PKR 600,001–1,200,000: 1% on amount exceeding PKR 600,000\n  • PKR 1,200,001–2,200,000: PKR 6,000 + 11%\n  • PKR 2,200,001–3,200,000: PKR 116,000 + 23%\n  • PKR 3,200,001–4,100,000: PKR 346,000 + 30%\n  • Above PKR 4,100,000: PKR 616,000 + 35%\n\nTax year: 1 July to 30 June. PKR exchange rate: USD 1 ≈ PKR 278–285 (2025).',
  'te.pk.dom.source': 'Section 12 (Income from Salary) — T.A./D.A. (Travelling Allowance/Daily Allowance) for official duties is exempt from tax',
  'te.pk.dom.h.0': 'Category',
  'te.pk.dom.h.1': 'Rate / Treatment',
  'te.pk.dom.h.2': 'Source Type',
  'te.pk.dom.r.0.0': 'T.A./D.A. for official duties (private sector)',
  'te.pk.dom.r.0.1': 'Tax-exempt under ITO 2001 Section 12 — must be for genuine employment-related travel',
  'te.pk.dom.r.0.2': 'Statutory',
  'te.pk.dom.r.1.0': 'Medical allowance',
  'te.pk.dom.r.1.1': '10% of basic salary OR PKR 10,000/month (whichever is lower) — tax-exempt',
  'te.pk.dom.r.1.2': 'Statutory',
  'te.pk.dom.r.2.0': 'Conveyance allowance',
  'te.pk.dom.r.2.1': 'Tax-free if vehicle used for business use only; taxable if mixed personal use',
  'te.pk.dom.r.2.2': 'Statutory',
  'te.pk.dom.r.3.0': 'Amounts not for genuine business purposes',
  'te.pk.dom.r.3.1': 'Taxable employment income — subject to progressive PIT 1%–35%',
  'te.pk.dom.r.3.2': 'Statutory',
  'te.pk.dom.r.4.0': 'Govt reference — BPS 20-22 (senior officials)',
  'te.pk.dom.r.4.1': 'USD equivalent 220–350/day (Finance Division scale, PKR-denominated)',
  'te.pk.dom.r.4.2': 'Government Benchmark',
  'te.pk.dom.r.5.0': 'Govt reference — BPS 16-19 (mid-level)',
  'te.pk.dom.r.5.1': 'USD equivalent 170–270/day',
  'te.pk.dom.r.5.2': 'Government Benchmark',
  'te.pk.dom.r.6.0': 'Govt reference — BPS 1-15 (support staff)',
  'te.pk.dom.r.6.1': 'USD equivalent 120–180/day',
  'te.pk.dom.r.6.2': 'Government Benchmark',
  'te.pk.intl.title': 'International Business Trips',
  'te.pk.intl.desc': 'For international business travel from Pakistan, the same ITO 2001 framework applies. T.A./D.A. paid for official duties abroad is tax-exempt.\n\nGovernment reference: Pakistan\'s federal government sets travel entitlements for civil servants traveling abroad based on grade and destination country. These are published by the Finance Division and vary by Basic Pay Scale (BPS).\n  • Senior officials (BPS 20-22): USD 220–350/day\n  • Mid-level (BPS 16-19): USD 170–270/day\n  • Support staff (BPS 1-15): USD 120–180/day\n\nU.S. State Department per diem rates for travel TO Pakistan (2025):\n  • Islamabad: Lodging USD 159/night + M&IE USD 77/day\n  • Karachi: Lodging USD 155/night + M&IE USD 78/day\n  • Lahore: Lodging USD 120/night + M&IE USD 65/day\n\nNote: Pakistan is a high-security-risk environment; many multinationals apply elevated per diems and hardship allowances for Karachi, Lahore, and sensitive areas.',
  'te.pk.intl.source': 'International travel: same ITO 2001 framework — documented travel allowances for official duties are tax-exempt',
  'te.pk.intl.h.0': 'Destination / Category',
  'te.pk.intl.h.1': 'Rate / Notes',
  'te.pk.intl.h.2': 'Source Type',
  'te.pk.intl.r.0.0': 'Islamabad — inbound (US State Dept 2025)',
  'te.pk.intl.r.0.1': 'Lodging: USD 159/night + M&IE: USD 77/day',
  'te.pk.intl.r.0.2': 'Government Benchmark',
  'te.pk.intl.r.1.0': 'Karachi — inbound (US State Dept 2025)',
  'te.pk.intl.r.1.1': 'Lodging: USD 155/night + M&IE: USD 78/day',
