  /* ── Peru (PE) ── */
  'te.pe.dom.title': 'Domestic Business Trip — Viaticos',
  'te.pe.dom.desc': 'Peru regulates viaticos (business travel expenses) under tax law and a separate public sector decree. Private sector follows SUNAT income tax rules; there is NO fixed mandatory per diem rate for private employers.\n\nTax treatment under Ley del Impuesto a la Renta (Income Tax Law):\n  • Business travel expenses (viaticos — accommodation, meals, transport) are NOT considered taxable income for the employee IF:\n    1. Exclusively used to cover necessary expenses in the performance of duties\n    2. Properly documented with comprobantes de pago (tax receipts / e-invoices)\n    3. Amounts are reasonable and not designed to evade tax\n\nSUNAT documentation requirement:\n  • Private sector: viaticos for domestic travel must be supported by comprobantes de pago (SUNAT-authorized receipts). Without receipts, expenses cannot be deducted by the employer (corporate income tax) and may be treated as taxable for the employee\n  • Mobility (movilidad) expense without receipts: capped at 4% of the monthly Remuneracion Minima Vital (RMV) per worker per day (2025: 4% of PEN 1,130 = PEN 45.20/day)\n\nPublic sector reference (Decreto Supremo No. 007-2013-EF):\n  • PEN 320/day — maximum viatico for domestic government employee travel\n  • Applies to all public servants for comisiones de servicio within Peru\n\nUIT (Unidad Impositiva Tributaria) 2025: PEN 5,350\nIncome tax exemption (Fifth Category — Quinta Categoria):\n  • First 7 UIT of annual employment income exempt: 7 x PEN 5,350 = PEN 37,450/year\n  • PIT rates above: 8% / 14% / 17% / 20% / 30%\nMinimum wage (RMV) from 1 Jan 2025: PEN 1,130/month',
  'te.pe.dom.source': 'DS 007-2013-EF: public sector domestic viaticos ceiling PEN 320/day; private sector: actual receipted costs with comprobantes de pago',
  'te.pe.dom.h.0': 'Category',
  'te.pe.dom.h.1': 'Rate / Treatment',
  'te.pe.dom.h.2': 'Source Type',
  'te.pe.dom.r.0.0': 'Private sector — domestic viaticos',
  'te.pe.dom.r.0.1': 'Actual receipted costs — non-taxable with comprobantes de pago',
  'te.pe.dom.r.0.2': 'Tax Authority Guideline',
  'te.pe.dom.r.1.0': 'Mobility (movilidad) without receipt',
  'te.pe.dom.r.1.1': 'Max 4% of monthly RMV per worker per day = PEN 45.20/day (2025)',
  'te.pe.dom.r.1.2': 'Tax Authority Guideline',
  'te.pe.dom.r.2.0': 'Public sector — domestic viaticos ceiling (DS 007-2013-EF)',
  'te.pe.dom.r.2.1': 'PEN 320/day (comisiones de servicio within Peru)',
  'te.pe.dom.r.2.2': 'Government Benchmark',
  'te.pe.dom.r.3.0': 'Amounts without documentation',
  'te.pe.dom.r.3.1': 'Not deductible for employer; may be taxable for employee',
  'te.pe.dom.r.3.2': 'Statutory',
  'te.pe.dom.r.4.0': 'Tax exemption — Fifth Category (Quinta Categoria) 2025',
  'te.pe.dom.r.4.1': 'First 7 UIT = PEN 37,450/year exempt; above: PIT 8%–30% progressive',
  'te.pe.dom.r.4.2': 'Statutory',
  'te.pe.dom.r.5.0': 'UIT 2025',
  'te.pe.dom.r.5.1': 'PEN 5,350 (Unidad Impositiva Tributaria — set annually by Supreme Decree)',
