  'te.pe.dom.r.6.0': 'Minimum wage (RMV) from Jan 2025',
  'te.pe.dom.r.6.1': 'PEN 1,130/month',
  'te.pe.dom.r.6.2': 'Statutory',
  'te.pe.intl.title': 'International Business Trips',
  'te.pe.intl.desc': 'For international viaticos, Peru has a public sector rate table set by Decreto Supremo No. 056-2013-PCM, with limits by geographic zone per day.\n\nPublic sector international viaticos (DS 056-2013-PCM — zones in USD/day):\n  • Zone A (US, Canada, Japan, Western Europe, Australia): USD 440/day (senior officials)\n  • Zone A (standard staff): USD 200/day\n  • Zone B (Latin America, Eastern Europe, most of Asia): USD 160/day (standard)\n  • Zone C (Africa, Central Asia): USD 100/day\n\nPrivate sector: No mandatory rate. Actual receipted costs are non-taxable. Companies commonly reference public sector scales or US State Dept rates.\n\nU.S. State Department per diem for travel TO Peru (2025):\n  • Lima: Lodging USD 197/night + M&IE USD 95/day\n  • Other Peru: Lodging USD 130/night + M&IE USD 75/day\n\nNote: SUNAT enforces electronic invoicing (comprobantes electronicos) — ensure that international accommodation receipts are retained for corporate deductibility.',
  'te.pe.intl.source': 'US State Dept 2025: Lima lodging $197 + M&IE $95/day (widely used as private sector benchmark)',
  'te.pe.intl.h.0': 'Destination / Zone',
  'te.pe.intl.h.1': 'Rate / Notes',
  'te.pe.intl.h.2': 'Source Type',
  'te.pe.intl.r.0.0': 'Lima — inbound (US State Dept 2025)',
