  /* ── Philippines (PH) ── */
  'te.ph.dom.title': 'Domestic Business Trip',
  'te.ph.dom.desc': 'Philippines has NO government-mandated per diem rate for private sector employers. The private sector sets its own rates; the BIR governs tax treatment.\n\nTax treatment under BIR Revenue Regulations No. 2-98 (as amended) and BIR Ruling 008-2023:\n  • Per diems paid to employees as advances or reimbursements for BONA FIDE, ORDINARY and NECESSARY travel and representation expenses incurred in the performance of their duties are NOT subject to Withholding Tax on Compensation (WTC)\n  • This applies to BOTH rank-and-file AND managerial/supervisory employees\n  • Conditions for tax-free treatment:\n    1. The expense is ordinary and necessary for the trade or business\n    2. The employee is required to account/liquidate the advance\n    3. Excess advances are returned to the employer\n    4. The expense is duly supported by receipts/documents\n\nGovernment reference (Executive Order 77, 2019 — replacing EO 248/EO 298):\n  • Domestic per diem cluster rates for government employees:\n    - Cluster I (Metro Manila and high-cost areas): PHP 800/day\n    - Cluster II (medium-cost areas): PHP 600/day\n    - Cluster III (low-cost areas): PHP 400/day\n  • Breakdown: 50% lodging, 30% meals, 20% incidentals\n\nIncome tax (TRAIN Law, RA 10963):\n  • Progressive: 0% up to PHP 250,000 | 20% PHP 250K–400K | 25% PHP 400K–800K | 30% PHP 800K–2M | 32% PHP 2M–8M | 35% above PHP 8M\n  • 13th month pay and de minimis benefits exempt up to PHP 90,000/year total',
  'te.ph.dom.source': 'RR 2-98: per diems for bona fide business expenses in performance of duties are NOT subject to withholding tax on compensation',
  'te.ph.dom.h.0': 'Category',
  'te.ph.dom.h.1': 'Rate / Treatment',
  'te.ph.dom.h.2': 'Source Type',
  'te.ph.dom.r.0.0': 'Private sector per diem — bona fide business travel',
  'te.ph.dom.r.0.1': 'NOT subject to WTC if properly liquidated and documented (BIR RR 2-98)',
  'te.ph.dom.r.0.2': 'Tax Authority Guideline',
  'te.ph.dom.r.1.0': 'Excess advance not liquidated / non-business amounts',
  'te.ph.dom.r.1.1': 'Taxable compensation — subject to WTC and income tax',
  'te.ph.dom.r.1.2': 'Statutory',
  'te.ph.dom.r.2.0': 'Govt reference — Cluster I (Metro Manila / high-cost): EO 77',
  'te.ph.dom.r.2.1': 'PHP 800/day (50% lodging, 30% meals, 20% incidentals)',
  'te.ph.dom.r.2.2': 'Government Benchmark',
  'te.ph.dom.r.3.0': 'Govt reference — Cluster II (medium-cost areas): EO 77',
  'te.ph.dom.r.3.1': 'PHP 600/day',
  'te.ph.dom.r.3.2': 'Government Benchmark',
  'te.ph.dom.r.4.0': 'Govt reference — Cluster III (low-cost areas): EO 77',
  'te.ph.dom.r.4.1': 'PHP 400/day',
  'te.ph.dom.r.4.2': 'Government Benchmark',
  'te.ph.dom.r.5.0': '13th month pay + de minimis benefits combined',
  'te.ph.dom.r.5.1': 'Exempt from tax up to PHP 90,000/year (TRAIN Law)',
  'te.ph.dom.r.5.2': 'Statutory',
  'te.ph.dom.r.6.0': 'Income tax rates (TRAIN Law — RA 10963)',
  'te.ph.dom.r.6.1': '0% up to PHP 250K; 20%–35% progressive above',
  'te.ph.dom.r.6.2': 'Statutory',
  'te.ph.intl.title': 'International Business Trips',
  'te.ph.intl.desc': 'For international business travel, the same BIR RR 2-98 framework applies. Genuine, documented travel reimbursements for business duties are non-taxable.\n\nGovernment reference (EO 77, 2019 — international travel for government employees):\n  • Based on Executive Order 248 (as amended): Travel allowance USD 100/day + hotel room rate USD 200/night\n  • Based on UNDP DSA rates for development cooperation work\n\nU.S. State Department per diem for travel TO Philippines (2025):\n  • Manila: Lodging USD 208/night + M&IE USD 101/day\n  • Other Philippines: lower rates — check State Dept for specific locations\n\nPrivate sector benchmarks for Philippine-based employees traveling abroad:\n  • United States / Western Europe: USD 280–400/day\n  • Japan / Singapore / Australia: USD 250–350/day\n  • Middle East / Gulf: USD 180–280/day\n  • Regional Asia: USD 150–250/day\n\nNote: Fringe benefits (as defined by BIR) given to managerial/supervisory employees are subject to Fringe Benefits Tax (FBT) at 35% on the grossed-up monetary value, not to WTC. Genuine travel expense reimbursements are excluded from FBT.',
  'te.ph.intl.source': 'EO 77 (2019): consolidates government travel rules; private sector per diem set by company policy',
  'te.ph.intl.h.0': 'Destination / Category',
  'te.ph.intl.h.1': 'Rate / Notes',
  'te.ph.intl.h.2': 'Source Type',
  'te.ph.intl.r.0.0': 'Manila — inbound (US State Dept 2025)',
  'te.ph.intl.r.0.1': 'Lodging: USD 208/night + M&IE: USD 101/day',
