  /* ── Poland (PL) ── */
  'te.pl.dom.title': 'Domestic Business Trip — Dieta Krajowa',
  'te.pl.dom.desc': 'Poland has statutory minimum per diem (dieta) rates for employee business trips under the Labour Code (Art. 775) and the Ministerial Regulation of 29 January 2013 (Rozporzadzenie MPiPS, Dz.U. 2023, poz. 2190). The regulation is mandatory as a floor for public sector and serves as the tax-free reference for private sector.\n\nCurrent domestic dieta (from 1 January 2023):\n  • PLN 45/day — minimum mandatory rate; also the PIT and ZUS (social insurance) exempt ceiling for private sector employers\n  • PROPOSED INCREASE: Ministry of Labour draft regulation proposes raising the domestic dieta to PLN 60/day. As of mid-2026, this was in legislative process — verify current amount before applying\n\nTrip duration thresholds:\n  • Up to 8 hours: 50% of dieta = PLN 22.50 (proposed: PLN 30)\n  • 8 to 12 hours: full dieta = PLN 45 (proposed: PLN 60)\n  • Over 12 hours: full dieta = PLN 45 (proposed: PLN 60)\n\nIf employer provides free meals, dieta is reduced:\n  • Free breakfast: −25% reduction on full dieta\n  • Free lunch: −50% reduction\n  • Free dinner: −25% reduction\n\nAccommodation (nocleg):\n  • Reimbursed at actual receipted cost OR flat 150% of dieta per night if no receipt = PLN 67.50/night (proposed: PLN 90)\n\nTax/ZUS treatment:\n  • Within PLN 45/day ceiling: fully exempt from PIT and ZUS contributions\n  • Above PLN 45/day: excess is taxable income and subject to ZUS contributions\n  • Private sector may pay above — but only up to PLN 45 is tax/ZUS-free\n\nKm allowance: PLN 0.89/km for car (up to 900cc), PLN 1.15/km for car (over 900cc).',
  'te.pl.dom.source': 'Domestic dieta: PLN 45/day (from 1 Jan 2023). Proposed increase to PLN 60/day pending legislation as of mid-2026.',
  'te.pl.dom.h.0': 'Trip Category / Duration',
