  'te.pl.dom.r.9.2': 'Statutory',
  'te.pl.intl.title': 'International Business Trips — Dieta Zagraniczna',
  'te.pl.intl.desc': 'For international business trips, Poland uses country-specific rates set in the Annex to the Rozporządzenie MPiPS of 29 January 2013. Each country has:\n  1. Dieta (daily meal/incidentals allowance) — in EUR, USD, or local currency\n  2. Limit za nocleg (accommodation ceiling) — per night\n\nDuration thresholds (same logic as domestic):\n  • Less than 8 hours abroad: 1/3 of the country dieta\n  • 8 to 12 hours: 1/2 of the country dieta\n  • Over 12 hours: full dieta rate\n\nIf free meals are provided:\n  • Breakfast provided: −15% of full dieta\n  • Lunch provided: −30%\n  • Dinner provided: −30%\n\nTax/ZUS treatment: same rule — amounts within the published country rates are PIT-exempt and ZUS-free; amounts above are taxable and subject to contributions.\n\nSelected country rates (2025 — Rozporządzenie 29 Jan 2013 Annex):',
  'te.pl.intl.source': 'International: dieta rate per country (EUR, USD, or local currency) + nocleg (accommodation) limit per country',
