  /* ── Portugal (PT) ── */
  'te.pt.dom.title': 'Domestic Business Trip — Ajudas de Custo',
  'te.pt.dom.desc': 'Portugal sets ajudas de custo (subsistence allowances) under Decree-Law 106/98 (as amended). These apply directly to the public sector and serve as the IRS/TSU (income tax / social contributions) exempt ceiling for private employers.\n\nKey update: Decreto-Lei n.o 1/2025 (16 January 2025) updated domestic rates +5% effective 1 January 2025.\n\nDomestic rates 2025 (Continente — mainland Portugal and Autonomous Regions):\n  Full day rate (involving overnight stay OR full working day away):\n    • For general employees: EUR 50.20/day\n    • For members of government: EUR 65.89/day\n\n  Partial day (no overnight):\n    • Lunch (13:00–14:00): 25% of daily rate = EUR 12.55\n    • Dinner (20:00–21:00): 25% of daily rate = EUR 12.55\n    • If unable to return home by 22:00: 50% supplement\n\n  Meals only (no overnight): EUR 22.30/day\n  Accommodation only: EUR 27.70/day\n\nKm allowance: EUR 0.40/km (private vehicle for business — tax-free up to this rate)\n\nTax treatment:\n  • Amounts within the Decree-Law ceilings: exempt from IRS and TSU (social security contributions)\n  • Amounts above the ceiling: taxable employment income (IRS) and subject to social security\n  • Private sector is free to use government rates or different amounts, but only the statutory ceiling is IRS/TSU-free\n\nMinimum wage 2025 (SMN): EUR 870/month (mainland Portugal)',
  'te.pt.dom.source': 'Decreto-Lei 106/98 de 24 de abril (as amended by DL 1/2025): public sector reference rates also used as IRS/TSU ceiling for private sector',
  'te.pt.dom.h.0': 'Category',
  'te.pt.dom.h.1': 'Rate (EUR — 2025)',
  'te.pt.dom.h.2': 'Source Type',
  'te.pt.dom.r.0.0': 'Full daily rate — general employees (with overnight or full day)',
