  'te.pt.dom.r.7.2': 'Statutory',
  'te.pt.dom.r.8.0': 'Amounts above DL 106/98 ceilings',
  'te.pt.dom.r.8.1': 'Taxable IRS income + TSU social contributions',
  'te.pt.dom.r.8.2': 'Statutory',
  'te.pt.intl.title': 'International Business Trips',
  'te.pt.intl.desc': 'For international ajudas de custo, the rates are set by Portaria (ministerial order) that updates the country-specific amounts referenced in DL 106/98. The 2025 international rates were being updated under a separate Portaria following DL 1/2025 — verify at dre.pt for the latest published values.\n\n2024/2025 reference rates (from DL 106/98 and previous Portaria — pending 2025 update):\n  • Meals and accommodation combined: EUR 89.35/day\n  • Meals only (abroad): EUR 37.19/day\n  • Accommodation only (abroad): EUR 52.16/day\n\nThese are the maximum IRS/TSU-free ceilings for international travel.\n\nU.S. State Department per diem for travel TO Portugal (2025):\n  • Lisbon: Lodging USD 232/night + M&IE USD 100/day\n  • Porto / other: lower rates — check State Dept for details\n\nE-invoicing note: From January 2025, Portugal requires qualified electronic signatures on all PDF invoices — ensure receipts for international travel expenses comply with new e-invoicing rules (SAF-T compliance).',
  'te.pt.intl.source': 'International rates: DL 106/98 sets foreign ajudas de custo limits (updated by separate Portaria); private sector references these',
