  /* ── Romania (RO) ── */
  'te.ro.dom.title': 'Domestic Business Trip — Diurna',
  'te.ro.dom.desc': 'Romania has a statutory domestic per diem (diurna) framework. The public sector rate is set by Order, and private employers benefit from a multiplied ceiling.\n\nCurrent rates (Order 1235/2023 — in force):\n  • Public sector diurna: RON 23/day\n  • Private sector maximum tax-free ceiling: 2.5 x RON 23 = RON 57.50/day\n\nThis means private employers can pay up to RON 57.50/day without income tax (PIT) or social contribution (CAS/CASS) implications for the employee. Amounts above RON 57.50/day are treated as taxable employment income.\n\nEmployees do NOT need to provide supporting documents (receipts) for the per diem itself — the diurna is a flat daily rate, not a reimbursement.\n\nAdditional allowances (separate from diurna):\n  • Accommodation: if not provided by employer, a separate accommodation allowance of up to RON 265/day is tax-free (must be substantiated with receipts)\n  • If accommodation is covered: no accommodation allowance\n\nMeal deduction rule:\n  • If employer provides full meals during the trip: 50% reduction on the diurna\n\nMobility indemnity (alternative — for employees without fixed workplace):\n  • RON 1,000 net/month — non-taxable (e.g., for field sales staff)\n  • Cannot be combined with the diurna for the same period\n\nMinimum wage from 1 January 2025: RON 4,050/month\nIncome tax: flat 10% on employment income after deductions',
  'te.ro.dom.source': 'Private sector: up to 2.5x public rate = RON 57.50/day tax-free (PIT + social contributions exempt within this ceiling)',
  'te.ro.dom.h.0': 'Category',
  'te.ro.dom.h.1': 'Rate / Amount',
  'te.ro.dom.h.2': 'Source Type',
  'te.ro.dom.r.0.0': 'Public sector diurna (Order 1235/2023)',
