  'te.ro.dom.r.2.2': 'Statutory',
  'te.ro.dom.r.3.0': 'Accommodation supplement (if no accommodation provided)',
  'te.ro.dom.r.3.1': 'Up to RON 265/day — tax-free with receipts',
