  'te.ro.dom.r.5.2': 'Statutory',
  'te.ro.dom.r.6.0': 'Income tax (PIT)',
  'te.ro.dom.r.6.1': 'Flat 10% on employment income after social deductions',
  'te.ro.dom.r.6.2': 'Statutory',
  'te.ro.intl.title': 'International Business Trips',
  'te.ro.intl.desc': 'For international business trips, Romania uses destination-specific rates set by Government Decision (Hotarare de Guvern) No. 518/1995 (as amended).\n\nSame 2.5x multiplier rule:\n  • Private sector can pay up to 2.5 times the GD 518/1995 country rate tax-free\n  • Amounts above 2.5x are taxable employment income\n\nIf accommodation is not provided by the employer abroad:\n  • Additional accommodation allowance may be granted — actual receipted cost or up to the country\'s accommodation ceiling per GD 518/1995\n\nSelected international diurna rates (GD 518/1995 — public sector base rates, in EUR or USD per day — private sector ceiling = 2.5x these values):',
  'te.ro.intl.source': 'Private sector: up to 2.5x the GD 518/1995 country rate tax-free. Amounts above: taxable income.',
  'te.ro.intl.h.0': 'Country',
