  /* ── Saudi Arabia (SA) ── */
  'te.sa.dom.title': 'Domestic Business Trip',
  'te.sa.dom.desc': 'Saudi Arabia has NO personal income tax on employment income. All employee allowances — including per diem, housing, transport, and meals — are fully non-taxable for the employee. There is also NO mandatory per diem rate for private sector employers.\n\nLegal framework:\n  • Saudi Labor Law (Royal Decree M/51, 2005, as amended by Royal Decree M/24, 2022)\n  • Does not prescribe mandatory per diem amounts for private sector travel\n  • Employers are free to set their own per diem and travel allowance policies\n\nGOSI (social insurance) note:\n  • Social contributions (GOSI) apply on basic salary plus housing allowance\n  • Cap: SAR 45,000/month as the contribution base\n  • Saudi nationals: 21.5% total (9.75% employee + 11.75% employer)\n  • Expatriates: 2% occupational hazard (employer only)\n  • Per diem / travel allowances are generally EXCLUDED from the GOSI base\n\nTypical private sector per diem rates in Saudi Arabia:\n  • Senior executives: SAR 500–1,500/day domestic\n  • Mid-level managers: SAR 300–800/day\n  • Standard employees: SAR 150–400/day\n\nVAT: Saudi Arabia applies 15% VAT. Business travel receipts are VAT-inclusive. Employer may reclaim input VAT on legitimate business expenses with valid tax invoices.',
  'te.sa.dom.source': 'No personal income tax in Saudi Arabia — all employee allowances (including per diem) are fully non-taxable for individuals',
  'te.sa.dom.h.0': 'Category',
  'te.sa.dom.h.1': 'Rate / Amount',
  'te.sa.dom.h.2': 'Source Type',
