  'te.sa.dom.r.8.1': 'SAR 150–400/day',
  'te.sa.dom.r.8.2': 'Market Practice',
  'te.sa.intl.title': 'International Business Trips',
  'te.sa.intl.desc': 'For international business travel from Saudi Arabia, the same no-personal-income-tax framework applies. All per diem payments are non-taxable for employees.\n\nCompanies in Saudi Arabia commonly reference U.S. State Department per diem rates or UN ICSC rates as benchmarks for international travel policies.\n\nU.S. State Department per diem for travel TO Saudi Arabia (2025):\n  • Riyadh: Lodging USD 215/night + M&IE USD 98/day\n  • Jeddah: Lodging USD 195/night + M&IE USD 96/day\n  • Dammam / Eastern Province: Lodging USD 185/night + M&IE USD 92/day\n\nTypical international per diem for Saudi-based employees traveling abroad:\n  • United States / Western Europe: USD 280–400/day\n  • Japan / Singapore / Australia: USD 250–350/day\n  • Other Middle East / GCC: USD 180–300/day\n  • Asia-Pacific (excl. Japan/Sing/Aus): USD 150–250/day\n  • Africa / Latin America: USD 120–200/day\n\nEnd-of-service benefit note: Gratuity (End of Service Award) is calculated on basic salary only under Saudi Labor Law — per diem and allowances do NOT increase gratuity liability.',
  'te.sa.intl.source': 'Saudi Arabia has NO personal income tax — per diem is non-taxable. Companies set rates freely. GOSI contributions apply on basic salary + housing only.',
  'te.sa.intl.h.0': 'Destination / Category',
