  /* ── Serbia (RS) ── */
  'te.rs.dom.title': 'Domestic Business Trip — Dnevnica',
  'te.rs.dom.desc': 'Serbia has statutory per diem (dnevnica) rules under the Law on Personal Income Tax (Zakon o porezu na dohodak gradjana). The tax-free ceiling is adjusted annually based on the Consumer Price Index (CPI).\n\nDomestic per diem — non-taxable ceiling:\n  • RSD 3,380 per full dnevnica (effective 1 February 2025)\n  • Approximately EUR 28–30 at 2025 exchange rates\n  • Half per diem (for shorter trips): corresponding proportional amount\n  • Adjusted annually by the CPI published by the Statistical Office\n\nTax treatment:\n  • Within RSD 3,380/day: non-taxable (not included in salary for PIT or social contribution purposes)\n  • Above RSD 3,380/day: excess is taxable employment income — subject to flat 10% PIT and social contributions\n\nCar allowance for business use of private vehicle:\n  • Up to RSD 9,855/month (~EUR 84) non-taxable (eff. 1 Feb 2025)\n  • OR up to 30% of the price per unit of fuel x fuel consumed — whichever is lower\n\nPIT 2025: Flat 10% on employment income after non-taxable monthly allowance of RSD 28,423 (~EUR 240). Progressive additional annual income tax: 10% on annual income 3-6x average salary; 15% above 6x average salary.',
  'te.rs.dom.source': 'Domestic per diem tax-free ceiling: RSD 3,380/day (~EUR 29) from 1 Feb 2025 (indexed annually to CPI). KPMG Serbia GMS Flash Alert 2025.',
  'te.rs.dom.h.0': 'Category',
  'te.rs.dom.h.1': 'Rate / Amount',
  'te.rs.dom.h.2': 'Source Type',
  'te.rs.dom.r.0.0': 'Domestic per diem — non-taxable ceiling (from 1 Feb 2025)',
  'te.rs.dom.r.0.1': 'RSD 3,380 per full dnevnica (~EUR 29)',
  'te.rs.dom.r.0.2': 'Statutory',
  'te.rs.dom.r.1.0': 'Indexation',
  'te.rs.dom.r.1.1': 'Adjusted annually to CPI (Statistical Office of Serbia)',
  'te.rs.dom.r.1.2': 'Statutory',
  'te.rs.dom.r.2.0': 'Amounts above RSD 3,380/day',
  'te.rs.dom.r.2.1': 'Taxable employment income — 10% PIT + social contributions',
  'te.rs.dom.r.2.2': 'Statutory',
  'te.rs.dom.r.3.0': 'Car use for business — non-taxable ceiling',
  'te.rs.dom.r.3.1': 'Up to RSD 9,855/month (~EUR 84) OR 30% of fuel price x consumption',
  'te.rs.dom.r.3.2': 'Statutory',
  'te.rs.dom.r.4.0': 'PIT rate',
  'te.rs.dom.r.4.1': 'Flat 10% on employment income after RSD 28,423/month non-taxable amount',
  'te.rs.dom.r.4.2': 'Statutory',
  'te.rs.dom.r.5.0': 'Annual income tax (above 3x average salary)',
  'te.rs.dom.r.5.1': 'Progressive: 10% on 3-6x average; 15% above 6x average salary',
  'te.rs.dom.r.5.2': 'Statutory',
  'te.rs.intl.title': 'International Business Trips',
  'te.rs.intl.desc': 'SIGNIFICANT CHANGE: The non-taxable ceiling for international per diems was dramatically increased effective 1 January 2025.\n\nInternational per diem — non-taxable ceiling:\n  • EUR 90 per day (increased from EUR 50/day)\n  • This applies to the FULL daily allowance for business trips OUTSIDE Serbia\n  • Any amount above EUR 90/day is taxable employment income\n\nTax treatment:\n  • Within EUR 90/day: non-taxable — not included in salary or social contributions\n  • Above EUR 90/day: excess is subject to 10% PIT and social contributions\n\nThis change was introduced by the Law amending the Personal Income Tax Law, published in the Official Gazette of Serbia No. 94/2024 and effective 1 Jan 2025.\n\nPrivate sector practice: Many Serbian employers were already paying above the old EUR 50 ceiling and taxing the excess. The new EUR 90 ceiling brings the Serbian limit closer to European norms, reducing the tax burden on frequent international travelers.\n\nAccommodation and transport costs: Reimbursed separately at actual receipted costs; these are not part of the per diem ceiling.',
  'te.rs.intl.source': 'International: EUR 90/day non-taxable from 1 Jan 2025 (increased from EUR 50 by Law amendment). Source: KPMG Serbia, Zunic Law.',
  'te.rs.intl.h.0': 'Category',
  'te.rs.intl.h.1': 'Rate / Amount',
  'te.rs.intl.h.2': 'Source Type',
  'te.rs.intl.r.0.0': 'International per diem — non-taxable ceiling (from 1 Jan 2025)',
  'te.rs.intl.r.0.1': 'EUR 90/day (INCREASED from EUR 50 — Official Gazette No. 94/2024)',
  'te.rs.intl.r.0.2': 'Statutory',
  'te.rs.intl.r.1.0': 'Previous limit (pre-2025)',
  'te.rs.intl.r.1.1': 'EUR 50/day — now obsolete; replaced by EUR 90',
  'te.rs.intl.r.1.2': 'Statutory',
  'te.rs.intl.r.2.0': 'Amounts above EUR 90/day',
  'te.rs.intl.r.2.1': 'Taxable employment income — 10% PIT + social contributions',
  'te.rs.intl.r.2.2': 'Statutory',
  'te.rs.intl.r.3.0': 'Accommodation and transport costs (international)',
  'te.rs.intl.r.3.1': 'Reimbursed separately at actual receipted cost — not part of per diem ceiling',
  'te.rs.intl.r.3.2': 'Statutory',
  'te.rs.intl.r.4.0': 'Private sector practice',
  'te.rs.intl.r.4.1': 'Most employers now set EUR 90 as the benchmark; excess is taxable',
