  /* ── Singapore (SG) ── */
  'te.sg.dom.title': 'Domestic Business Trip — Singapore',
  'te.sg.dom.desc': 'Singapore has IRAS-published \'acceptable rates\' for per diem allowances. These are the maximum daily amounts that can be paid tax-free. Paying above these rates does NOT require the employee to produce receipts, but the excess becomes taxable income that must be reported in Form IR8A.\n\nDomestic Singapore rates (2025):\n  • Singapore-based employee traveling WITHIN Singapore for business: SGD 150/day tax-free\n  • Overseas-based employee traveling INTO Singapore for business: SGD 160/day tax-free\n\nKey rules:\n  • Rates apply to meals and incidental expenses only (not accommodation or flights)\n  • Accommodation paid directly or reimbursed by employer based on actual receipted costs is NOT classified as per diem and is non-taxable\n  • Airport transfers, inter-city business travel, business entertainment: NOT classified as per diem — non-taxable when reimbursed at actual cost\n  • If trip spans multiple countries in the same day: use the country where the employee spends most of that day\n\nIf employer pays LESS than the acceptable rate on a trip: the shortfall cannot be used to offset taxable excess from a different trip.\n\nEmployers can request IRAS to review rates by submitting cost-of-living data from a consulting firm (own experience not accepted).\n\nNo income tax on employment income in Singapore for first SGD 20,000. Progressive rates: 0%–24% (resident); non-residents: 15% or progressive, whichever higher.',
  'te.sg.dom.source': 'IRAS (Inland Revenue Authority of Singapore) — acceptable per diem rates; published annually in December; effective 1 January each year',
  'te.sg.dom.h.0': 'Category',
  'te.sg.dom.h.1': 'Rate (SGD/day — 2025)',
  'te.sg.dom.h.2': 'Source Type',
  'te.sg.dom.r.0.0': 'Singapore-based employee — travel within Singapore',
  'te.sg.dom.r.0.1': 'SGD 150/day',
  'te.sg.dom.r.0.2': 'Tax Authority Guideline',
  'te.sg.dom.r.1.0': 'Overseas-based employee — traveling INTO Singapore',
  'te.sg.dom.r.1.1': 'SGD 160/day',
  'te.sg.dom.r.1.2': 'Tax Authority Guideline',
  'te.sg.dom.r.2.0': 'Accommodation (direct payment or actual reimbursement)',
  'te.sg.dom.r.2.1': 'Non-taxable — NOT classified as per diem',
  'te.sg.dom.r.2.2': 'Tax Authority Guideline',
  'te.sg.dom.r.3.0': 'Excess above acceptable rate',
  'te.sg.dom.r.3.1': 'Taxable income — must be reported in Form IR8A',
  'te.sg.dom.r.3.2': 'Statutory',
  'te.sg.dom.r.4.0': 'No receipt needed up to acceptable rate',
  'te.sg.dom.r.4.1': 'Employee does not need receipts for amounts within acceptable rate',
  'te.sg.dom.r.4.2': 'Tax Authority Guideline',
  'te.sg.intl.title': 'International Per Diem — IRAS Acceptable Rates 2025 (SGD/day)',
  'te.sg.intl.desc': 'For international trips, IRAS publishes country-specific acceptable rates annually (published each December, effective 1 January). These are the maximum tax-free daily allowances for Singapore-based employees on overseas business trips.\n\nThe table shows 2025 IRAS acceptable rates (SGD/day) — source: IRAS official PDF (published December 2024, effective 1 January 2025).\n\nExcess above the acceptable rate = taxable income → report in Form IR8A.\nAmount at or below acceptable rate = non-taxable, no reporting needed.',
  'te.sg.intl.source': 'IRAS 2025 Acceptable Rates — full country table (SGD/day). Excess above acceptable rate: taxable income, reported in Form IR8A.',
  'te.sg.intl.h.0': 'Country / Region',
  'te.sg.intl.h.1': 'SGD/day (2025)',
