  /* ── Slovakia (SK) ── */
  'te.sk.dom.title': 'Domestic Business Trip — Dieta',
  'te.sk.dom.desc': 'Slovakia has statutory per diem (dieta) rates under the Act on Travel Allowances (Zakon c. 283/2002 Z.z. o cestovnych nahradach). Rates are updated periodically by ministerial order.\n\nCurrent domestic rates (effective 1 December 2025 — Slovak Ministry of Labour):\n  • Trip 5 to 12 hours: EUR 9.30\n  • Trip 12 to 18 hours: EUR 13.80\n  • Trip over 18 hours: EUR 20.60\n  • Trips under 5 hours: no per diem entitlement\n\nMeal deductions (if employer provides free meals):\n  • Free breakfast: −25% reduction on applicable dieta\n  • Free lunch: −40% reduction\n  • Free dinner: −40% reduction\n\nTax treatment:\n  • Amounts within the statutory dieta rates: exempt from income tax (PIT) and social/health insurance contributions\n  • Amounts above the statutory rates: taxable employment income\n\nAccommodation: reimbursed at actual receipted cost — separate from per diem.\n\nIncome tax (PIT) 2025: 19% on income up to EUR 47,537.98/year; 25% above.\nMinimum wage 2025: EUR 816/month.',
  'te.sk.dom.source': 'Domestic dieta from 1 Dec 2025: 5-12h = EUR 9.30; 12-18h = EUR 13.80; over 18h = EUR 20.60 (Slovak Ministry of Labour order)',
  'te.sk.dom.h.0': 'Trip Duration / Category',
  'te.sk.dom.h.1': 'Dieta (EUR — eff. 1 Dec 2025)',
  'te.sk.dom.h.2': 'Source Type',
  'te.sk.dom.r.0.0': 'Trip 5 to 12 hours',
  'te.sk.dom.r.0.1': 'EUR 9.30',
