  'te.sk.intl.title': 'International Business Trips — Dieta Zahranicna',
  'te.sk.intl.desc': 'For international business trips, Slovakia sets country-specific dieta rates under the Act on Travel Allowances. Rates are set by the Ministry of Labour and Social Affairs and are updated annually.\n\nDuration thresholds for international dieta:\n  • Over 12 to 24 hours: full dieta (100%)\n  • Over 6 to 12 hours: 1/2 dieta (50%)\n  • Up to 6 hours: 1/3 dieta if costs incurred, otherwise no dieta\n\nMeal deductions (if free meals provided abroad):\n  • Free breakfast: −25% of applicable dieta\n  • Free lunch: −40%\n  • Free dinner: −40%\n\nSelected international rates (from Slovak Ministry of Labour Opatrenie — full day rates, in currency per day):',
  'te.sk.intl.source': 'International dieta rates set annually by the Ministry of Labour and Social Affairs; per destination country (EUR, USD, GBP, CHF, etc.)',
