  /* ── Slovenia (SI) ── */
  'te.si.dom.title': 'Domestic Business Trip — Dnevnica',
  'te.si.dom.desc': 'Slovenia has statutory dnevnica (per diem) rates. The non-taxable limits for private sector employers are set by the Decree on Tax Treatment of Cost Reimbursements (Uredba o davchni obravnavi povracil stroshkov).\n\nDomestic dnevnica rates (2025 — non-taxable ceilings for private sector):\n  • Absence over 12 hours: EUR 27.81\n  • Absence 8 to 12 hours: EUR 13.88\n  • Absence 6 to 8 hours: EUR 9.69\n  • Absence under 6 hours: no dnevnica entitlement\n\nMeal deductions (if employer provides free meals):\n  • Free breakfast: −10% of full dnevnica (over 12h rate); −15% for 8-12h rate\n  • Free lunch: −35% (over 12h); −40% (8-12h)\n  • Free dinner: −35% (over 12h); −40% (8-12h)\n  • Total deductions capped: employee always retains at least 20% of dnevnica\n\nTax treatment:\n  • Within statutory limits: exempt from PIT and social contributions\n  • Above statutory limits: taxable employment income\n\nAccommodation: reimbursed at actual receipted cost.\nKm allowance: EUR 0.43/km for private vehicle use (from 2026).\n\nPIT rates 2025 (progressive): 16%–50%\n  • Up to EUR 9,566/year: 16%\n  • EUR 9,567–26,046/year: 26%\n  • EUR 26,047–51,886/year: 33%\n  • EUR 51,887–74,160/year: 39%\n  • Above EUR 74,160/year: 50%',
  'te.si.dom.source': 'Domestic dnevnica: over 12h = EUR 27.81; 8-12h = EUR 13.88; 6-8h = EUR 9.69 (2025 non-taxable limits)',
  'te.si.dom.h.0': 'Trip Duration / Category',
  'te.si.dom.h.1': 'Dnevnica (EUR — 2025)',
  'te.si.dom.h.2': 'Source Type',
