  'te.si.dom.r.8.2': 'Statutory',
  'te.si.intl.title': 'International Business Trips — Dnevnica v Tujini',
  'te.si.intl.desc': 'For international business trips, Slovenia uses country-specific dnevnica rates under the Decree on Travel Reimbursements Abroad.\n\nNEW REGULATION: Ur. l. RS 102/2025 (effective 1 January 2026) introduced updated time thresholds and a revised country rate table for international travel.\n\nInternational dnevnica thresholds (NEW — from 1 Jan 2026):\n  • Over 14 to 24 hours: 100% of country rate\n  • Over 8 to 14 hours: 75% of country rate\n  • Over 6 to 8 hours: 25% of country rate\n  • Under 6 hours: no dnevnica\n\nPrevious thresholds (pre-2026): over 14h/8-14h/under 8h\n\nMeal deductions abroad (from new regulation):\n  • Over 14h trips: breakfast −10%, lunch −35%, dinner −35%\n  • 8-14h trips: breakfast −15%, lunch −40%, dinner −40%\n  • Maximum deduction: 80% (employee retains at least 20%)\n\nSelected key country rates (in EUR or USD/day — from Ur. l. RS 102/2025):\nPrivate sector uses these rates as the non-taxable ceiling.',
  'te.si.intl.source': 'New foreign travel regulation effective 1 January 2026 — updated thresholds and per-country dnevnica table; replaces 2019 regulation',
