  /* ── South Africa (ZA) ── */
  'te.za.dom.title': 'Domestic Business Trip — Subsistence Allowance',
  'te.za.dom.desc': 'South Africa has SARS-published \'deemed amount\' subsistence allowances under Section 8(1) of the Income Tax Act No. 58 of 1962. These are updated annually by the Finance Minister around the time of the Budget Speech, effective 1 March (start of the South African tax year).\n\nDomestic rates (2026 tax year — effective 1 March 2025):\n  • Incidental costs only: ZAR 176/day (increased from ZAR 169)\n  • Meals and incidental costs combined: ZAR 570/day (increased from ZAR 548)\n\nHow deemed amounts work:\n  • Employee must be OBLIGED to spend at least ONE NIGHT away from usual residence\n  • Within the deemed amount: tax-free — NO receipt required\n  • Above the deemed amount: the excess is taxable (included in annual tax return, NOT deducted via PAYE monthly)\n  • Employee may alternatively claim actual expenses (receipts required) to reduce tax\n\nAccommodation note:\n  • SARS does NOT publish a deemed rate for accommodation costs\n  • Accommodation reimbursements must be supported by receipts to be tax-free\n  • Any unsubstantiated accommodation allowance is taxable\n\nIRP5 codes:\n  • Code 3705: local travel subsistence (non-taxable)\n  • Code 3704: local travel subsistence (taxable — above deemed rate)\n\nPersonal income tax (PIT) 2025: progressive 18%–45%.\nTax year: 1 March to end of February.\nMinimum wage 2025: ZAR 28.79/hour (approx. ZAR 4,969/month for 40h/week).',
  'te.za.dom.source': 'SARS (South African Revenue Service) — Section 8(1) Income Tax Act No. 58/1962; 2026 tax year rates (eff. 1 March 2025)',
