  'te.za.dom.r.6.2': 'Statutory',
  'te.za.intl.title': 'International Business Trips — Foreign Subsistence Allowance',
  'te.za.intl.desc': 'For international business travel, SARS publishes country-specific deemed daily amounts in foreign currency (PAYE-GEN-01-G03-A02). These are the tax-free maximums for meals and incidental costs when traveling outside South Africa.\n\n2026 tax year rates (effective 1 March 2025):\n  • No changes were made to the 2025 foreign rates for the 2026 tax year\n  • Verify the 2027 rates at sars.gov.za after the February 2026 Budget Speech\n\nKey rules:\n  • Rate applies per full day (or part day) outside South Africa\n  • Convert foreign currency deemed amount to ZAR at the exchange rate on the day the allowance is paid\n  • No receipt required for amounts within the deemed rate\n  • Amounts above: taxable via annual assessment (not PAYE monthly)\n\nIRP5 codes for international:\n  • Code 3716: foreign subsistence (non-taxable)\n  • Code 3715: foreign subsistence (taxable excess)\n\nSelected SARS 2026 foreign subsistence allowance rates by country:',
  'te.za.intl.source': 'SARS 2026 tax year foreign subsistence allowance table — country-specific deemed daily amounts in foreign currency (eff. 1 March 2025)',
