  /* ── South Korea (KR) ── */
  'te.kr.dom.title': 'Domestic Business Trip',
  'te.kr.dom.desc': 'South Korea has NO government-mandated per diem rate for private sector employers. Companies set their own business travel expense policies.\n\nKey NTS (National Tax Service) exemptions relevant to business travel:\n\n1. Meal Allowance (sik-dae, sik-dae):\n   • Up to KRW 200,000/month is tax-exempt (Income Tax Act Article 12)\n   • This applies when meals are NOT provided by the employer\n   • Changed from KRW 100,000/month to KRW 200,000/month effective January 2023\n\n2. Business Travel Expense Regulations (chul-jang-bi ):\n   • Companies formally adopt internal travel expense regulations\n   • Per diem paid within these regulations is treated as non-taxable expense reimbursement\n   • Amounts must be reasonable and not inflated for tax avoidance\n   • NTS may challenge excessive amounts as taxable income\n\nGovernment reference (Ministry of Personnel Management):\n   • Grade-based domestic per diem for civil servants (Appendix 1)\n   • Senior officials (Grade 1-3): KRW 50,000–70,000/day incidentals\n   • Standard officers (Grade 4-9): KRW 30,000–50,000/day\n\nTypical private sector benchmarks (daily incidentals — varies by company/grade):\n   • Executive level: KRW 50,000–100,000/day\n   • Manager level: KRW 30,000–70,000/day\n   • Staff level: KRW 20,000–50,000/day\n\nPIT 2025: Progressive 6%–45% (+ 10% local income tax surtax on PIT amount).\nForeign workers may elect a flat 19% rate for up to 5 years.\nMinimum wage 2025: KRW 10,030/hour (approx. KRW 2,096,270/month at 209h).',
  'te.kr.dom.source': 'No statutory per diem rate for private sector. Government employees follow Ministry of Personnel Management Regulations (grade-based, Appendix 1).',
