  'te.kr.intl.title': 'International Business Trips',
  'te.kr.intl.desc': 'For international business trips, the same NTS framework applies. Per diem paid under a formally adopted company travel regulation is treated as non-taxable expense reimbursement.\n\nGovernment reference (Ministry of Personnel Management — international):\n   • Civil servant international per diem rates are set per destination country\n   • Published in the Regulations on Official Travel Expenses (Appendix 4)\n   • Rate levels vary by grade and destination\n\nTypical private sector international benchmarks (KRW/day incidentals — accommodation and transport separate):\n   • North America / Western Europe: KRW 80,000–200,000/day\n   • Japan / China / Southeast Asia: KRW 60,000–150,000/day\n   • Emerging markets / other regions: KRW 40,000–100,000/day\n\nU.S. State Department per diem for travel TO South Korea (2025):\n   • Seoul: Lodging USD 213/night + M&IE USD 100/day\n   • Other Korea: Lodging USD 130/night + M&IE USD 71/day\n\nIRAS Singapore 2025 acceptable rate for South Korea: SGD 155/day',
  'te.kr.intl.source': 'International per diem: same framework — Ryohi Kisoku-style company travel regulations govern private sector rates.',
  'te.kr.intl.h.0': 'Destination / Category',
  'te.kr.intl.h.1': 'Rate / Notes',
  'te.kr.intl.h.2': 'Source Type',
  'te.kr.intl.r.0.0': 'Seoul — inbound (US State Dept 2025)',
