  /* ── Spain (ES) ── */
  'te.es.dom.title': 'Domestic Business Trip — Dietas',
  'te.es.dom.desc': 'Spain has AEAT (Agencia Tributaria) statutory limits for dietas (travel allowances) under the IRPF (Income Tax) regulations. These apply to ALL private sector employers and have remained unchanged for many years.\n\nKey principle: TRAVEL OUTSIDE THE MUNICIPALITY of the usual workplace is required. Travel within the same municipality does NOT qualify for tax-free dieta.\n\nDomestic dieta ceilings (within Spain):\n  • Meals (manutención): EUR 26.67/day tax-free\n  • Accommodation WITHOUT hotel receipt: EUR 53.34/night tax-free\n  • Accommodation WITH hotel receipt: actual cost is tax-free (no ceiling)\n\nImportant rule — meal ticket vs. dieta:\n  • An employee CANNOT claim both a meal ticket (vale comida / ticket restaurante) AND a dieta for the same day — only one applies\n\nKm allowance: EUR 0.26/km for use of private vehicle for business (tax-free).\n\nTax treatment:\n  • Within AEAT ceilings: fully exempt from IRPF (income tax) and Social Security contributions\n  • Above ceilings: excess is taxable employment income — subject to IRPF (progressive 19%–47%) and Social Security contributions\n\nDocumentation required:\n  • Date and destination of trip\n  • Business purpose\n  • Transport receipts (flights, trains, etc.)\n  • Hotel invoice if claiming actual accommodation above the flat rate\n\nIRPF progressive rates 2025 (state + regional):\n  • Up to EUR 12,450: 19% | EUR 12,451–20,200: 24% | EUR 20,201–35,200: 30%\n  • EUR 35,201–60,000: 37% | EUR 60,001–300,000: 45% | Above EUR 300,000: 47%',
  'te.es.dom.source': 'AEAT IRPF Manual Sec 7.1.1.2 — dietas gastos de manutencion y estancia; rates unchanged for many years',
  'te.es.dom.h.0': 'Category',
  'te.es.dom.h.1': 'AEAT Tax-Free Ceiling',
  'te.es.dom.h.2': 'Source Type',
  'te.es.dom.r.0.0': 'Meals (manutención) — within Spain',
  'te.es.dom.r.0.1': 'EUR 26.67/day',
  'te.es.dom.r.0.2': 'Statutory',
  'te.es.dom.r.1.0': 'Accommodation WITHOUT hotel receipt — within Spain',
  'te.es.dom.r.1.1': 'EUR 53.34/night',
