  'te.es.dom.r.4.0': 'Condition — municipality requirement',
  'te.es.dom.r.4.1': 'Must travel OUTSIDE the municipality of usual workplace — same-city travel does NOT qualify',
  'te.es.dom.r.4.2': 'Statutory',
  'te.es.dom.r.5.0': 'Meal ticket vs. dieta',
  'te.es.dom.r.5.1': 'Cannot combine meal ticket (vale comida) and dieta for the same day',
  'te.es.dom.r.5.2': 'Statutory',
  'te.es.dom.r.6.0': 'Amounts above AEAT ceilings',
  'te.es.dom.r.6.1': 'Taxable IRPF income + Social Security contributions',
  'te.es.dom.r.6.2': 'Statutory',
  'te.es.dom.r.7.0': 'IRPF progressive rates 2025',
  'te.es.dom.r.7.1': '19%–47% (state + regional combined); 47% applies above EUR 300,000',
  'te.es.dom.r.7.2': 'Statutory',
  'te.es.intl.title': 'International Business Trips',
  'te.es.intl.desc': 'For international business trips, the same AEAT framework applies but with higher tax-free ceilings to reflect higher international living costs.\n\nInternational dieta ceilings (outside Spain):\n  • Meals (manutención): EUR 48.08/day tax-free\n  • Accommodation WITHOUT hotel receipt: EUR 91.35/night tax-free\n  • Accommodation WITH hotel receipt: actual cost is tax-free (no ceiling)\n\nSame conditions apply:\n  • Travel must be outside the municipality of usual workplace\n  • Employee cannot combine meal ticket and dieta for the same day\n  • Proper documentation required\n\nNote: These international AEAT rates have remained unchanged for many years. No announcement of imminent revision as of mid-2026. Always verify at sede.agenciatributaria.gob.es before applying.\n\nUS State Dept per diem for travel TO Spain (2025):\n  • Madrid: Lodging USD 237/night + M&IE USD 107/day\n  • Barcelona: Lodging USD 233/night + M&IE USD 105/day',
  'te.es.intl.source': 'Same IRPF framework for international travel; no receipts needed for accommodation up to EUR 91.35/night without hotel bill',
