  /* ── Sweden (SE) ── */
  'te.se.dom.title': 'Domestic Business Trip — Traktamente',
  'te.se.dom.desc': 'Sweden has statutory traktamente (per diem) rates published by Skatteverket (Swedish Tax Agency). These are the maximum tax-free amounts for employer reimbursements during business travel requiring at least one overnight stay.\n\n2025 domestic traktamente rates (Skatteverket):\n  • Full day: SEK 290/day (for income year 2025)\n  • Half day (departure from 12:00 OR return by 19:00): SEK 145\n  • Private accommodation overnight supplement: SEK 145/night (no receipt — only if trip occurred between midnight and 06:00)\n\n2026 rates (for reference — applicable from 1 January 2026):\n  • Full day: SEK 300/day\n  • Half day: SEK 150\n  • Private accommodation supplement: SEK 150/night\n\nLong-stay reductions:\n  • After 3 months at same location: 70% of full rate (SEK 203 in 2025)\n  • After 2 years at same location: 50% of full rate (SEK 145 in 2025)\n\nEligibility conditions:\n  • Destination must be more than 50 km from BOTH home AND usual workplace\n  • At least one overnight stay required\n\nMeal deductions (2025) — if employer provides free meals:\n  • Breakfast: SEK 58 deducted from daily rate\n  • Lunch: SEK 102 deducted\n  • Dinner: SEK 102 deducted\n\nKm allowance: SEK 2.50/km (tax-free for private vehicle in business use).\nNote: Accommodation is reimbursed separately at actual receipted cost.',
  'te.se.dom.source': 'Skatteverket — traktamente 2025: full day SEK 290 (SEK 300 from 2026); half day SEK 145 (SEK 150 from 2026)',
  'te.se.dom.h.0': 'Category / Duration',
  'te.se.dom.h.1': '2025 Rate (SEK)',
