  'te.se.dom.r.10.2': 'Statutory',
  'te.se.intl.title': 'International Business Trips — Utlandstraktamente 2025',
  'te.se.intl.desc': 'For international trips, Skatteverket publishes country-specific utlandstraktamente rates annually, based on cost-of-living surveys for standard restaurant meals in each country.\n\nRules:\n  • If employer provides free meals: deduct 15% per meal (breakfast/lunch/dinner)\n  • If 2+ free meals on same day: deduct 35% total\n  • Country with the most time spent during 06:00–24:00 determines the rate\n  • Travel time by plane or boat between countries is excluded when determining\n\nLong-stay reduction for international (after 28 days at same location):\n  • From day 29: 75% of the country\'s utlandstraktamente rate\n\nSelected utlandstraktamente 2025 rates (SEK/day — Skatteverket official table):',
  'te.se.intl.source': 'Skatteverket — utlandstraktamente 2025: country-specific rates published annually; reviewed based on restaurant cost surveys',
