  /* ── Switzerland (CH) ── */
  'te.ch.dom.title': 'Domestic Business Trip',
  'te.ch.dom.desc': 'Switzerland has NO government-mandated per diem rate. Under Article 327a of the Code of Obligations (Obligationenrecht / Code des obligations), employers MUST reimburse employees for all expenses necessarily incurred in performance of work, including necessary living expenses when working away from the employer\'s premises.\n\nTwo reimbursement methods:\n  1. Effective reimbursement (Effektive Spesenverguetung): actual documented costs with receipts\n  2. Flat-rate allowances (Pauschalspesen): fixed amounts per the company\'s approved expense regulations (Spesenreglement)\n\nESTV (Federal Tax Administration) reference limits for flat-rate expenses (not statutory but widely used as the tax-safe benchmark):\n  • Lunch/dinner (no receipt): CHF 30/meal\n  • Lunch/dinner (with receipt): up to CHF 35/meal (effective reimbursement)\n  • Small daily expenses (incidentals): CHF 20/day\n  • Private vehicle: CHF 0.70/km (tax-free)\n\nApproved Spesenreglement (expense regulations):\n  • Companies can apply to the relevant cantonal tax authority for an approved Spesenreglement with higher flat-rate amounts\n  • Typical approved lump-sum: 3–5% of employee\'s net salary, max CHF 24,000/year\n  • Without approved regulations, only ESTV reference limits are tax-safe\n\nIncome tax: Federal rate max 11.5%; total cantonal + municipal burden varies widely:\n  • Zug: ~16–18% | Zurich: ~24–26% | Bern: ~27–29% | Geneva: ~31–34%\nAHV/AVS social contributions: ~8.7% employee + ~8.7% employer (2025 rates).',
  'te.ch.dom.source': 'No statutory per diem. FTA expense limits: lunch CHF 35 (receipt) or CHF 30 (flat); small daily expenses CHF 20/day; km CHF 0.70/km',
  'te.ch.dom.h.0': 'Category / Method',
  'te.ch.dom.h.1': 'ESTV Reference Limit / Amount',
  'te.ch.dom.h.2': 'Source Type',
  'te.ch.dom.r.0.0': 'No statutory per diem rate',
  'te.ch.dom.r.0.1': 'Switzerland has no government-mandated per diem for private sector — company sets own rates under Art. 327a CO',
  'te.ch.dom.r.0.2': 'Statutory',
  'te.ch.dom.r.1.0': 'Lunch or dinner — no receipt (flat rate)',
  'te.ch.dom.r.1.1': 'CHF 30/meal (ESTV reference limit)',
  'te.ch.dom.r.1.2': 'Tax Authority Guideline',
  'te.ch.dom.r.2.0': 'Lunch or dinner — with receipt (effective)',
