  'te.ch.dom.r.5.1': '3–5% of net annual salary, max CHF 24,000/year (requires cantonal tax authority approval)',
  'te.ch.dom.r.5.2': 'Tax Authority Guideline',
  'te.ch.dom.r.6.0': 'Amounts above ESTV limits without Spesenreglement',
  'te.ch.dom.r.6.1': 'Taxable employment income — subject to federal + cantonal PIT and AHV/AVS',
  'te.ch.dom.r.6.2': 'Statutory',
  'te.ch.dom.r.7.0': 'Federal income tax max rate',
  'te.ch.dom.r.7.1': '11.5% (federal only); total burden varies by canton/municipality',
  'te.ch.dom.r.7.2': 'Statutory',
  'te.ch.intl.title': 'International Business Trips',
  'te.ch.intl.desc': 'For international business trips, the same Code of Obligations framework applies. There is no statutory per diem — the company sets its own rates.\n\nPractical approaches companies use:\n  1. Actual costs (receipts for accommodation, meals, transport)\n  2. Flat-rate per diem in an approved Spesenreglement\n  3. Reference to external benchmarks (US State Dept, UN ICSC, OECD)\n\nCompanies without an approved Spesenreglement should apply the ESTV reference limits as a baseline and document all amounts above that.\n\nUS State Dept per diem for travel TO Switzerland (2025):\n  • Geneva: Lodging USD 358/night + M&IE USD 141/day\n  • Zurich: Lodging USD 350/night + M&IE USD 139/day\n  • Bern: Lodging USD 282/night + M&IE USD 117/day\n\nIRAS Singapore 2025 acceptable rate for Switzerland: SGD 170/day\nPoland Rozporządzenie 2025 rate for Switzerland: CHF 88/day dieta\n\nNote: Switzerland is consistently among the most expensive countries for business travel. Realistic full-day accommodation + meals in Zurich or Geneva exceeds CHF 400/day for most business travelers.',
  'te.ch.intl.source': 'International: same Code of Obligations framework; no statutory per diem rate; company-set amounts with FTA approval or reference to benchmarks',
  'te.ch.intl.h.0': 'Category / Destination',
  'te.ch.intl.h.1': 'Rate / Notes',
  'te.ch.intl.h.2': 'Source Type',
  'te.ch.intl.r.0.0': 'No statutory international per diem',
  'te.ch.intl.r.0.1': 'Same as domestic — Code of Obligations applies; company sets rates',
  'te.ch.intl.r.0.2': 'Statutory',
  'te.ch.intl.r.1.0': 'Geneva — inbound (US State Dept 2025)',
  'te.ch.intl.r.1.1': 'Lodging: USD 358/night + M&IE: USD 141/day',
