  /* ── Tanzania (TZ) ── */
  'te.tz.dom.title': 'Domestic Business Trip',
  'te.tz.dom.desc': 'Tanzania has NO government-mandated per diem rate for private sector employers. Companies set their own travel allowance policies.\n\nTax treatment under the Income Tax Act 2004 (as amended):\n  • Monthly taxable income includes: basic salary, overtime, bonus, commission, allowances and benefits in kind\n  • Genuine business travel reimbursements for official duties — properly documented — are generally treated as non-taxable expense reimbursements\n  • Flat cash allowances paid without documentation or not tied to actual travel duties may be treated as taxable employment income\n\nGovernment reference rates for civil servants (effective July 2022 — still current as of 2025):\n  • Senior officials / directors: TZS 250,000/night (domestic)\n  • Lower-level public servants: TZS 100,000/night (domestic)\n  • Extra duty allowance (lower level): TZS 30,000/day\n  • Extra duty allowance (middle level): TZS 40,000/day\n  • Extra duty allowance (senior level): TZS 60,000/day\n\nPIT rates 2025 (monthly — Income Tax Act 2004):\n  • Up to TZS 270,000/month: 0%\n  • TZS 270,001–520,000: 8%\n  • TZS 520,001–760,000: TZS 20,000 + 20% above 520,000\n  • TZS 760,001–1,000,000: TZS 68,000 + 25% above 760,000\n  • Above TZS 1,000,000: TZS 128,000 + 30% above 1,000,000\n  • Annual tax-free threshold: TZS 3,240,000/year\n\nNSSF contributions: 20% total (10% employer + 10% employee) — no cap.\nSDL (Skills Development Levy): 3.5% employer-only (10+ employee organisations).\nMinimum wage (public sector, July 2025): TZS 500,000/month.',
  'te.tz.dom.source': 'Private sector: no statutory per diem rate. Genuine documented travel reimbursements generally non-taxable under ITA 2004.',
  'te.tz.dom.h.0': 'Category',
  'te.tz.dom.h.1': 'Rate / Treatment',
  'te.tz.dom.h.2': 'Source Type',
  'te.tz.dom.r.0.0': 'Private sector — domestic per diem',
  'te.tz.dom.r.0.1': 'Per company policy — no statutory rate',
  'te.tz.dom.r.0.2': 'Market Practice',
  'te.tz.dom.r.1.0': 'Tax treatment — documented genuine travel reimbursements',
  'te.tz.dom.r.1.1': 'Generally non-taxable under ITA 2004',
  'te.tz.dom.r.1.2': 'Tax Authority Guideline',
  'te.tz.dom.r.2.0': 'Flat undocumented cash allowances',
  'te.tz.dom.r.2.1': 'May be included as taxable employment income',
  'te.tz.dom.r.2.2': 'Statutory',
  'te.tz.dom.r.3.0': 'Govt reference — senior officials / directors',
  'te.tz.dom.r.3.1': 'TZS 250,000/night (eff. July 2022)',
