  'te.tz.dom.r.7.0': 'Govt extra duty — senior level',
  'te.tz.dom.r.7.1': 'TZS 60,000/day',
  'te.tz.dom.r.7.2': 'Government Benchmark',
  'te.tz.dom.r.8.0': 'Annual tax-free threshold (PAYE)',
  'te.tz.dom.r.8.1': 'TZS 3,240,000/year (TZS 270,000/month) — 0% below this',
  'te.tz.dom.r.8.2': 'Statutory',
  'te.tz.dom.r.9.0': 'Minimum wage (public sector, July 2025)',
  'te.tz.dom.r.9.1': 'TZS 500,000/month',
  'te.tz.dom.r.9.2': 'Statutory',
  'te.tz.intl.title': 'International Business Trips',
  'te.tz.intl.desc': 'For international travel, the same ITA 2004 framework applies. Properly documented genuine business travel reimbursements are generally non-taxable.\n\nGovernment reference for civil servants traveling abroad (from historical scale, unchanged since approximately 2015 for foreign travel):\n  • Senior officials (directors and above): USD 420/day\n  • Mid-level officers: USD 365/day\n  • Note: These are older rates — verify current rates with Tanzania President\'s Office for Public Service Management\n\nU.S. State Department per diem for travel TO Tanzania (2025):\n  • Dar es Salaam: Lodging USD 150/night + M&IE USD 78/day\n  • Arusha: Lodging USD 130/night + M&IE USD 71/day\n\nIRAS Singapore 2025 acceptable rate for Tanzania: SGD 115/day\n\nPrivate sector practice: Most international companies operating in Tanzania reference US State Dept rates or UN ICSC DSA rates for international travel. USD is widely used for international travel budgeting.',
  'te.tz.intl.source': 'Government per diem (2022 update, still current 2025): senior officials TZS 250,000/night; lower-level TZS 100,000/night',
  'te.tz.intl.h.0': 'Destination / Category',
  'te.tz.intl.h.1': 'Rate / Notes',
  'te.tz.intl.h.2': 'Source Type',
  'te.tz.intl.r.0.0': 'Dar es Salaam — inbound (US State Dept 2025)',
  'te.tz.intl.r.0.1': 'Lodging: USD 150/night + M&IE: USD 78/day',
