  /* ── Thailand (TH) ── */
  'te.th.dom.title': 'Domestic Business Trip',
  'te.th.dom.desc': 'Thailand has NO government-mandated per diem rate for private sector employers. Companies set their own business travel policies.\n\nTax treatment under the Revenue Code (Section 42(1)):\n  • Per diem (ค่าเบี้ยเลี้ยง) and transport expenses spent wholly, necessarily, and exclusively in the performance of employment duties are NOT assessable income — therefore not subject to Personal Income Tax (PIT)\n  • This applies regardless of the amount — there is no published cap\n  • Key condition: amounts must be spent in good faith, wholly and necessarily for carrying out job duties\n  • If amounts appear excessive or personal in nature, they may be treated as assessable employment income by the Revenue Department\n\nPractical guidance:\n  • Reimbursement of actual receipted travel costs: non-taxable\n  • Fixed flat-rate per diem (within reasonable limits): non-taxable\n  • Excessive or undocumented flat payments: may be taxable\n\nGovernment reference (civil servants — Finance Ministry):\n  • Domestic per diem scales based on grade\n  • General employees: THB 240–480/day\n  • Senior officials: THB 480–720/day\n\nPIT rates 2025: Progressive 5%–35%\n  • Up to THB 150,000: exempt | THB 150K–300K: 5% | THB 300K–500K: 10%\n  • THB 500K–750K: 15% | THB 750K–1M: 20% | THB 1M–2M: 25%\n  • THB 2M–5M: 30% | Above THB 5M: 35%\n\nMinimum wage (Oct 2024): THB 363/day (Bangkok and major provinces).',
  'te.th.dom.source': 'Per diem and transport expenses spent wholly and necessarily in carrying out duties are NOT assessable income (Revenue Code Sec. 42(1))',
  'te.th.dom.h.0': 'Category',
  'te.th.dom.h.1': 'Rate / Treatment',
  'te.th.dom.h.2': 'Source Type',
  'te.th.dom.r.0.0': 'Per diem — spent wholly and necessarily for employment duties',
  'te.th.dom.r.0.1': 'NOT assessable income — exempt from PIT (Revenue Code Sec. 42(1))',
  'te.th.dom.r.0.2': 'Statutory',
  'te.th.dom.r.1.0': 'No statutory per diem rate for private sector',
