  'te.th.dom.r.4.2': 'Government Benchmark',
  'te.th.dom.r.5.0': 'IBC regime employees (special)',
  'te.th.dom.r.5.1': '15% flat PIT rate on employment income from qualifying IBC activities',
  'te.th.dom.r.5.2': 'Statutory',
  'te.th.dom.r.6.0': 'PIT rates 2025',
  'te.th.dom.r.6.1': 'Progressive 0%–35%: exempt up to THB 150K; 5%–35% above',
  'te.th.dom.r.6.2': 'Statutory',
  'te.th.intl.title': 'International Business Trips',
  'te.th.intl.desc': 'For international business travel, the same Revenue Code Section 42(1) framework applies. Per diem spent wholly and necessarily for employment duties is not assessable income.\n\nNo government-published table exists for private sector international rates.\n\nU.S. State Department per diem for travel TO Thailand (2025):\n  • Bangkok: Lodging USD 165/night + M&IE USD 75/day\n  • Other Thailand (Chiang Mai, Phuket): lower rates — verify at State Dept\n\nIRAS Singapore 2025 acceptable rate for Thailand: SGD 110/day\n\nPrivate sector benchmarks for Thai employees traveling abroad:\n  • United States / Western Europe: USD 250–380/day\n  • Japan / Singapore / Australia: USD 200–300/day\n  • Regional Asia (China, ASEAN): USD 150–250/day\n\nNote: Thailand introduced a new LTR (Long-Term Resident) visa scheme and IBC (International Business Centre) tax regime in 2022. Employees under the IBC scheme may be subject to a reduced 15% flat income tax rate.',
  'te.th.intl.source': 'International: same framework — wholly and necessarily incurred per diems are non-taxable; company sets own international rates',
  'te.th.intl.h.0': 'Destination / Category',
  'te.th.intl.h.1': 'Rate / Notes',
