  /* ── Turkey (TR) ── */
  'te.tr.dom.title': 'Domestic Business Trip — Harcırah (Yurt İci)',
  'te.tr.dom.desc': 'Turkey has STATUTORY tax-exempt per diem (harcırah) ceilings under Article 24 of the Income Tax Law (Gelir Vergisi Kanunu). The ceilings are updated semi-annually (January–June and July–December) by the Ministry of Finance based on civil servant salary coefficients published in the Central Government Budget Law.\n\nDomestic harcırah (within Turkey) — 2025 rates:\n  • For employees with gross monthly salary up to TRY 25,467.70:\n    Tax-exempt ceiling: TRY 686/day (Jan–Jun 2025)\n  • Higher salary bands have proportionally higher tax-exempt ceilings\n  • Source: Central Government Budget Law Annex H (Official Gazette No. 32769, 31 Dec 2024) and Income Tax Law Communique No. 323 — 2025 I. Period\n\nKey rules:\n  • Amounts within the tax-exempt ceiling: NOT subject to income tax or social security contributions\n  • Amounts ABOVE the ceiling: treated as taxable salary income — subject to progressive income tax (15%–40% in 2025) and social security\n  • Rates are updated semi-annually — ALWAYS verify the current period at gib.gov.tr\n\nIncome tax (PIT) brackets 2025 (cumulative — calendar year):\n  • Up to TRY 158,000: 15%\n  • TRY 158,001–330,000: 20%\n  • TRY 330,001–800,000: 27%\n  • TRY 800,001–4,300,000: 35%\n  • Above TRY 4,300,000: 40%\n\nMinimum wage 2025: TRY 26,005.50 gross/month. Social security (SGK): employer 20.75% + employee 14% of gross (subject to ceiling).',
  'te.tr.dom.source': 'Semi-annual updates: coefficients set by Ministry of Finance. Jan-Jun 2025: TRY 686/day (salary band TRY 25,467.70/month gross). Updated each H1/H2.',
  'te.tr.dom.h.0': 'Category',
  'te.tr.dom.h.1': 'Rate / Treatment',
  'te.tr.dom.h.2': 'Source Type',
  'te.tr.dom.r.0.0': 'Domestic harcırah — Jan–Jun 2025 (salary band ~TRY 25,467.70 gross/month)',
  'te.tr.dom.r.0.1': 'TRY 686/day tax-exempt ceiling',
