  'te.tr.dom.r.6.1': 'TRY 26,005.50 gross/month',
  'te.tr.dom.r.6.2': 'Statutory',
  'te.tr.intl.title': 'International Business Trips — Harcırah (Yurt Dışı)',
  'te.tr.intl.desc': 'For international business trips, Turkey publishes country-specific harcırah rates in a Presidential Council Decision published in the Official Gazette semi-annually.\n\nInternational harcırah rates — Jan–Jun 2025:\n  • For employees with gross monthly salary ABOVE TRY 35,907.57:\n    Individual rates per country (in USD or EUR) — same ceiling applies\n    Source: Presidential Decision No. 9396 published in Official Gazette No. 32779 dated 11 January 2025\n\n  • For employees with gross monthly salary BELOW TRY 35,907.57:\n    Rates are set proportionally lower based on the salary band\n\nTax treatment:\n  • Within the published country-specific ceilings: NOT subject to PIT or social security contributions\n  • Above published ceilings: taxable salary income\n\nSelected reference rates (Jan–Jun 2025 — for senior salary band above TRY 35,907.57 gross/month — USD or EUR/day):\nNote: These are the MAXIMUM tax-free amounts. Always verify the current semi-annual update at gib.gov.tr or the Official Gazette.\n\nUS State Dept per diem for travel TO Turkey (2025):\n  • Istanbul: Lodging USD 180/night + M&IE USD 89/day\n  • Ankara: Lodging USD 158/night + M&IE USD 81/day',
  'te.tr.intl.source': 'International per diem: salary band above TRY 35,907.57/month gross: separate USD/EUR amounts per country (Official Gazette No. 32779, 11 Jan 2025)',
