  /* ── Ukraine (UA) ── */
  'te.ua.dom.title': 'Domestic Business Trip — Dobovi',
  'te.ua.dom.desc': 'Ukraine has statutory per diem (dobovi) limits under Tax Code Article 170.9. These are the maximum tax-free amounts for employee business trips.\n\nDomestic per diem (dobovi) — from 1 January 2025:\n  • Up to UAH 800/day (non-taxable)\n  • Calculated as 0.1 x minimum wage per day\n  • Minimum wage from 1 January 2025: UAH 8,000/month\n  • Therefore: 0.1 x UAH 8,000 = UAH 800/day\n\nTax treatment:\n  • Within UAH 800/day: NOT subject to PIT (18%), military tax (5%), or Unified Social Contribution (USC, 22% employer)\n  • Above UAH 800/day: excess is taxable income — subject to PIT 18% + military tax 5% = effective 23% on the excess\n\nCRITICAL CONTEXT — Martial Law:\n  • Ukraine has been under martial law since February 2022\n  • Military tax was raised from 1.5% to 5% effective 1 December 2024 (Law 4015-IX)\n  • Military tax applies to all taxable income of individuals\n  • Per diem amounts exceeding the statutory ceiling are subject to both PIT (18%) and military tax (5%)\n\nPIT rate: Flat 18% on employment income. Military tax: 5% (from Dec 2024).\nMinimum wage: UAH 8,000/month (Jan 2025). UAH exchange: USD 1 ≈ UAH 41–42 (2025).',
  'te.ua.dom.source': 'Forvis Mazars Ukraine: domestic dobovi = UAH 800/day from 1 Jan 2025 (0.1 x minimum wage). International: EUR 80/calendar day (unchanged).',
  'te.ua.dom.h.0': 'Category',
  'te.ua.dom.h.1': 'Rate / Treatment',
  'te.ua.dom.h.2': 'Source Type',
  'te.ua.dom.r.0.0': 'Domestic per diem (dobovi) — from 1 Jan 2025',
  'te.ua.dom.r.0.1': 'UAH 800/day (0.1 x UAH 8,000 minimum wage) — tax-free ceiling',
  'te.ua.dom.r.0.2': 'Statutory',
  'te.ua.dom.r.1.0': 'Amounts within UAH 800/day',
  'te.ua.dom.r.1.1': 'NOT subject to PIT (18%), military tax (5%), or USC',
  'te.ua.dom.r.1.2': 'Statutory',
  'te.ua.dom.r.2.0': 'Amounts above UAH 800/day',
  'te.ua.dom.r.2.1': 'Taxable income — PIT 18% + military tax 5% on excess',
  'te.ua.dom.r.2.2': 'Statutory',
  'te.ua.dom.r.3.0': 'Military tax rate (from 1 Dec 2024 — Law 4015-IX)',
  'te.ua.dom.r.3.1': '5% on all taxable income (increased from 1.5%)',
  'te.ua.dom.r.3.2': 'Statutory',
  'te.ua.dom.r.4.0': 'PIT rate',
  'te.ua.dom.r.4.1': 'Flat 18% on employment income after deductions',
  'te.ua.dom.r.4.2': 'Statutory',
  'te.ua.dom.r.5.0': 'Minimum wage (Jan 2025)',
  'te.ua.dom.r.5.1': 'UAH 8,000/month (sets the dobovi ceiling as 0.1 x this amount)',
  'te.ua.dom.r.5.2': 'Statutory',
  'te.ua.intl.title': 'International Business Trips',
  'te.ua.intl.desc': 'For international business trips, Ukraine sets a fixed EUR-denominated tax-free per diem ceiling under Tax Code Article 170.9.\n\nInternational per diem (dobovi) ceiling:\n  • Up to EUR 80 per calendar day (non-taxable)\n  • Converted to UAH at the NBU (National Bank of Ukraine) official exchange rate for each day\n  • This ceiling has remained unchanged despite the domestic rate increase\n\nTax treatment:\n  • Within EUR 80/day: NOT subject to PIT (18%) or military tax (5%)\n  • Above EUR 80/day: taxable — PIT 18% + military tax 5%\n\nDocumentation requirements:\n  • Trip order (nakazatel pro komandiruvannya) required\n  • Expense report after return\n  • Receipts for accommodation and transport\n\nU.S. State Department per diem for travel TO Ukraine (2025):\n  • Kyiv: Lodging USD 150/night + M&IE USD 78/day\n  • Note: Travel safety conditions — consult your government\'s travel advisories\n\nIRAS Singapore 2025 acceptable rate for Ukraine: SGD 110/day',
  'te.ua.intl.source': 'Military tax: increased from 1.5% to 5% effective 1 December 2024 (Law 4015-IX) — applies on PIT taxable income including per diem above the ceiling',
