  /* ── United Arab Emirates (AE) ── */
  'te.ae.dom.title': 'Domestic Business Trip — UAE',
  'te.ae.dom.desc': 'The UAE has NO personal income tax. ALL employee compensation — including salaries, bonuses, allowances, and per diems — is fully non-taxable for employees. There is also NO mandatory per diem rate for private sector employers.\n\nLegal framework:\n  • Federal Labour Law: Decree-Law No. 33 of 2021 (UAE Labour Law)\n  • Does NOT prescribe mandatory per diem amounts for private sector travel\n  • Employers are free to set their own per diem and travel allowance policies\n\nGOSI / Social Security note:\n  • UAE nationals: GPSSA (General Pension and Social Security Authority) contributions apply — employer 12.5% + employee 5% + 2.5% state contribution\n  • Expatriates: NO social security contributions — no GPSSA entitlement\n  • Per diem and travel allowances are generally NOT included in the GPSSA base\n\nUAE Corporate Tax (CIT) — from June 2023:\n  • 9% CIT on taxable business profits above AED 375,000/year\n  • This is a business tax — does NOT affect employee per diems or allowances\n  • Employee travel reimbursements are deductible corporate expenses\n\nTypical private sector per diem benchmarks:\n  • Senior executives: AED 500–1,500/day domestic\n  • Mid-level managers: AED 300–800/day\n  • Standard employees: AED 150–400/day\n\nMinimum salary for Emirati nationals (private sector, from Jan 2026): AED 6,000/month.',
  'te.ae.dom.source': 'No personal income tax in UAE. No mandatory per diem rate. All employment compensation — including allowances and per diems — is fully non-taxable for employees.',
