  'te.ae.dom.r.8.2': 'Statutory',
  'te.ae.intl.title': 'International Business Trips',
  'te.ae.intl.desc': 'For international business travel from the UAE, the same no-personal-income-tax framework applies. All per diem payments are fully non-taxable for employees.\n\nCompanies in the UAE commonly reference U.S. State Department or UN ICSC rates as benchmarks for international travel policies.\n\nU.S. State Department per diem for travel TO UAE (2025):\n  • Dubai: Lodging USD 275/night + M&IE USD 110/day\n  • Abu Dhabi: Lodging USD 225/night + M&IE USD 99/day\n  • Sharjah / Other UAE: Lodging USD 185/night + M&IE USD 86/day\n\nIRAS Singapore 2025 acceptable rate for UAE: SGD 175/day\n\nTypical international per diem for UAE-based employees traveling abroad:\n  • United States / Western Europe: USD 280–400/day\n  • Japan / Singapore / Australia: USD 250–350/day\n  • Asia-Pacific (excl. Japan/Sing/Aus): USD 150–250/day\n  • Africa / South Asia / Latin America: USD 120–200/day\n\nEnd-of-service note: UAE end-of-service gratuity (EOSB) is calculated on basic salary only — per diems and allowances do NOT increase gratuity liability.',
  'te.ae.intl.source': 'UAE introduced 9% Corporate Tax from June 2023. This applies to business profits only — NOT to employee per diems or allowances.',
  'te.ae.intl.h.0': 'Destination / Category',
  'te.ae.intl.h.1': 'Rate / Notes',
  'te.ae.intl.h.2': 'Source Type',
