  /* ── United Kingdom (GB) ── */
  'te.gb.dom.title': 'Domestic Business Trip — HMRC Benchmark Scale Rates',
  'te.gb.dom.desc': 'The UK has NO statutory per diem. HMRC publishes benchmark scale rates as advisory safe-harbour amounts. Payments within these rates are tax-free (exempt from PAYE and NIC) without requiring receipts.\n\nHMRC domestic benchmark scale rates (2025/26 — unchanged from 2024/25):\n  • Over 5 hours absence: GBP 5 (meal allowance)\n  • Over 10 hours absence: GBP 10 (meal allowance)\n  • Over 15 hours AND travel continuing after 8pm: GBP 25\n  • Additional late evening meal rate (travel after 8pm): GBP 10\n  • Overnight incidental expenses: GBP 25/night\n\nConditions for tax-free treatment:\n  1. Travel must be in performance of duties OR to a temporary workplace\n  2. Employee must be absent from normal workplace for 5+ or 10+ hours\n  3. Employee must have INCURRED a meal cost during the journey\n  4. An employee can only be reimbursed once per meal\n\nAccommodation:\n  • NO HMRC benchmark rate for accommodation — must use actual receipted costs\n  • OR employer may apply for a bespoke rate agreement with HMRC\n\nMileage Allowance Payments (MAPs — Approved Amount):\n  • Car/van: 45p/mile (first 10,000 miles per tax year), 25p/mile thereafter\n  • Motorcycle: 24p/mile | Bicycle: 20p/mile\n\nPayments ABOVE benchmark rates: taxable and subject to NIC unless a bespoke higher rate has been agreed with HMRC under an exemption application.\n\nIncome tax (2025/26): Personal allowance GBP 12,570. Rates: 20%/40%/45%.',
  'te.gb.dom.source': 'HMRC EIM05210/EIM05220: benchmark scale rates (domestic); conditions: 5h/10h/15h absence; employee must have incurred meal cost; receipt not required for flat rates',
  'te.gb.dom.h.0': 'Category / Duration',
  'te.gb.dom.h.1': 'HMRC Rate (GBP — 2025/26)',
