  'te.gb.intl.title': 'International Business Trips — HMRC Worldwide Subsistence Rates',
  'te.gb.intl.desc': 'For international business trips, HMRC publishes Worldwide Subsistence Rates — city-specific tables updated annually. These replace the need for receipts when paying subsistence to employees traveling outside the UK.\n\nStructure of HMRC overseas rates (per city):\n  1. Over 5 hours: flat meal allowance\n  2. Over 10 hours: higher flat meal allowance\n  3. 24-hour rate: covers breakfast, lunch, dinner, drinks, and hotel-to-office transport\n  4. Room rate: accommodation ceiling per night\n\nKey rules:\n  • Employee must have incurred the expense\n  • Rate applies to the city where most of the business day is spent\n  • Amounts above HMRC overseas rates: taxable + NIC unless bespoke rate agreed\n  • For locations not listed: use the nearest city shown in the HMRC table\n\nSelected HMRC overseas rates (2025/26 — from gov.uk):\nAll values in local currency unless stated. Full table at gov.uk.',
  'te.gb.intl.source': 'HMRC overseas scale rates: per city/country; 5-hour, 10-hour, 24-hour + room rate components; published annually; updated for 2025/26 tax year',
