  /* ── United States (US) ── */
  'te.us.dom.title': 'Domestic Business Travel — GSA CONUS Per Diem',
  'te.us.dom.desc': 'The United States has a comprehensive per diem system. Federal employees must use GSA (General Services Administration) rates. Private sector employers may choose their own rates, but using GSA/IRS-approved rates provides automatic tax-free treatment for employees.\n\nGSA CONUS per diem rates — FY 2026 (effective 1 October 2025 – 30 September 2026):\n  • Standard CONUS lodging rate: USD 110/night\n  • Standard CONUS M&IE (Meals and Incidental Expenses): USD 68/day\n  • Standard total: USD 178/day (unchanged from FY 2025 — GSA Bulletin FTR 26-01)\n\nNote on Non-Standard Areas (NSAs):\n  • ~300 high-cost localities have higher rates (e.g., Manhattan USD 342 lodging)\n  • M&IE for NSAs: USD 68–92/day depending on location\n  • First and last day of travel: 75% of M&IE rate applies\n\nIRS tax treatment for private sector (Accountable Plan):\n  • Per diem paid within GSA rates under an accountable plan: NOT taxable income for the employee — no income tax or FICA\n  • Accountable plan requires: business purpose, substantiation of expenses, return of excess advances within a reasonable time\n  • Per diem ABOVE GSA rates: excess is taxable compensation — subject to federal income tax and FICA\n\nIRS High-Low Per Diem Method (alternative for private sector):\n  • FY 2026 (Oct 1 2025 – Sep 30 2026):\n    High-cost areas: USD 319/day (USD 233 lodging + USD 86 M&IE)\n    Low-cost areas: USD 225/day (USD 151 lodging + USD 74 M&IE)\n\nMileage reimbursement: IRS standard rate 67 cents/mile (2024 — verify 2025/2026 update).',
  'te.us.dom.source': 'GSA FY2026 standard CONUS rate: $178/day ($110 lodging + $68 M&IE). Rates unchanged from FY2025 (GSA Bulletin FTR 26-01).',
