  'te.us.intl.title': 'International Business Travel — State Dept OCONUS Rates',
  'te.us.intl.desc': 'For international business travel, the U.S. Department of State publishes OCONUS (Outside Continental US) per diem rates updated monthly at aoprals.state.gov. These include lodging + M&IE amounts for 150+ countries and thousands of cities.\n\nStructure: Lodging (actual up to ceiling) + M&IE (flat daily allowance)\n\nIRS tax treatment (private sector):\n  • Per diem at or below State Dept rates under an accountable plan: non-taxable\n  • Amounts above State Dept rates: taxable compensation\n\nSelected State Dept per diem rates — FY 2025/2026 (current):\n(Note: State Dept rates are updated monthly — verify at aoprals.state.gov)',
  'te.us.intl.source': 'IRS: private sector accountable plan rules — per diem at or below GSA/State Dept rates is non-taxable for employees (IRS Pub. 463)',
