  /* ── Uzbekistan (UZ) ── */
  'te.uz.dom.title': 'Domestic Business Trip',
  'te.uz.dom.desc': 'Uzbekistan has statutory per diem (komandirovochnye / sutochnie) norms set by the Tax Code and Cabinet of Ministers decisions. Per diems within these statutory norms are not subject to Personal Income Tax (PIT).\n\nTax treatment under the Uzbekistan Tax Code:\n  • Per diem and travel reimbursements within statutory norms: NOT included in taxable employment income\n  • Per diems EXCEEDING statutory norms: treated as taxable employment income — subject to flat 12% PIT and social tax contributions\n\nStatutory norm rates:\n  • Domestic: up to 2 times the Base Calculation Value (BCV) per day\n  • BCV (Bazovaya Raschetnaya Velichina) 2025: UZS 375,000\n  • Therefore domestic ceiling: 2 x UZS 375,000 = UZS 750,000/day\n  • Note: BCV is updated by government decree — verify at soliq.uz\n\nAccommodation: reimbursed separately at actual receipted cost.\nTransport: reimbursed at actual cost with supporting documents.\n\nIncome tax 2025: Flat 12% PIT on all employment income (introduced Jan 2023).\nSocial tax (employer): 12% on gross salary.\nPension contribution (employee): 1% of gross salary.\nMinimum wage: UZS 1,200,000/month (as of August 2025).\nUZS exchange rate: USD 1 ≈ UZS 12,700–12,900 (2025).',
  'te.uz.dom.source': 'Per diems within statutory norms: non-taxable. Per diems exceeding statutory norms: taxable employment income (PwC Uzbekistan Income Determination). Flat PIT rate: 12%.',
  'te.uz.dom.h.0': 'Category',
  'te.uz.dom.h.1': 'Rate / Treatment',
  'te.uz.dom.h.2': 'Source Type',
  'te.uz.dom.r.0.0': 'Domestic per diem within statutory norm',
  'te.uz.dom.r.0.1': 'Up to 2x BCV/day = UZS 750,000/day (2025 BCV = UZS 375,000 — verify annually)',
  'te.uz.dom.r.0.2': 'Statutory',
  'te.uz.dom.r.1.0': 'Amounts within 2x BCV ceiling',
