  'te.uz.dom.r.6.1': '12% on gross salary',
  'te.uz.dom.r.6.2': 'Statutory',
  'te.uz.dom.r.7.0': 'Minimum wage (from Aug 2025)',
  'te.uz.dom.r.7.1': 'UZS 1,200,000/month',
  'te.uz.dom.r.7.2': 'Statutory',
  'te.uz.intl.title': 'International Business Trips',
  'te.uz.intl.desc': 'For international business trips, the same Uzbekistan Tax Code framework applies. Per diems within statutory norms are non-taxable.\n\nInternational per diem statutory norm:\n  • Typically expressed in USD equivalent or as a multiple of BCV\n  • Companies often reference government rates for civil servants traveling abroad or use US State Dept rates as a benchmark\n\nU.S. State Department per diem for travel TO Uzbekistan (2025):\n  • Tashkent: Lodging USD 135/night + M&IE USD 60/day\n\nIRAS Singapore 2025 acceptable rate for Uzbekistan: SGD 85/day\n\nPrivate sector benchmarks for Uzbekistan-based employees traveling abroad:\n  • United States / Western Europe: USD 250–380/day\n  • Russia / CIS countries: USD 80–180/day\n  • China / East Asia: USD 150–250/day\n  • Middle East / Gulf: USD 150–250/day\n\nNote: Uzbekistan\'s economy has been growing rapidly (~5–6% annually). Tax and social contribution rates have been reformed since 2023. Always verify current BCV and statutory norms at soliq.uz.',
  'te.uz.intl.source': 'International: same Tax Code framework — per diems within statutory norms are non-taxable. Amounts above norms subject to 12% PIT.',
  'te.uz.intl.h.0': 'Destination / Category',
  'te.uz.intl.h.1': 'Rate / Notes',
  'te.uz.intl.h.2': 'Source Type',
  'te.uz.intl.r.0.0': 'Tashkent — inbound (US State Dept 2025)',
