  /* ── Vietnam (VN) ── */
  'te.vn.dom.title': 'Domestic Business Trip — Cong Tac Phi',
  'te.vn.dom.desc': 'Vietnam has NO government-mandated per diem rate for private sector employers. Companies set their own travel allowance policies.\n\nTax treatment under the Personal Income Tax Law and Circular 111/2013/TT-BTC:\n  • Per diem (cong tac phi) and travel expenses spent wholly, exclusively and necessarily in carrying out employment duties are NOT assessable income\n  • This means they are NOT subject to PIT (Personal Income Tax)\n  • The expenses must be genuine, for business purposes, and supported by appropriate documentation\n\nRelated non-taxable allowances (specific caps apply):\n  • Lunch allowance: VND 730,000/day is the previous benchmark (companies may set their own reasonable amount per current guidance)\n  • Uniform allowance: up to VND 5,000,000/year if paid in cash; unlimited if provided in kind\n  • Phone allowance: within company policy limits\n\nPIT rates 2025 (resident — progressive 5%–35%):\n  • Up to VND 60M/month: 5% | VND 60M–120M: 10% | VND 120M–216M: 15%\n  • VND 216M–384M: 20% | VND 384M–624M: 25% | VND 624M–960M: 30%\n  • Above VND 960M/month: 35%\n\nIMPORTANT — 2025 PIT Law reform:\n  • National Assembly passed amendments raising personal deduction from VND 11M to VND 15.5M/month\n  • PIT brackets reduced from 7 to 5 tiers with revised thresholds\n  • Verify effective date and implementing decree at gdt.gov.vn\n\nMinimum wage (Region I — Ho Chi Minh City, from 1 Jul 2024): VND 4,960,000/month.',
  'te.vn.dom.source': 'Travel expenses (cong tac phi) spent wholly and necessarily for employment duties are NOT assessable income. Circular 111/2013/TT-BTC, as updated.',
  'te.vn.dom.h.0': 'Category',
  'te.vn.dom.h.1': 'Rate / Treatment',
  'te.vn.dom.h.2': 'Source Type',
  'te.vn.dom.r.0.0': 'Per diem (cong tac phi) — spent wholly and necessarily for duties',
  'te.vn.dom.r.0.1': 'NOT assessable income — exempt from PIT (Circular 111/2013/TT-BTC)',
  'te.vn.dom.r.0.2': 'Statutory',
  'te.vn.dom.r.1.0': 'No statutory per diem rate for private sector',
  'te.vn.dom.r.1.1': 'Company sets own rates; GDT assesses reasonableness',
