  'te.vn.dom.r.2.0': 'Lunch allowance — previous benchmark',
  'te.vn.dom.r.2.1': 'VND 730,000/day (previous reference — companies may use own reasonable amount)',
  'te.vn.dom.r.2.2': 'Tax Authority Guideline',
  'te.vn.dom.r.3.0': 'Uniform allowance — paid in cash',
  'te.vn.dom.r.3.1': 'Up to VND 5,000,000/year — tax-free',
  'te.vn.dom.r.3.2': 'Statutory',
  'te.vn.dom.r.4.0': 'Excessive or non-business amounts',
  'te.vn.dom.r.4.1': 'Treated as assessable employment income — subject to PIT 5%–35%',
  'te.vn.dom.r.4.2': 'Statutory',
  'te.vn.dom.r.5.0': 'PIT personal deduction (current)',
  'te.vn.dom.r.5.1': 'VND 11,000,000/month (VND 15,500,000/month under 2025 reform — verify effective date)',
  'te.vn.dom.r.5.2': 'Statutory',
  'te.vn.dom.r.6.0': '2025 PIT Law reform',
  'te.vn.dom.r.6.1': 'Personal deduction raised to VND 15.5M/month; brackets reduced from 7 to 5 tiers (verify effective date at gdt.gov.vn)',
  'te.vn.dom.r.6.2': 'Statutory',
  'te.vn.intl.title': 'International Business Trips',
  'te.vn.intl.desc': 'For international business travel, the same PIT Law framework applies. Per diem spent wholly and necessarily for employment duties is not assessable income.\n\nNo government-published table exists for private sector international rates.\n\nU.S. State Department per diem for travel TO Vietnam (2025):\n  • Hanoi: Lodging USD 153/night + M&IE USD 81/day\n  • Ho Chi Minh City: Lodging USD 168/night + M&IE USD 84/day\n\nIRAS Singapore 2025 acceptable rate for Vietnam: SGD 70/day\n\nPrivate sector benchmarks for Vietnam-based employees traveling abroad:\n  • United States / Western Europe: USD 250–380/day\n  • Japan / South Korea / Singapore / Australia: USD 200–300/day\n  • Regional Asia (China, ASEAN): USD 120–200/day\n\nSocial insurance: employee contributes 8% to SI fund (capped at 20x basic salary = VND 46,800,000). Employer SI total: ~17.5%. Travel per diem is NOT included in the SI calculation base.',
  'te.vn.intl.source': 'Vietnam 2025 PIT Law amendments: personal deduction raised from VND 11M to VND 15.5M/month; brackets from 7 to 5 tiers (effective date pending)',
